export const articles: Article[] = [
  {
    slug: 'scala-2-to-scala-3', title: 'Should you migrate from Scala 2 to Scala 3?', category: 'Scala', topic: 'Scala', readTime: '15 min read',
    summary: 'A technical decision guide to compatibility, macros, dependencies, compiler migration modes, cross-building and a staged route from Scala 2.13 to Scala 3.',
    sections: [
      { heading: 'Scala 2.13 is not about to stop working', paragraphs: ['Migration should begin with a reason, not an assumed deadline. Scala 2.13 remains maintained, including security work, new JVM compatibility and continued interoperability with Scala 3. A service is not automatically at risk simply because its compiler has a 2 in the version.', 'The stronger reasons are local to the system: a library has moved its development to Scala 3, new internal modules need to share Scala 3 code, Scala 2-specific tooling is blocking JDK or framework upgrades, or the team expects enough future development to benefit from the newer language and ecosystem.', 'A stable Scala 2.13 service approaching retirement may be better left alone. A product expected to change for another five years has a different cost curve. Compare migration with the cost of staying: dependency availability, hiring, build friction, security response and the number of changes the team expects to make.'], bullets: ['What concrete constraint does Scala 3 remove?', 'How long will the service continue to change?', 'Which supported library or framework versions are required?', 'Who will own the migrated code and build?'] },
      { heading: 'Identify the real starting point', paragraphs: ['The supported migration path starts from Scala 2.13. If the application is on 2.11 or 2.12, moving to 2.13 is a separate migration with its own collection, dependency and framework compatibility work. Do not hide that work inside a single 2-to-3 estimate.', 'Record the Scala binary version for every module, the JDK used locally and in CI, the sbt version, framework versions, compiler plugins, sbt plugins and internal artifacts. Run the build from a clean checkout. A migration plan based on a developer’s warm dependency cache is not yet reproducible.', 'Also establish which failures already exist. Warnings, flaky tests, eviction messages and generated-source differences need a baseline so they are not incorrectly attributed to the new compiler.'], code: { label: 'Interrogate the build before editing it', language: 'sbt shell', source: 'show scalaVersion\nshow javaHome\nshow sbtVersion\nplugins\nshow Compile / scalacOptions\ndependencyTree\nevicted\nclean\nTest / test' } },
      { heading: 'Dependencies determine whether migration is feasible', paragraphs: ['Scala dependencies are normally published for a particular binary line. In sbt, the double-percent operator selects the artifact for the project’s Scala binary version. Changing scalaVersion therefore changes the artifact coordinates sbt resolves, even when every declared library version stays the same.', 'The Scala 3 compiler can read signatures from many libraries compiled for Scala 2.13. That compatibility is useful during a staged migration, but it is not universal. A Scala 3 compiler cannot expand a Scala 2.13 macro. Scala 2 compiler plugins cannot run inside Scala 3, and code that relies on scala-reflect must be replaced or isolated.', 'Build a compatibility table before touching application syntax. Include direct and transitive macro libraries, compiler plugins introduced by sbt plugins, generated-code tools, test frameworks and private libraries. One abandoned internal macro can matter more than fifty ordinary dependencies.'], bullets: ['Is a Scala 3 artifact published for the required library version?', 'Does the dependency expose Scala 2 macros at compile time?', 'Does an sbt plugin inject a Scala 2 compiler plugin?', 'Is scala-reflect present directly or transitively?', 'Can an internal library be cross-built before the application moves?'], code: { label: 'Use a Scala 2.13 artifact only as a deliberate bridge', language: 'scala / sbt', source: 'libraryDependencies +=\n  ("com.example" %% "domain-model" % domainVersion)\n    .cross(CrossVersion.for3Use2_13)\n\n// This can bridge an ordinary 2.13 library while it is ported.\n// It cannot make a Scala 2 macro expandable by the Scala 3 compiler.' } },
      { heading: 'Make Scala 2.13 warn about Scala 3 first', paragraphs: ['Before changing compilers, enable Scala 2.13’s Scala 3 source mode. The -Xsource:3 option reports constructs whose meaning changes or which will not compile under Scala 3. Recent Scala 2.13 releases also understand selected Scala 3 syntax, which can reduce the amount of version-specific source in a cross-build.', 'Introduce the option on the existing compiler and review every diagnostic. It can initially be useful to report the migration category as warnings so the team sees the complete set; later, fail the build on newly introduced migration problems.', 'This is also the point to add explicit result types to public methods and values. Scala 3 has a redesigned inference algorithm, so leaving public APIs inferred can produce source or binary changes that are hard to distinguish from the intended migration.'], code: { label: 'Enable migration diagnostics only for Scala 2.13', language: 'scala / sbt', source: 'scalacOptions ++= {\n  if (scalaBinaryVersion.value == "2.13")\n    Seq(\n      "-Xsource:3",\n      "-Wconf:cat=scala3-migration:w",\n      "-deprecation",\n      "-feature"\n    )\n  else Seq.empty\n}' } },
      { heading: 'Compile with Scala 3 before adopting Scala 3 style', paragraphs: ['The first goal is not enums, indentation syntax or a new effect library. It is to compile the existing program with the Scala 3 compiler while changing as little behaviour as possible. Mixing a language migration, architecture refactor and dependency redesign removes the ability to explain a failure.', 'Scala 3 provides a migration source mode that accepts many dropped constructs with warnings. When the project compiles, the compiler can rewrite a number of those constructs automatically. Run rewrites only on a clean, committed worktree because they modify source files and apply as a set rather than as individually selected fixes.', 'Automatic rewriting handles syntax, not application semantics. Review the diff, compile again without migration mode, and keep generated sources out of the manual edit path. Remaining failures usually expose changed type inference, implicit resolution, macros or APIs rather than punctuation.'], code: { label: 'Use migration mode as a temporary compiler stage', language: 'sbt shell', source: 'set scalacOptions += "-source:3.0-migration"\ncompile\nreload\n\n// After the migration compile succeeds, commit the baseline first.\nset scalacOptions ++= Seq("-source:3.0-migration", "-rewrite")\ncompile\n\n// Review the source diff, then remove migration mode and compile again.' } },
      { heading: 'Some source changes are mechanical; others change resolution', paragraphs: ['Scala 3 separates the jobs previously grouped under implicit. Context parameters use using, provided instances use given, and enrichment methods use extension. The new syntax is clearer, but a mechanical rewrite does not prove that the same instance wins when several candidates are in scope.', 'Test code that depends on ordering, fallback instances or imported implicits. Scala 3 wildcard imports do not automatically import givens, so an import that looks equivalent may provide a different context. Overloaded methods and inferred conversions deserve the same attention.', 'There is no need to rewrite every sealed trait as an enum or every implicit class as an extension method during the compiler move. First preserve the API and behaviour. Adopt Scala 3-native modelling later where it makes the code materially clearer.'], code: { label: 'Separate context, instance and extension intent', language: 'scala', source: '// Scala 2\nobject Scala2Service {\n  def load(id: AccountId)(implicit trace: Trace): Future[Account] = ???\n  implicit val trace: Trace = Trace.console\n  implicit class AccountOps(account: Account) {\n    def isOverdrawn: Boolean = account.balance < 0\n  }\n}\n\n// Scala 3\nobject Scala3Service:\n  def load(id: AccountId)(using Trace): Future[Account] = ???\n  given Trace = Trace.console\n  extension (account: Account)\n    def isOverdrawn: Boolean = account.balance < 0' } },
      { heading: 'Cross-build where it reduces the blast radius', paragraphs: ['A multi-module repository does not have to change compiler everywhere at once. Shared libraries can often cross-build for Scala 2.13 and Scala 3 while applications migrate separately. Version-specific source directories provide a controlled escape hatch for compiler APIs, syntax or macro implementations that genuinely differ.', 'Cross-building is not free. Every conditional dependency and duplicated source file becomes maintenance work until Scala 2 support is removed. Use common source wherever possible and keep the compatibility period tied to a migration sequence rather than leaving two permanent implementations.', 'Macro libraries are the sharpest example. Their public non-macro data types may remain shared, but Scala 2 macro implementations and Scala 3 quoted implementations normally belong in separate source directories and require tests under both compilers.'], code: { label: 'Cross-build a library without forking the whole project', language: 'scala / sbt', source: 'val Scala213 = "2.13.18"\nval Scala3   = "3.8.4"\n\nThisBuild / crossScalaVersions := Seq(Scala213, Scala3)\nThisBuild / scalaVersion := Scala213\n\n// Shared code:       src/main/scala\n// Scala 2-only code: src/main/scala-2\n// Scala 3-only code: src/main/scala-3\n\n// Verify both sides in CI:\n// sbt "+test"' } },
      { heading: 'Compilation is necessary but not sufficient', paragraphs: ['A clean compile proves that types line up under the new compiler. It does not prove that external behaviour, serialised data or runtime wiring is unchanged. Migration tests should concentrate on places where Scala’s compile-time model leaks into runtime behaviour.', 'Check JSON and binary formats derived from case classes, reflection-based framework wiring, dependency injection, configuration decoding, route binding, database mappings and generated schemas. Snapshot or contract tests are useful when another service depends on the exact representation.', 'Operational behaviour matters too. Compare startup and shutdown, thread pools, blocking execution contexts, request latency, memory and error reporting on the same JDK and workload. If the JDK is changing as well, test the compiler change and runtime change as separate deployable checkpoints wherever the framework allows it.'], bullets: ['Run unit, integration and contract tests under both compilers during transition', 'Compare API payloads and persisted representations', 'Exercise startup, graceful shutdown and failure paths', 'Check logging, metrics and tracing integrations', 'Canary the production artifact and retain a rollback path'] },
      { heading: 'Use explicit go and no-go criteria', paragraphs: ['Proceed when the service has enough useful life, required libraries and plugins have a viable Scala 3 route, important behaviour can be verified, and the team can support the result. The migration should unlock something identifiable: supported dependencies, a platform upgrade, simpler maintenance or a shared language direction.', 'Defer when a managed platform fixes the Scala version, an essential macro or compiler plugin has no replacement, the service is close to retirement, or the test and deployment baseline is too weak to distinguish migration failures from existing ones. In the last case, improving the baseline may be the right first project rather than abandoning migration entirely.', 'Define done beyond scalaVersion. A credible completion means the build resolves without unexplained overrides, migration modes and temporary compatibility flags are removed or documented, production behaviour is observed, rollback has been exercised, and the team understands any remaining Scala 2 bridge.'] },
    ],
  },
  {
    slug: 'finding-your-way-around-scala-ecosystem', title: 'How Scala fits together: language, runtime and ecosystem', category: 'Scala', topic: 'Scala', readTime: '14 min read',
    summary: 'A technical guide to Scala’s type system, execution models, common use cases and the libraries that turn the language into a production stack.',
    sections: [
      { heading: 'Start with the language, not the libraries', paragraphs: ['Scala is a statically typed language that normally compiles to JVM bytecode. It can call Java code directly, use the Java standard library and run in the same process as Java classes. Scala.js and Scala Native provide other compilation targets, but the JVM is still the centre of most backend and data workloads.', 'The distinctive part is the combination of object-oriented and functional programming. Every value has a type, functions are values, immutable data is conventional, and classes, traits and objects remain available when they are the clearest model. Type inference removes much of the annotation noise without making the program dynamically typed.', 'Scala 3 adds direct syntax for enums, union and intersection types, opaque types, extension methods, and contextual abstractions through given and using. Those features are most useful when they make an application constraint visible to the compiler—not when they are used to build the cleverest possible API.'], code: { label: 'A domain type with no allocation overhead', language: 'scala', source: 'opaque type AccountId = Long\n\nobject AccountId:\n  def from(value: Long): Either[String, AccountId] =\n    Either.cond(value > 0, value, "account id must be positive")\n\n  extension (id: AccountId)\n    def value: Long = id\n\nfinal case class Account(id: AccountId, balance: BigDecimal)' } },
      { heading: 'Model the states the system is allowed to have', paragraphs: ['Case classes are immutable product types: they describe values that contain several fields. Enums and sealed traits are sum types: they describe a closed choice between alternatives. Together they form algebraic data types, which are a practical way to represent a domain rather than passing strings and nullable values between methods.', 'Pattern matching deconstructs those values. Because the compiler knows every member of a closed hierarchy, it can warn when a match is not exhaustive. Adding a new payment method can therefore identify the decisions that have not yet been updated.', 'Option makes absence explicit. Either can make an expected failure part of a return type. Exceptions still have a place at process boundaries and for genuinely exceptional failures, but a value such as Either[PaymentError, Receipt] tells a caller more than a method that may throw something.'], code: { label: 'Closed domain choices and exhaustive matching', language: 'scala', source: 'enum PaymentMethod:\n  case Card(lastFour: String)\n  case BankTransfer(reference: String)\n\nenum PaymentError:\n  case Declined(reason: String)\n  case Duplicate(paymentId: String)\n\ndef description(method: PaymentMethod): String = method match\n  case PaymentMethod.Card(lastFour) =>\n    s"card ending $lastFour"\n  case PaymentMethod.BankTransfer(reference) =>\n    s"bank transfer $reference"' } },
      { heading: 'Composition is the important functional idea', paragraphs: ['Functional Scala is not mainly about avoiding classes. It is about building larger behaviour by composing smaller values and functions. Map transforms a successful value while preserving its surrounding context; flatMap lets the next computation depend on the previous result. Option, Either, Future, IO and collections all provide variations of these operations.', 'A for-comprehension is syntax over map, flatMap and withFilter. In the example below, parsing stops on the first invalid field and the error remains typed. No mutable accumulator or nested conditionals are needed.', 'This style scales when the return types are consistent. It becomes awkward when one repository returns Future, another returns IO, and business code throws exceptions. Decide how absence, expected failure and asynchronous work cross each architectural boundary.'], code: { label: 'Compose validation with Either', language: 'scala', source: 'final case class CreateOrder(accountId: AccountId, amount: BigDecimal)\n\ndef positiveAmount(raw: String): Either[String, BigDecimal] =\n  raw.toBigDecimalOption\n    .filter(_ > 0)\n    .toRight("amount must be a positive number")\n\ndef createOrder(id: Long, rawAmount: String): Either[String, CreateOrder] =\n  for\n    accountId <- AccountId.from(id)\n    amount    <- positiveAmount(rawAmount)\n  yield CreateOrder(accountId, amount)' } },
      { heading: 'Future and effect systems are different execution models', paragraphs: ['The standard library Future represents a result that may arrive later. Creating one normally schedules its work immediately on an ExecutionContext. It integrates naturally with Java completion stages and remains common in Play applications, but it does not provide a general model for cancellation or resource lifetime.', 'Cats Effect IO and ZIO use values that describe work. The runtime interprets that description at the edge of the program. This indirection enables lightweight fibres, structured concurrency, cancellation, timeouts and resource scopes whose finalisers run on success, failure or cancellation.', 'That distinction changes application design. A function returning IO[User] describes an action; it has not fetched a user yet. Blocking JDBC work must still be identified and shifted to an appropriate executor. An effect type does not make blocking calls non-blocking, and wrapping every pure calculation in IO only obscures the program.'], code: { label: 'Resource lifetime and concurrent effects', language: 'scala / Cats Effect', source: 'import cats.effect.{IO, Resource}\nimport cats.syntax.all.*\nimport java.sql.Connection\nimport scala.concurrent.duration.*\n\ndef account(id: AccountId): IO[Account] = ???\ndef creditScore(id: AccountId): IO[Score] = ???\n\nval connection: Resource[IO, Connection] =\n  Resource.fromAutoCloseable(IO.blocking(dataSource.getConnection))\n\ndef assess(id: AccountId): IO[Decision] =\n  (account(id), creditScore(id))\n    .parMapN(Decision.from)\n    .timeout(2.seconds)\n\nconnection.use(conn => IO.blocking(runAssessment(conn)))' } },
      { heading: 'Where Scala is a strong fit', paragraphs: ['Scala is most convincing when the problem benefits from both the JVM and a richer type system. Long-lived backend services use it for domain modelling, concurrent request handling and streaming. FS2 can express bounded, back-pressured pipelines using functional stream transformations.', 'Data engineering is another established use case. Apache Spark exposes a Scala API and its own runtime dictates compatible Scala and JDK versions. That last detail matters: a data platform may keep an application on a different Scala line from a new HTTP service, even inside the same organisation.', 'Scala can also target JavaScript for browser or Node.js programs and native binaries for command-line tools. Those targets are real options, but library availability differs by platform. Check whether every required dependency is published for the intended target before choosing it.'], bullets: ['Backend APIs with complicated domains or concurrency', 'Event ingestion and streaming pipelines', 'Distributed data processing with Spark', 'Compilers, developer tools and rule engines', 'Shared cross-platform libraries where Scala.js or Native support is deliberate'], code: { label: 'A typed Spark transformation', language: 'scala / Spark', source: 'final case class Purchase(customerId: Long, amount: BigDecimal)\nfinal case class CustomerTotal(customerId: Long, total: BigDecimal)\n\nval totals: Dataset[CustomerTotal] = purchases\n  .groupByKey(_.customerId)\n  .mapGroups { case (customerId, rows) =>\n    CustomerTotal(customerId, rows.map(_.amount).sum)\n  }' } },
      { heading: 'The backend ecosystem has several coherent stacks', paragraphs: ['There is no single standard Scala web stack. Play is an integrated MVC framework with routing, JSON support and an established Future-based model. The Typelevel family combines Cats Effect, http4s and FS2 with libraries for JSON and database access. Other Scala ecosystems provide their own HTTP, streaming, JSON and configuration choices.', 'These choices reach below the routing layer. They influence how dependencies are provided, how errors are encoded, how tests run and how resources shut down. Mixing is possible through adapters, but every bridge adds another execution model for engineers to understand.', 'Choose the centre of gravity first, then fill genuine gaps. For example, an http4s service already using Cats Effect will usually gain more from an FS2-compatible client than from introducing a second effect runtime for one attractive library.'], bullets: ['HTTP: Play or http4s', 'JSON: Play JSON or a codec compatible with the chosen stack', 'Database: a library compatible with the application effect and persistence model', 'Streaming: FS2 where the application uses Cats Effect', 'Testing: ScalaTest or a framework compatible with the chosen effect model'] },
      { heading: 'Java interoperability is a design tool', paragraphs: ['Scala classes compile to JVM classes, so a project can use Java database drivers, cloud SDKs and observability agents directly. Java interfaces can be implemented in Scala, and Java code can call deliberately designed Scala APIs.', 'The rough edges are usually Scala-specific types and conventions. Scala collections are not Java collections, Future is not CompletionStage, and default parameters or contextual arguments do not produce an obvious Java API. Conversion libraries cover the common cases, but a public cross-language boundary should prefer simple JVM types and explicit methods.', 'This is especially useful during incremental modernisation. A Java service can move a well-bounded module to Scala without rewriting the process, deployment model or infrastructure integrations. The boundary matters more than the percentage of each language.'], code: { label: 'Expose an explicit Java-facing boundary', language: 'scala', source: 'import java.util.concurrent.CompletionStage\nimport scala.concurrent.{ExecutionContext, Future}\nimport scala.jdk.FutureConverters.*\n\ntrait ScalaAccountService:\n  def find(id: AccountId): Future[Option[Account]]\n\nfinal class JavaAccountApi(service: ScalaAccountService)(using ExecutionContext):\n  def find(id: Long): CompletionStage[Account | Null] =\n    val result = AccountId.from(id) match\n      case Left(message) => Future.failed(new IllegalArgumentException(message))\n      case Right(accountId) => service.find(accountId).map(_.orNull)\n\n    result.asJava' } },
      { heading: 'Scala dependencies carry a binary version', paragraphs: ['A Java dependency in sbt uses a single percent sign because its artifact name is independent of Scala. A Scala dependency normally uses two percent signs. sbt expands that operator to an artifact suffixed with the project’s Scala binary version, such as a Scala 2.13 or Scala 3 build.', 'That is why a library can exist on Maven Central and still be unavailable to your project: it may not have been published for your Scala line or runtime target. Libraries that support several versions are cross-built and publish a separate artifact for each supported binary version.', 'Before a Scala or framework upgrade, inspect the complete graph: compiler plugins, sbt plugins, macros, test frameworks and internal libraries as well as runtime dependencies. Eviction warnings and forced version overrides are evidence to investigate, not build noise to suppress.'], code: { label: 'Java, Scala and cross-built dependencies in sbt', language: 'scala / sbt', source: 'ThisBuild / scalaVersion := "3.8.4"\n\nlibraryDependencies ++= Seq(\n  "org.postgresql" %  "postgresql" % postgresVersion, // Java artifact\n  "org.typelevel"  %% "cats-effect" % catsEffectVersion, // Scala artifact\n  "org.scalameta"  %% "munit"      % munitVersion % Test\n)\n\n// A library project can publish once for each binary line.\ncrossScalaVersions := Seq("2.13.18", "3.8.4")' } },
      { heading: 'Tooling should make those constraints visible', paragraphs: ['sbt remains common for multi-module production builds and has a large plugin ecosystem. Mill offers a different build definition and execution model. Scala CLI is particularly effective for scripts, examples and small applications, and can declare the Scala version, platform and dependencies in source directives.', 'Metals supplies language-server features to VS Code and other editors; IntelliJ has its own Scala support. Scalafmt standardises formatting, while Scalafix can apply semantic rewrites and enforce some codebase rules. Pin all of them. A globally installed compiler should not decide how a checked-out project builds.', 'A healthy Scala repository makes four versions easy to find: Scala, the JDK, the build tool and the principal framework or effect runtime. CI should reproduce them, compile with useful warnings, run tests, and fail on incompatible dependency resolution. That foundation matters more than the number of advanced language features in the source.'], code: { label: 'A small Scala CLI program with pinned inputs', language: 'scala', source: '//> using scala "3.8.4"\n//> using jvm "21"\n\nimport java.nio.file.{Files, Path}\nimport scala.jdk.CollectionConverters.*\n\n@main def countScalaFiles(path: String): Unit =\n  val stream = Files.walk(Path.of(path))\n  try\n    val count = stream.iterator.asScala.count(_.toString.endsWith(".scala"))\n    println(s"$count Scala files")\n  finally stream.close()' } },
    ],
  },
  {
    slug: 'partial-functions-in-scala', title: 'Partial functions in Scala: useful precision, not incomplete code', category: 'Scala language', topic: 'Scala', readTime: '9 min read',
    summary: 'How PartialFunction models a function defined for only part of its input, how collect and recover use it, and where ordinary total functions are safer.',
    sections: [
      { heading: 'A partial function has a defined domain', paragraphs: ['An ordinary Function1[A, B] promises that it can produce a B for every A it receives. A PartialFunction[A, B] narrows that promise: it is defined for some values of A and exposes isDefinedAt so callers can ask whether a value belongs to that domain.', 'A case block can be assigned directly to a PartialFunction. The compiler generates both the matching behaviour and the domain check. Calling apply with an unsupported value can still throw MatchError, so the type does not make arbitrary direct invocation safe.', 'The important distinction is semantic rather than syntactic. A partial function is appropriate when selective handling is the operation itself. It is not a substitute for returning Option or Either from a business operation that callers expect to invoke normally.'], code: { label: 'Define and inspect a selective operation', language: 'scala 2.13', source: 'val statusText: PartialFunction[Int, String] = {\n  case 200 => "ok"\n  case 404 => "not found"\n}\n\nstatusText.isDefinedAt(200) // true\nstatusText.isDefinedAt(500) // false\nstatusText.lift(404)        // Some("not found")\nstatusText.lift(500)        // None' } },
      { heading: 'collect is the natural collection operation', paragraphs: ['Collection methods reveal why PartialFunction is useful. map requires an output for every element. filter decides which elements remain but does not transform them. collect combines those operations: it selects the values for which a partial function is defined and transforms only those values.', 'This is clearer than returning Option from map and flattening when selection and transformation are one decision. It also keeps the accepted input shapes next to the transformation that handles them.', 'Use collect when discarded inputs are expected. If an unsupported value means corrupt data or a failed invariant, silently omitting it can hide a problem; traverse the inputs with Either or validate them explicitly instead.'], code: { label: 'Select and transform in one expression', language: 'scala 2.13', source: 'sealed trait Event\nfinal case class UserCreated(id: String) extends Event\nfinal case class EmailChanged(id: String, email: String) extends Event\nfinal case class Heartbeat(at: Long) extends Event\n\nval affectedUsers: List[String] = events.collect {\n  case UserCreated(id)       => id\n  case EmailChanged(id, _)   => id\n}\n\n// Heartbeats are deliberately outside this operation\'s domain.' } },
      { heading: 'Composition preserves the defined cases', paragraphs: ['orElse combines two partial functions. The left-hand function gets the first opportunity to handle an input; the right-hand function is consulted only when the first is not defined. This makes ordering part of the behaviour and deserves a test when cases overlap.', 'andThen transforms the successful output while keeping the original input domain. lift converts a PartialFunction[A, B] into a total Function1[A, Option[B]], which is often safer at a boundary where a value may not be handled.', 'At a lower level, applyOrElse can test and apply without evaluating the pattern match twice. Collection implementations use this shape for efficiency. Application code should normally prefer collect, lift or orElse because they communicate the intent directly.'], code: { label: 'Compose handlers, then make the result total', language: 'scala 2.13', source: 'val clientError: PartialFunction[Int, String] = {\n  case code if code >= 400 && code < 500 => "client"\n}\n\nval serverError: PartialFunction[Int, String] = {\n  case code if code >= 500 && code < 600 => "server"\n}\n\nval classifyError = clientError.orElse(serverError)\nval safeClassify: Int => Option[String] = classifyError.lift\n\nsafeClassify(503) // Some("server")\nsafeClassify(204) // None' } },
      { heading: 'Recovery handlers are partial by design', paragraphs: ['Future.recover and recoverWith accept partial functions because a recovery policy commonly handles only selected failures. An unmatched exception remains a failed Future rather than being accidentally converted into a success.', 'Keep these handlers narrow. A broad case matching Throwable can turn programming errors, interruption or infrastructure failures into misleading domain responses. Match only failures for which the current layer has a legitimate fallback.', 'The same rule applies to actor receive handlers and request-routing DSLs: partial functions are effective dispatch mechanisms, but the boundary still needs an explicit policy for unhandled input.'], code: { label: 'Recover only the failure this layer understands', language: 'scala 2.13', source: 'def loadAccount(id: AccountId): Future[Account] =\n  repository.find(id).recoverWith {\n    case _: RepositoryTimeout =>\n      cache.find(id).flatMap {\n        case Some(account) => Future.successful(account)\n        case None          => Future.failed(AccountUnavailable(id))\n      }\n  }\n\n// Other failures remain failures.' } },
      { heading: 'Prefer a total result for domain decisions', paragraphs: ['Eligibility checks, validation and state transitions usually need to explain rejection rather than declare themselves undefined. Either[Reason, Result] or Option[Result] gives every input a result and forces the caller to acknowledge the negative case.', 'A useful test is to ask what an unsupported input means. If it means “this handler is not responsible for that message”, PartialFunction is a good fit. If it means “the request was invalid” or “the transition was rejected”, return that fact as data.', 'Partial functions are therefore precise tools for selection, dispatch and selective recovery. Used at those boundaries they remove branching noise. Used as ordinary service methods they can move a missing case from compile-time reasoning into a runtime MatchError.'] },
    ],
  },
  {
    slug: 'modelling-a-play-framework-application', title: 'Modelling a Play Framework application beyond controllers and JSON', category: 'Play Framework', topic: 'Scala', topics: ['Architecture'], readTime: '11 min read',
    summary: 'A practical route from untrusted HTTP input to validated domain commands, explicit service outcomes and stable Play JSON responses.',
    sections: [
      { heading: 'HTTP models and domain models have different jobs', paragraphs: ['A Play controller sits at an untrusted boundary. Request bodies may be missing fields, contain malformed values or use representations chosen for compatibility with clients. A domain model should represent the states the application is prepared to reason about after those checks have succeeded.', 'Using one case class for JSON, business logic and persistence is initially convenient, but it couples three reasons to change. A renamed API field can disturb stored documents; an optional transport field can introduce Option deep into code where the value is actually required.', 'Small applications do not need ceremonial layers. Separate the models when the boundary has different invariants, lifecycle or compatibility requirements—not simply because a diagram says every service needs a DTO.'], code: { label: 'Keep transport choices at the HTTP boundary', language: 'scala 2.13 / Play', source: 'final case class CreateAccountRequest(name: String, openingBalance: BigDecimal)\nobject CreateAccountRequest {\n  implicit val reads: Reads[CreateAccountRequest] = Json.reads\n}\n\nfinal case class AccountName private (value: String)\nobject AccountName {\n  def from(value: String): Either[String, AccountName] =\n    Either.cond(value.trim.nonEmpty, AccountName(value.trim), "name is required")\n}\n\nfinal case class OpenAccount(name: AccountName, openingBalance: BigDecimal)' } },
      { heading: 'Validate structure first, then domain meaning', paragraphs: ['Play JSON Reads answers structural questions: is the body JSON, are required fields present, and can their values be decoded? Domain construction answers a different set of questions: is this name usable and is the opening balance permitted?', 'Keeping both stages visible improves error handling. JsError can become a consistent 400 response describing malformed input. A domain rejection can use the application’s own error vocabulary without importing Play JSON types into the service layer.', 'Validation should not be duplicated indiscriminately. The domain constructor is the authoritative place for an invariant that must hold regardless of whether input arrives through HTTP, a test or another service entry point.'], code: { label: 'Translate validated JSON into a domain command', language: 'scala 2.13 / Play', source: 'def toCommand(request: CreateAccountRequest): Either[CreateError, OpenAccount] =\n  for {\n    name <- AccountName.from(request.name).left.map(CreateError.InvalidName)\n    _ <- Either.cond(\n      request.openingBalance >= 0,\n      (),\n      CreateError.InvalidBalance("opening balance cannot be negative")\n    )\n  } yield OpenAccount(name, request.openingBalance)\n\ndef create: Action[JsValue] = Action.async(parse.json) { request =>\n  request.body.validate[CreateAccountRequest].fold(\n    errors => Future.successful(BadRequest(JsError.toJson(errors))),\n    input => handle(input)\n  )\n}' } },
      { heading: 'Make service outcomes explicit', paragraphs: ['A service returning Future[Result] is easy to wire but gives the domain layer control over HTTP and makes its behaviour harder to reuse. Prefer a service result that describes what happened, then translate that result into Play’s Result at the controller boundary.', 'Expected outcomes such as duplicate accounts or rejected commands are values, not failed Futures. Reserve a failed Future for failures that prevented the operation from producing a domain answer: a database outage, timeout or unexpected defect.', 'This separation also improves tests. Service tests assert domain outcomes without building fake requests. Controller tests concentrate on JSON, status codes and response bodies rather than repeating the business rules.'], code: { label: 'Translate domain outcomes into HTTP responses', language: 'scala 2.13 / Play', source: 'sealed trait CreateAccountResult\nobject CreateAccountResult {\n  final case class Created(account: Account) extends CreateAccountResult\n  case object AlreadyExists extends CreateAccountResult\n}\n\ndef render(result: CreateAccountResult): Result = result match {\n  case CreateAccountResult.Created(account) =>\n    Created(Json.toJson(AccountResponse.from(account)))\n  case CreateAccountResult.AlreadyExists =>\n    Conflict(Json.obj("code" -> "account_exists"))\n}\n\nservice.create(command).map(render)' } },
      { heading: 'Dependency injection belongs at construction boundaries', paragraphs: ['Play’s dependency injection can construct controllers, services and repositories, but injected classes should still expose small dependencies with meaningful interfaces. Injecting a large application environment into every class hides what each operation needs.', 'Constructor injection makes dependencies visible and permits ordinary unit tests. It does not require an interface for every concrete class. Introduce a trait when there is a real boundary—persistence, an external API, time, or another effect that tests and implementations need to vary.', 'Keep configuration parsing and resource creation near application startup. A repository should receive the collection or client it needs rather than repeatedly looking it up from global configuration. Invalid required configuration should fail during startup, not on the first production request.'], code: { label: 'Expose the meaningful application dependencies', language: 'scala 2.13 / Play', source: 'trait AccountRepository {\n  def insert(account: Account): Future[InsertResult]\n  def findByName(name: AccountName): Future[Option[Account]]\n}\n\nfinal class AccountService @Inject()(\n  repository: AccountRepository,\n  clock: java.time.Clock\n)(implicit ec: ExecutionContext) {\n  def create(command: OpenAccount): Future[CreateAccountResult] = ???\n}\n\nfinal class AccountController @Inject()(\n  components: ControllerComponents,\n  service: AccountService\n)(implicit ec: ExecutionContext) extends AbstractController(components)' } },
      { heading: 'Persistence and JSON changes need compatibility decisions', paragraphs: ['Case-class shape is not automatically an API or database migration strategy. Play JSON derivation follows field names and available formats; MongoDB mappings have their own representation. Renaming a Scala field can therefore change external data even when business behaviour is unchanged.', 'Use explicit reads when accepting an old and new representation during a transition. Write only the intended current format, measure remaining legacy data, and remove compatibility code deliberately. For stored documents, decide whether migration happens on read, through a background process or before deployment.', 'Integration tests should cover the real boundary: representative JSON through the route, repository behaviour against MongoDB, and the response or stored document clients rely upon. Unit tests alone cannot prove that formats, wiring and indexes agree.'], bullets: ['Version externally visible changes intentionally', 'Test malformed, missing and additional input fields', 'Keep domain values independent of Play Result and JsValue', 'Exercise repository mappings against the real database', 'Record whether old payloads and documents remain readable'] },
    ],
  },
  {
    slug: 'case-classes-as-domain-models', title: 'Case classes are data models, not your whole domain', category: 'Scala language', topic: 'Scala', readTime: '9 min read',
    summary: 'What Scala case classes generate, why value semantics are useful, and how to keep validation, invariants and persistence concerns under control.',
    sections: [
      { heading: 'A case class gives a value a useful identity', paragraphs: ['A case class generates value-based equals and hashCode, a readable toString, accessors for constructor parameters, a copy method and companion apply and unapply methods. Those defaults make immutable records concise and easy to use in collections, tests and pattern matches.', 'Value equality is the central feature. Two separately constructed values with the same fields compare as equal, which suits commands, identifiers, configuration and domain snapshots. That is different from an entity whose identity remains the same while its recorded attributes change.', 'Case classes are not deeply immutable by magic. A val prevents reassignment of the field, but a mutable collection or object stored inside the field can still change. Prefer immutable field types when the value is intended to be stable.'], code: { label: 'Generated value semantics in everyday use', language: 'scala 2.13', source: 'final case class Account(id: AccountId, name: String, balance: BigDecimal)\n\nval original = Account(AccountId("a-17"), "Ada", BigDecimal(20))\nval updated  = original.copy(balance = BigDecimal(35))\n\noriginal.balance // 20\nupdated.balance  // 35\noriginal == Account(AccountId("a-17"), "Ada", BigDecimal(20)) // true' } },
      { heading: 'Put invalid primitive values behind constructors', paragraphs: ['A case class with String and BigDecimal fields may allow empty names, negative balances or identifiers in the wrong format. Checking those rules only in a controller leaves other construction paths unprotected.', 'A small value type can own parsing and validation. Its companion returns Either rather than throwing for expected invalid input. Once constructed, application code can rely on the invariant without repeating checks at every call site.', 'Not every String needs a wrapper. Add a domain type when it prevents a real category of mistake, centralises a meaningful rule or stops two values with the same runtime representation from being interchanged.'], code: { label: 'Construct a constrained value explicitly', language: 'scala 2.13', source: 'final case class AccountId private (value: String) extends AnyVal\n\nobject AccountId {\n  private val Valid = "[a-z0-9-]{3,40}".r\n\n  def from(raw: String): Either[String, AccountId] =\n    raw match {\n      case Valid() => Right(AccountId(raw))\n      case _       => Left("invalid account id")\n    }\n}\n\nAccountId.from("a-17") // Right(AccountId("a-17"))\nAccountId.from("")     // Left("invalid account id")' } },
      { heading: 'copy is convenient because it is unrestricted', paragraphs: ['copy treats a case class as a product of its fields. That is ideal for ordinary immutable data, but it does not express which business transitions are permitted. account.copy(status = Closed) can bypass rules about outstanding balances if status is publicly replaceable.', 'Model important transitions as methods or functions that validate the current state and return the next state. The case class can remain the representation while the transition becomes the public operation. For stricter control, keep constructors and representations inside a module and expose only smart constructors and behaviours.', 'This is a judgement call. A request DTO benefits from unrestricted copy. An aggregate with consequential state changes may need a smaller public surface.'], code: { label: 'Name and validate a domain transition', language: 'scala 2.13', source: 'sealed trait AccountStatus\nobject AccountStatus {\n  case object Open extends AccountStatus\n  case object Closed extends AccountStatus\n}\n\nfinal case class Account(id: AccountId, balance: BigDecimal, status: AccountStatus) {\n  def close: Either[CloseError, Account] =\n    if (balance == 0) Right(copy(status = AccountStatus.Closed))\n    else Left(CloseError.OutstandingBalance(balance))\n}' } },
      { heading: 'Pattern matching can couple callers to representation', paragraphs: ['The generated unapply makes case classes pleasant to deconstruct. It also means callers can become coupled to constructor order and field shape. Adding a field may require edits across matches that only needed one property.', 'Prefer named accessors or behaviour methods when the caller is not genuinely interpreting the whole product. Pattern matching is strongest when used with a closed set of alternatives, such as a sealed trait whose cases carry different data.', 'At external boundaries, derived serializers can create similar coupling. A convenient Json.format or database codec is still a representation decision. Protect important payloads and persisted formats with tests before changing the case class.'], code: { label: 'Match on the domain choice, not every field', language: 'scala 2.13', source: 'sealed trait PaymentResult\nobject PaymentResult {\n  final case class Accepted(receipt: Receipt) extends PaymentResult\n  final case class Declined(reason: DeclineReason) extends PaymentResult\n}\n\ndef message(result: PaymentResult): String = result match {\n  case PaymentResult.Accepted(receipt) => s"accepted: ${receipt.id}"\n  case PaymentResult.Declined(reason)  => s"declined: ${reason.message}"\n}' } },
      { heading: 'Separate domain, transport and storage where they diverge', paragraphs: ['Reusing one case class everywhere is reasonable while the shapes and change cycles are genuinely the same. Separate it when JSON compatibility, database migrations or domain invariants begin pulling in different directions.', 'A transport model can reflect an optional legacy field. A persistence model can include schema version and migration metadata. The domain model can then state what current application logic requires. Translation code is not waste when it prevents accidental coupling between those contracts.', 'The aim is not to maximise the number of models. It is to make each important representation explicit enough that a local refactor cannot silently alter an API or stored document.'] },
    ],
  },
  {
    slug: 'traits-in-scala-design', title: 'Using traits as precise boundaries in Scala', category: 'Scala language', topic: 'Scala', readTime: '9 min read',
    summary: 'Traits can define capabilities, share behaviour and close a domain hierarchy; those are different jobs with different design trade-offs.',
    sections: [
      { heading: 'A trait can describe a capability', paragraphs: ['A Scala trait can contain abstract members, concrete methods and state. That makes it more capable than a minimal Java interface, but the most maintainable service boundaries usually remain small and describe one role.', 'A repository trait is useful when application logic should depend on persistence behaviour without knowing MongoDB details. Its method signatures should expose domain intent rather than mirroring every method offered by a database client.', 'Do not create a trait solely to satisfy a rule that every class needs an interface. A single pure implementation with no meaningful boundary often needs no abstraction. Add the trait when multiple interpreters, testing, dependency direction or ownership of an effect makes the boundary valuable.'], code: { label: 'Describe the operation, not the database driver', language: 'scala 2.13', source: 'trait AccountRepository {\n  def find(id: AccountId): Future[Option[Account]]\n  def save(account: Account): Future[Unit]\n}\n\nfinal class MongoAccountRepository(collection: AccountCollection)\n    extends AccountRepository {\n  override def find(id: AccountId): Future[Option[Account]] = ???\n  override def save(account: Account): Future[Unit] = ???\n}' } },
      { heading: 'A sealed trait defines a closed choice', paragraphs: ['Sealing a trait means direct subclasses must be declared in the same source file in Scala 2. The compiler can then reason about the complete set of alternatives and warn when a pattern match is not exhaustive.', 'This is a different use of traits from dependency abstraction. A sealed hierarchy models data: a payment was accepted or declined; a command is pending, running or complete. Case classes and case objects carry the data for each alternative.', 'Closed models make illegal combinations harder to construct. Instead of a record with several booleans and optional fields, each case can contain exactly the information available in that state.'], code: { label: 'Represent each permitted state directly', language: 'scala 2.13', source: 'sealed trait ImportState\nobject ImportState {\n  case object Pending extends ImportState\n  final case class Running(startedAt: Instant) extends ImportState\n  final case class Completed(rows: Int, finishedAt: Instant) extends ImportState\n  final case class Failed(reason: String, failedAt: Instant) extends ImportState\n}\n\ndef isFinished(state: ImportState): Boolean = state match {\n  case ImportState.Completed(_, _) | ImportState.Failed(_, _) => true\n  case ImportState.Pending | ImportState.Running(_)            => false\n}' } },
      { heading: 'Concrete behaviour introduces linearisation', paragraphs: ['Traits can implement methods and call super, enabling stackable modifications. When several traits override the same method, Scala linearises the inheritance graph to determine the order. The trait mixed in furthest to the right is entered first, then its super call proceeds through the chain.', 'This can be elegant for small, orthogonal behaviour, but application control flow becomes difficult to follow when logging, retries, metrics and validation are all mixed into a class. Constructor-injected decorators usually make order and dependencies more explicit.', 'If mixin order changes behaviour, test that order directly and keep the chain short. Avoid mutable trait state shared across concurrent requests unless its lifecycle and synchronisation are deliberate.'], code: { label: 'Mixin order is part of the result', language: 'scala 2.13', source: 'trait Message { def text: String = "account created" }\n\ntrait WithTimestamp extends Message {\n  abstract override def text: String = s"[12:00] ${super.text}"\n}\n\ntrait AsWarning extends Message {\n  abstract override def text: String = s"WARNING: ${super.text}"\n}\n\nval message = new Message with WithTimestamp with AsWarning\nmessage.text // "WARNING: [12:00] account created"' } },
      { heading: 'Self-types state a requirement but do not provide it', paragraphs: ['A self-type says that a trait may only be mixed into something that also conforms to another type. It can make a capability available inside the trait without extending that capability as part of the public subtype relationship.', 'Self-types are useful in some modular designs, but they can hide the eventual object graph across several files. Constructor parameters are usually clearer for application services because the required dependencies are visible where the class is instantiated.', 'Use a self-type when composition through mixins is genuinely the chosen model. Do not use it as a more mysterious spelling of dependency injection.'], code: { label: 'A self-type constrains legal composition', language: 'scala 2.13', source: 'trait AuditLog {\n  def record(event: String): Unit\n}\n\ntrait AuditedOperations { self: AuditLog =>\n  def closeAccount(id: AccountId): Unit = {\n    record(s"closing ${id.value}")\n    // perform the operation\n  }\n}\n\nfinal class AccountAdmin extends AuditedOperations with AuditLog {\n  override def record(event: String): Unit = println(event)\n}' } },
      { heading: 'Choose the job before choosing the trait', paragraphs: ['Traits are used for at least three distinct jobs: open service abstractions, closed algebraic data types and reusable implementation. Confusing those jobs produces broad interfaces, deep inheritance and models that callers can extend when they should be closed.', 'For a service boundary, prefer a small vocabulary of meaningful operations. For domain alternatives, seal the hierarchy. For shared implementation, check whether an ordinary function, helper value or explicit decorator would make execution order easier to see.', 'The best trait is not the most reusable one. It is the one that makes a real boundary or set of permitted states obvious to the next engineer.'] },
    ],
  },
  {
    slug: 'typeclasses-in-practical-scala', title: 'Typeclasses in practical Scala: behaviour without inheritance', category: 'Functional Scala', topic: 'Scala', readTime: '11 min read',
    summary: 'How a typeclass separates behaviour from data, how Scala 2 implicits and Scala 3 given instances supply evidence, and when the pattern is worth using.',
    sections: [
      { heading: 'A typeclass describes behaviour for a type', paragraphs: ['In Scala, a typeclass is a design pattern rather than a special declaration. A parameterised trait describes an operation for A, and a separate value implements that operation for a particular A. Generic code receives the implementation as an implicit parameter in Scala 2 or a using parameter in Scala 3.', 'The data type does not have to extend the typeclass. This allows behaviour to be defined for types you do not own and permits more than one interpretation where the application makes the choice explicit.', 'Unlike subtype polymorphism, the relationship is assembled at the call site. The compiler searches the available implicit scope for evidence that the requested behaviour exists. That convenience is useful only while instance ownership and imports remain understandable.'], code: { label: 'Define behaviour separately from the data', language: 'scala 2.13', source: 'trait Display[A] {\n  def display(value: A): String\n}\n\nfinal case class AccountId(value: String)\n\nobject AccountId {\n  implicit val accountIdDisplay: Display[AccountId] =\n    new Display[AccountId] {\n      override def display(value: AccountId): String = value.value\n    }\n}\n\ndef label[A](value: A)(implicit display: Display[A]): String =\n  display.display(value)\n\nlabel(AccountId("a-17")) // "a-17"' } },
      { heading: 'Companion placement gives instances a discoverable home', paragraphs: ['Scala 2 implicit search considers values available locally, imported values and relevant companion objects. Placing the canonical instance beside the data type or typeclass lets callers use it without a wildcard import from an unrelated utility object.', 'Local instances can deliberately override behaviour for one scope, but competing imports often produce ambiguity. If an application genuinely needs several interpretations—an internal display and a redacted display, for example—use clearly named modules and import the selected policy close to use.', 'An instance is application behaviour, not harmless wiring. Equality, ordering, serialisation and retry policies can change program results. Give important instances direct tests.'], code: { label: 'Select an alternative policy explicitly', language: 'scala 2.13', source: 'object RedactedAccountDisplay {\n  implicit val redacted: Display[AccountId] =\n    new Display[AccountId] {\n      override def display(value: AccountId): String =\n        s"***${value.value.takeRight(4)}"\n    }\n}\n\n{\n  import RedactedAccountDisplay.redacted\n  label(AccountId("account-a-17")) // "***a-17"\n}' } },
      { heading: 'Syntax makes the abstraction usable', paragraphs: ['Typeclass syntax is usually an implicit class in Scala 2 or an extension method in Scala 3. It turns display.display(account) into account.display while still resolving the separate Display[Account] instance.', 'Keep syntax thin. It should delegate to the typeclass rather than contain a second implementation. Otherwise direct typeclass use and extension syntax can disagree.', 'Libraries such as Cats use this structure for Eq, Show, Semigroup and many other abstractions. Understanding the small pattern makes library syntax less mysterious: an operator normally requires an instance expressing the law or behaviour behind it.'], code: { label: 'Add syntax without adding behaviour', language: 'scala 2.13', source: 'object DisplaySyntax {\n  implicit final class DisplayOps[A](private val value: A) extends AnyVal {\n    def display(implicit instance: Display[A]): String =\n      instance.display(value)\n  }\n}\n\nimport DisplaySyntax._\n\nAccountId("a-17").display' } },
      { heading: 'Instances can be derived from other instances', paragraphs: ['Typeclasses become powerful when an instance for a larger structure can be constructed from instances for its parts. If A can be displayed, Option[A] can be displayed without knowing anything else about A.', 'This is ordinary dependency composition performed through types. The compiler resolves Display[A], passes it to the deriving method and receives Display[Option[A]]. More advanced functional libraries apply the same idea across nested contexts and algebraic structures.', 'Recursive derivation can produce confusing compiler errors when a base instance is missing or candidates overlap. Inspect the required type from the outside in and supply explicit instances at important module boundaries rather than adding broad fallback implicits.'], code: { label: 'Derive behaviour for an enclosing type', language: 'scala 2.13', source: 'implicit def optionDisplay[A](implicit A: Display[A]): Display[Option[A]] =\n  new Display[Option[A]] {\n    override def display(value: Option[A]): String =\n      value.fold("not supplied")(A.display)\n  }\n\nlabel(Option(AccountId("a-17"))) // "a-17"\nlabel(Option.empty[AccountId])   // "not supplied"' } },
      { heading: 'Scala 3 changes the vocabulary, not the core pattern', paragraphs: ['Scala 3 expresses instances with given, dependencies with using and syntax with extension. summon retrieves an instance from context. The separation remains the same: a behaviour interface, implementations for concrete types and generic functions that require evidence.', 'During a Scala 2 to Scala 3 migration, preserve behaviour before rewriting every implicit into new syntax. Instance-resolution rules and imports differ in places, so compile success should be supported by tests for code where instance choice affects results.', 'A mixed codebase can adopt the new vocabulary gradually where source compatibility and team conventions permit it. Clarity of instance ownership matters more than whether the syntax looks maximally Scala 3-native.'], code: { label: 'The same small typeclass in Scala 3', language: 'scala 3', source: 'trait Display[A]:\n  def display(value: A): String\n\ngiven Display[AccountId] with\n  def display(value: AccountId): String = value.value\n\nextension [A](value: A)\n  def display(using instance: Display[A]): String =\n    instance.display(value)\n\nAccountId("a-17").display' } },
      { heading: 'Reach for a typeclass when generic behaviour is real', paragraphs: ['A typeclass earns its complexity when several data types share an operation, generic code needs that operation, or behaviour must be added without changing the data types. It can also express capabilities such as encoding, equality or combination in a reusable way.', 'For one service with one implementation, constructor injection is often simpler. For behaviour that inherently belongs to a domain object, a regular method may be clearer. Typeclasses should solve a polymorphism or composition problem, not merely relocate a method.', 'The practical test is whether callers benefit from writing code in terms of A plus a capability. If there is no useful generic caller, the extra trait, instance and syntax layer may be abstraction without leverage.'] },
    ],
  },
  {
    slug: 'error-handling-as-values-in-scala', title: 'Error handling as values in Scala', category: 'Functional Scala', topic: 'Scala', readTime: '11 min read',
    summary: 'Model expected failures with sealed types and Either, keep unexpected failures distinct, and translate both deliberately at HTTP and asynchronous boundaries.',
    sections: [
      { heading: 'Not every unsuccessful result is an exception', paragraphs: ['A rejected command, missing account or invalid transition may be an expected outcome of an operation. Representing that outcome in the return type tells callers that they must consider it. A thrown exception hides the possibility from the method signature and relies on runtime control flow.', 'Scala’s Either[E, A] describes a computation that produces an error E or a successful value A. By convention Left contains the error and Right contains the success. In Scala 2.13, Either is right-biased, so map and flatMap operate on the successful value while leaving an existing Left unchanged.', 'This does not mean exceptions should never exist. Failed database connections, timeouts and defects still need an exceptional channel. The useful distinction is whether the current operation can name and reasonably handle the outcome as part of its contract.'], code: { label: 'Make expected rejection visible in the signature', language: 'scala 2.13', source: 'sealed trait CloseAccountError\nobject CloseAccountError {\n  case object AlreadyClosed extends CloseAccountError\n  final case class OutstandingBalance(amount: BigDecimal) extends CloseAccountError\n}\n\ndef close(account: Account): Either[CloseAccountError, Account] =\n  if (account.isClosed) Left(CloseAccountError.AlreadyClosed)\n  else if (account.balance != 0)\n    Left(CloseAccountError.OutstandingBalance(account.balance))\n  else Right(account.copy(isClosed = true))' } },
      { heading: 'Give errors a closed vocabulary', paragraphs: ['A sealed trait or sealed abstract class gives the operation a finite error vocabulary. Callers can pattern match on the cases and the compiler can warn when a new case is not handled. The cases can carry structured context without reducing the result to a message string.', 'Keep domain errors independent of presentation. InvalidAccountName is a domain fact; “account_name_invalid” may be an API code; a sentence shown to a user is presentation. Putting HTTP status codes or translated messages inside the domain error couples application logic to one delivery mechanism.', 'An error algebra should be as small as the decision requires. A single global ApplicationError hierarchy tends to collect unrelated failures and allows every method to appear capable of returning all of them. Prefer errors scoped to an operation or coherent domain.'], code: { label: 'Translate domain errors at the HTTP boundary', language: 'scala 2.13 / Play', source: 'def render(error: CloseAccountError): Result = error match {\n  case CloseAccountError.AlreadyClosed =>\n    Conflict(Json.obj("code" -> "account_already_closed"))\n\n  case CloseAccountError.OutstandingBalance(amount) =>\n    UnprocessableEntity(Json.obj(\n      "code" -> "outstanding_balance",\n      "amount" -> amount\n    ))\n}\n\nservice.close(id).map {\n  case Right(account) => Ok(Json.toJson(AccountResponse.from(account)))\n  case Left(error)    => render(error)\n}' } },
      { heading: 'Compose operations without discarding the error type', paragraphs: ['Because Either is right-biased, a for-comprehension can sequence dependent operations. The first Left stops the remaining steps and becomes the result. Each step must agree on the error type, so boundary-specific failures often need to be translated into the operation’s vocabulary.', 'map changes a successful value. flatMap starts another operation that may fail. left.map changes the error while leaving a Right untouched. These operations keep the happy path linear without making failure invisible.', 'Do not widen every error to Throwable merely to make types line up. Translate low-level errors into a meaningful application error where the abstraction changes, and retain the original cause in logs when it is operationally useful.'], code: { label: 'Translate errors while composing a command', language: 'scala 2.13', source: 'def create(input: CreateAccountRequest): Either[CreateAccountError, Account] =\n  for {\n    name <- AccountName.from(input.name)\n      .left.map(CreateAccountError.InvalidName)\n    balance <- OpeningBalance.from(input.openingBalance)\n      .left.map(CreateAccountError.InvalidBalance)\n    account <- Account.open(name, balance)\n  } yield account' } },
      { heading: 'Future and Either describe different kinds of failure', paragraphs: ['Future[A] represents an asynchronous result and has a success or failure channel. Either[E, A] represents an expected typed choice. Combining them as Future[Either[E, A]] is reasonable when an asynchronous operation can complete successfully with either a domain rejection or a domain success.', 'A failed Future should normally mean the operation could not produce that answer: the database was unavailable, a timeout expired or an unexpected defect occurred. A successful Future containing Left means the operation ran and produced a known negative result.', 'Nested types add handling code, but collapsing both channels into failed Futures loses information. Keep the distinction where callers respond differently, then translate it once at a boundary such as a Play controller. Effect systems can encode typed errors differently, but the same design question remains: which failures are part of the operation’s declared result?'], code: { label: 'Keep operational failure separate from domain rejection', language: 'scala 2.13', source: 'def close(id: AccountId): Future[Either[CloseAccountError, Account]] =\n  repository.find(id).flatMap {\n    case None =>\n      Future.successful(Left(CloseAccountError.NotFound(id)))\n\n    case Some(account) =>\n      closeAccount(account) match {\n        case left @ Left(_) => Future.successful(left)\n        case Right(closed)  => repository.save(closed).map(_ => Right(closed))\n      }\n  }\n\n// A repository outage remains a failed Future.' } },
      { heading: 'Fail-fast and error accumulation solve different problems', paragraphs: ['Either’s flatMap is fail-fast because a later step may depend on the value produced by an earlier one. That behaviour is appropriate for workflows such as loading an account and then applying a transition.', 'Independent input validation may need to report several problems together. Play JSON validation can accumulate structural errors, and functional libraries provide applicative validation types such as Cats Validated. Accumulation requires a way to combine errors and is appropriate only when checks are independent.', 'Do not run a dependent operation after its prerequisite failed merely to collect more messages. Choose fail-fast sequencing for dependencies and accumulation for independent fields, then convert the validated input into a domain command.'], bullets: ['Use Either when later work depends on earlier success', 'Accumulate independent request-field errors when it improves the client experience', 'Keep operational causes available for logging and diagnosis', 'Avoid returning internal exception messages through an API'] },
      { heading: 'Typed errors are still part of a public contract', paragraphs: ['Once another module matches on an error case, that case is part of the interface. Renaming, removing or broadening it can require coordinated changes just like changing a successful return type.', 'Errors should contain enough information for a caller to decide what to do, but not database implementation details or sensitive data. Logging belongs near the boundary that has both technical context and responsibility for the failure; logging the same Left in every layer creates duplicated noise.', 'Error values work best when they improve a concrete decision. If every caller immediately converts an elaborate hierarchy into the same generic response, the model is probably more detailed than the application needs.'] },
    ],
  },
  {
    slug: 'monads-in-practical-scala', title: 'Option, Either and other monads in practical Scala', category: 'Functional Scala', topic: 'Scala', readTime: '14 min read',
    summary: 'How Option, Either, collections, Future and IO represent different computational contexts—and how map, flatMap and for-comprehensions compose them.',
    sections: [
      { heading: 'The abstraction is about sequencing in a context', paragraphs: ['A type such as Option[A], Either[E, A], Future[A] or IO[A] contains or describes an A with some additional computational context. The context may represent absence, an expected error, asynchronous completion or an effectful program.', 'A monad provides an operation that places a plain value into that context—commonly called pure—and flatMap, which sequences a contextual value into the next contextual computation. In simplified form, flatMap has the shape F[A] => (A => F[B]) => F[B].', 'The abstraction lets code describe dependent steps without manually unpacking and rebuilding the context at every line. It does not make all contexts behave alike. Option can stop with None, Either with Left, Future can fail asynchronously, and IO describes work for a runtime to execute.'], code: { label: 'The essential shape of the abstraction', language: 'scala / pseudocode', source: 'trait Monad[F[_]] {\n  def pure[A](value: A): F[A]\n\n  def flatMap[A, B](value: F[A])(next: A => F[B]): F[B]\n}\n\n// map can be derived from pure and flatMap\ndef map[A, B](value: F[A])(f: A => B): F[B] =\n  flatMap(value)(a => pure(f(a)))' } },
      { heading: 'Option sequences computations that may be absent', paragraphs: ['For Option, pure creates Some(value). flatMap applies the next function to a Some and propagates None without calling it. A chain therefore stops at the first absent value.', 'This is useful when absence itself is sufficient information. If callers need to know whether input was malformed, data was missing or access was denied, Either with a specific error type carries a more useful context.', 'The for-comprehension is syntax for the same map and flatMap calls. It improves readability but does not introduce a different execution model.'], code: { label: 'Sequence dependent optional lookups', language: 'scala 2.13', source: 'def primaryAddress(user: User): Option[Address] =\n  for {\n    addressId <- user.primaryAddressId\n    address   <- addresses.get(addressId)\n  } yield address\n\n// Equivalent shape:\nuser.primaryAddressId.flatMap { addressId =>\n  addresses.get(addressId).map(address => address)\n}' } },
      { heading: 'Either preserves a typed failure', paragraphs: ['For Either[E, *], the context includes a fixed error type E. flatMap runs the next step for Right and propagates Left. This makes it suitable for fail-fast validation and domain workflows in which later steps depend on earlier results.', 'The error type must remain compatible throughout the chain. Translating a parsing error and a domain error into one operation-specific algebra is often clearer than widening everything to Exception or String.', 'This also shows why a monad is a relationship over a type constructor, not a label attached to a class in isolation. Either becomes a one-parameter context only after its left-hand error type is fixed.'], code: { label: 'Fix the error type and sequence the successful side', language: 'scala 2.13', source: 'type Result[A] = Either[CreateOrderError, A]\n\ndef createOrder(input: CreateOrderRequest): Result[Order] =\n  for {\n    accountId <- parseAccountId(input.accountId)\n    amount    <- parseAmount(input.amount)\n    order     <- Order.create(accountId, amount)\n  } yield order' } },
      { heading: 'Future and IO obey similar interfaces with different timing', paragraphs: ['Creating a Future normally schedules its body immediately on an ExecutionContext. A Cats Effect IO value describes a computation and does not run it merely because it was constructed. Both support map and flatMap, but substituting one for the other changes execution, cancellation and resource semantics.', 'Future memoises its eventual result: attaching several transformations to the same Future observes the same completed computation. Running the same IO value more than once interprets its description more than once unless the program explicitly memoises it.', 'Generic syntax can hide these differences, so engineers still need to understand the concrete effect. A typeclass removes repeated sequencing code; it does not remove operational behaviour such as thread usage, blocking work, cancellation or resource lifetime.'], code: { label: 'Similar composition does not mean similar execution', language: 'scala / Cats Effect', source: 'val future: Future[UUID] = Future(UUID.randomUUID())\nval firstFuture  = future\nval secondFuture = future // observes the same scheduled computation\n\nval io: IO[UUID] = IO(UUID.randomUUID())\nval program = for {\n  first  <- io\n  second <- io // evaluates the description again\n} yield (first, second)' } },
      { heading: 'Collections and Try add different meanings again', paragraphs: ['List is also a monad. Its context is multiplicity: a step can produce zero, one or many results, and flatMap concatenates those results. A for-comprehension over two lists therefore produces combinations; it does not fail fast like Either or schedule work like Future.', 'Try captures a thrown non-fatal exception as Success or Failure. It is useful around exception-based APIs, but Throwable is usually too broad for an application contract. Convert to a meaningful error type when the code crosses from an implementation detail into domain or application behaviour.', 'Sharing map and flatMap does not make these types interchangeable. The outer type communicates what kind of program is being composed, and changing it changes the observable meaning of the code.'], code: { label: 'The context decides what flatMap means', language: 'scala 2.13', source: 'val combinations: List[String] =\n  List("small", "large").flatMap { size =>\n    List("sage", "plum").map(colour => s"$size-$colour")\n  }\n\nval port: Try[Int] = Try(configuration.getString("port").toInt)\n\nval validatedPort: Either[ConfigurationError, Int] =\n  port.toEither.left.map(error =>\n    ConfigurationError.InvalidPort(error.getMessage)\n  )' } },
      { heading: 'Nested contexts preserve more than one concern', paragraphs: ['Real services often need more than one context. Future[Either[AccountError, Account]] distinguishes asynchronous operational failure from an expected account result. Neither layer is redundant, so a single flatMap cannot remove both.', 'The direct version is often clearest for a short workflow: flatMap the Future, then map or flatMap the Either inside it. When this pattern dominates a larger module, Cats EitherT can provide one compositional interface while retaining both layers.', 'A transformer reduces nesting syntax; it does not remove the need to decide which errors belong in Left and which failures belong to the outer effect. Introduce it when repeated composition is the problem, not merely because a nested type looks untidy.'], code: { label: 'Compose Future and Either without losing either meaning', language: 'scala 2.13 / Cats', source: 'import cats.data.EitherT\nimport scala.concurrent.Future\n\ntype AsyncResult[A] = EitherT[Future, AccountError, A]\n\ndef load(id: AccountId): AsyncResult[Account] =\n  EitherT(repository.find(id).map {\n    case Some(account) => Right(account)\n    case None          => Left(AccountError.NotFound(id))\n  })\n\ndef rename(id: AccountId, name: AccountName): AsyncResult[Account] =\n  for {\n    account <- load(id)\n    renamed <- EitherT.fromEither[Future](account.rename(name))\n    _       <- EitherT.liftF(repository.save(renamed))\n  } yield renamed' } },
      { heading: 'The laws protect refactoring', paragraphs: ['Monad instances are expected to satisfy left identity, right identity and associativity. Left identity says that placing a value in the context and immediately flatMapping a function is equivalent to calling the function. Right identity says flatMapping pure does not change the computation. Associativity says regrouping dependent flatMap calls does not change the result.', 'These are behavioural equivalences, not necessarily identical implementation steps. They matter because for-comprehensions, helper functions and library combinators routinely regroup expressions. Without the laws, apparently harmless refactoring could alter meaning.', 'Side effects performed while constructing values can break reasoning even when the underlying data type has a lawful instance. Keep effects suspended in the effect type or controlled at explicit boundaries rather than hiding them inside functions presented as pure.'], code: { label: 'The three monad laws', language: 'scala / pseudocode', source: '// Left identity\npure(a).flatMap(f) == f(a)\n\n// Right identity\nfa.flatMap(pure) == fa\n\n// Associativity\nfa.flatMap(f).flatMap(g) ==\n  fa.flatMap(a => f(a).flatMap(g))' } },
      { heading: 'Generic code is useful when the capability is genuinely generic', paragraphs: ['Cats exposes Monad[F] as a typeclass, allowing a function to sequence any F with a lawful instance. This is valuable for reusable libraries and application modules whose logic genuinely depends only on sequencing.', 'Application code does not need to abstract over every concrete effect. A service written directly in Future or IO is often easier for its team to understand, test and operate. Introducing F[_] also introduces typeclass constraints, syntax imports and decisions about which effects are permitted.', 'Start with the concrete program. Abstract when two real interpreters, reusable logic or a testable capability boundary justify it. Monad is a precise and useful vocabulary for composition; it is not an architectural objective by itself.'], code: { label: 'State only the capability a generic program needs', language: 'scala / Cats', source: 'import cats.Monad\nimport cats.syntax.flatMap._\nimport cats.syntax.functor._\n\ndef enrich[F[_]: Monad](\n  load: AccountId => F[Account],\n  score: Account => F[Score],\n  id: AccountId\n): F[ScoredAccount] =\n  for {\n    account <- load(id)\n    value   <- score(account)\n  } yield ScoredAccount(account, value)' } },
    ],
  },
  {
    slug: 'scala-collections-in-practice', title: 'Scala collections in practice', category: 'Scala', topic: 'Scala', readTime: '14 min read',
    summary: 'How to choose and transform immutable Scala collections, avoid accidental work, and recognise the performance and semantic differences between List, Vector, Set, Map, View and Iterator.',
    sections: [
      { heading: 'Choose a collection for its meaning and operations', paragraphs: ['A collection type is part of a method contract. Seq promises ordering, Set promises uniqueness and Map associates unique keys with values. A concrete type adds operational expectations: List is a linked sequence, while Vector is an indexed immutable sequence.', 'Start with the behaviour callers need. Return Seq when callers only need ordered traversal; return Set when duplicates would be a modelling error; return Map when lookup by a stable key is the point. Exposing a mutable implementation or an unnecessarily specific concrete type gives callers constraints they may start to depend on.', 'Immutable collections are the normal default in Scala. Operations such as updated, + and map return new values while safely sharing unchanged structure internally. A val can therefore refer to a collection whose implementation is efficient without permitting another part of the program to mutate it.'], code: { label: 'Let the result type state the collection contract', language: 'scala 2.13', source: 'final case class AccountId(value: String)\nfinal case class Account(id: AccountId, name: String)\n\ndef accountsInDisplayOrder: Seq[Account] = ???\ndef activeAccountIds: Set[AccountId] = ???\ndef accountsById: Map[AccountId, Account] = ???\n\nval renamed: Map[AccountId, Account] =\n  accountsById.updated(id, account.copy(name = "Ada"))' } },
      { heading: 'List and Vector favour different work', paragraphs: ['List provides constant-time head, tail and prepend operations. Indexing, finding its length and appending with :+ require traversal, so repeatedly appending to a List can turn a linear operation into quadratic work.', 'Vector offers effectively constant-time indexed access and updates while remaining immutable. It is often a better general-purpose sequence when code needs both traversal and indexed operations. Array is appropriate at a lower-level boundary where compact storage, Java interoperation or controlled mutation matters.', 'Small collections rarely justify elaborate optimisation. The important habit is to notice operations inside loops and folds. Building a List by prepending and reversing once, or using a builder, expresses the same result without repeatedly walking the accumulated prefix.'], code: { label: 'Build a List without repeated append traversal', language: 'scala 2.13', source: 'def normalise(values: List[String]): List[String] = {\n  val reversed = values.foldLeft(List.empty[String]) {\n    case (result, raw) => raw.trim.toLowerCase :: result\n  }\n\n  reversed.reverse\n}\n\n// For a general indexed sequence:\nval names: Vector[String] = Vector("Ada", "Grace")\nval updated = names.updated(1, "Hopper")' } },
      { heading: 'Set and Map encode identity decisions', paragraphs: ['A Set removes duplicates according to equality and hashing. A Map does the same for keys, retaining one value for each key. Choosing the key is therefore a domain decision: grouping accounts by display name is unsafe when names are not unique, while AccountId may provide the identity the operation requires.', 'Map.apply throws when a key is absent. Use get when absence must remain explicit, getOrElse when there is a genuine default, or an operation-specific Either when a missing entry is an error that callers need to understand.', 'Conversions can silently discard information. Calling toMap on pairs with duplicate keys keeps one value, and calling toSet removes repeated elements. Make that collapse deliberate, particularly when it happens at an application boundary.'], code: { label: 'Make a missing key part of the result', language: 'scala 2.13', source: 'sealed trait LookupError\nobject LookupError {\n  final case class AccountNotFound(id: AccountId) extends LookupError\n}\n\ndef find(\n  accounts: Map[AccountId, Account],\n  id: AccountId\n): Either[LookupError, Account] =\n  accounts.get(id).toRight(LookupError.AccountNotFound(id))' } },
      { heading: 'map, flatMap and collect describe different transformations', paragraphs: ['map produces one output for each input while preserving the collection shape where the operation permits it. flatMap lets each input produce zero, one or many outputs and concatenates them. filter retains original elements that satisfy a predicate.', 'collect combines filtering and transformation through a partial function. It is useful when only some input cases produce an output, especially with a sealed hierarchy. collectFirst stops at the first defined result rather than building every match.', 'Avoid chaining several full traversals without considering the data size and clarity. One collect can be clearer than filter followed by map, but combining unrelated business decisions into a dense partial function is not an improvement.'], code: { label: 'Select and transform one pass', language: 'scala 2.13', source: 'sealed trait Event\nfinal case class AccountOpened(id: AccountId) extends Event\nfinal case class AccountClosed(id: AccountId) extends Event\nfinal case class AuditRecorded(message: String) extends Event\n\nval affectedAccounts: List[AccountId] = events.collect {\n  case AccountOpened(id) => id\n  case AccountClosed(id) => id\n}\n\nval firstClosure: Option[AccountId] = events.collectFirst {\n  case AccountClosed(id) => id\n}' } },
      { heading: 'Prefer total folds to unsafe reductions', paragraphs: ['foldLeft carries an explicit initial value through a collection and works for empty input. reduce combines elements without an initial value and throws for an empty collection. If emptiness is possible, the initial value in a fold makes the intended result visible.', 'Scala 2.13 provides groupMap and groupMapReduce for common grouping operations. They avoid constructing an intermediate grouped collection only to map or reduce each group afterwards.', 'A fold can still hide too much. If the accumulator contains unrelated flags, maps and counters, name a small state type or split the operation. The goal is to make the transition from one state to the next obvious.'], code: { label: 'Aggregate with an explicit empty result', language: 'scala 2.13', source: 'val total: BigDecimal =\n  payments.foldLeft(BigDecimal(0))(_ + _.amount)\n\nval namesByStatus: Map[Status, List[String]] =\n  accounts.groupMap(_.status)(_.name)\n\nval totalsByAccount: Map[AccountId, BigDecimal] =\n  payments.groupMapReduce(_.accountId)(_.amount)(_ + _)' } },
      { heading: 'Views and iterators postpone work in different ways', paragraphs: ['Most ordinary collection transformations are strict: map creates its result before returning. View builds a reusable description of transformations and evaluates elements when the view is consumed. Iterator is also lazy but stateful and normally single-use.', 'A view can avoid large intermediate collections when several transformations are chained, but it can also repeat expensive work if consumed more than once. Convert with toVector, toList or another strict collection when the result needs a stable materialised value.', 'In Scala 2.13, mapValues and filterKeys return views. That catches code migrated from older collections where the apparent Map was often treated as a realised result. Use view.mapValues(...).toMap when lazy projection is not the intended contract.'], code: { label: 'Make laziness and materialisation explicit', language: 'scala 2.13', source: 'val activeNames: Vector[String] = accounts\n  .view\n  .filter(_.isActive)\n  .map(_.name.trim)\n  .filter(_.nonEmpty)\n  .toVector\n\nval balances: Map[AccountId, BigDecimal] =\n  accountsById.view.mapValues(_.balance).toMap\n\nval lines: Iterator[String] = source.getLines()\n// Consuming lines advances the iterator.' } },
      { heading: 'Interop makes mutability especially important', paragraphs: ['Scala 2.13 uses scala.jdk.CollectionConverters._ to convert between Scala and Java collections. Conversions are generally adapters over the same underlying collection rather than deep immutable copies. Mutating a Java list obtained from a mutable Scala buffer can therefore be visible from both sides.', 'Converting an immutable Scala collection to a Java interface does not make mutation valid. If an API requires ownership of a mutable collection, create an explicit copy at that boundary rather than allowing implementation assumptions to leak through the application.', 'Review collection code by asking about meaning first and cost second: are ordering, uniqueness and absence correct; is mutation owned; can the input be empty; is evaluation strict or deferred; and does an operation inside a loop repeatedly traverse accumulated data?'], code: { label: 'Treat conversion and copying as separate decisions', language: 'scala 2.13', source: 'import scala.jdk.CollectionConverters._\n\nval scalaNames: Vector[String] = Vector("Ada", "Grace")\nval javaView: java.util.List[String] = scalaNames.asJava\n\n// When a Java API will mutate the list, give it an owned copy.\nval mutableCopy = new java.util.ArrayList[String](javaView)\nlegacyApi.populate(mutableCopy)' } },
    ],
  },
  {
    slug: 'recursion-and-tail-recursion-in-scala', title: 'Recursion and tail recursion in Scala', category: 'Scala', topic: 'Scala', readTime: '12 min read',
    summary: 'How recursive Scala functions use the call stack, how @tailrec makes constant-stack loops possible, and when folds or explicit work queues are the clearer design.',
    sections: [
      { heading: 'Recursion needs a smaller problem and a stopping point', paragraphs: ['A recursive function defines a result in terms of another call to itself. Useful recursion has a base case that returns directly and a recursive case that moves measurably closer to that base case. Without both, the function either does not compile into sensible behaviour or never terminates.', 'Linked structures make recursion natural. A List is either Nil or a head followed by a tail, and a tree is a node containing smaller trees. Pattern matching can make those cases visible in the same shape as the data.', 'Correctness is only the first concern. Every ordinary recursive call retains a stack frame until the nested call returns. A function that works on ten values may throw StackOverflowError on a sufficiently large input.'], code: { label: 'A correct but non-tail-recursive sum', language: 'scala 2.13', source: 'def sum(values: List[Int]): Int = values match {\n  case Nil          => 0\n  case head :: tail => head + sum(tail)\n}\n\n// The addition happens after sum(tail) returns, so each\n// call must remain on the stack.' } },
      { heading: 'A tail call is the final operation', paragraphs: ['A function is tail-recursive only when the recursive call is the last operation performed by that branch. The caller has no addition, construction or other work left to do after the nested call returns, so the compiler can reuse the current stack frame.', 'The scala.annotation.tailrec annotation asks the compiler to verify that optimisation is possible. It turns an assumption about stack safety into a compile-time guarantee and should be used whenever a method is intentionally tail-recursive.', 'Tail recursion is an implementation property, not simply a function that happens to call itself near the bottom of the source. head + sum(tail), for example, still needs the current head after the recursive result arrives and is not a tail call.'], code: { label: 'Move pending work into an accumulator', language: 'scala 2.13', source: 'import scala.annotation.tailrec\n\ndef sum(values: List[Int]): Int = {\n  @tailrec\n  def loop(remaining: List[Int], total: Int): Int =\n    remaining match {\n      case Nil          => total\n      case head :: tail => loop(tail, total + head)\n    }\n\n  loop(values, 0)\n}' } },
      { heading: 'Accumulators change when work happens', paragraphs: ['Converting a function to tail recursion usually means adding an accumulator containing the partial answer. Instead of waiting for a recursive result and then combining it, each step computes the next state before making the tail call.', 'Order matters. Prepending to a List is constant time, so a tail-recursive transformation often builds its result backwards and reverses once at the end. Repeatedly appending with :+ would preserve order locally but repeatedly traverse the accumulated list.', 'An accumulator should have a clear invariant: total is the sum of values already visited, or reversed contains the transformed prefix in reverse order. Naming that invariant makes the loop easier to test and review.'], code: { label: 'Build backwards, then reverse once', language: 'scala 2.13', source: 'import scala.annotation.tailrec\n\ndef normalise(values: List[String]): List[String] = {\n  @tailrec\n  def loop(\n    remaining: List[String],\n    reversed: List[String]\n  ): List[String] = remaining match {\n    case Nil => reversed.reverse\n    case head :: tail =>\n      loop(tail, head.trim.toLowerCase :: reversed)\n  }\n\n  loop(values, Nil)\n}' } },
      { heading: 'Direct tree recursion is not usually tail-recursive', paragraphs: ['A tree branch may require results from two or more recursive calls before the current node can be completed. Those calls are not in tail position, and @tailrec correctly rejects the method. Balanced trees may remain safe because their depth is small, while a deeply skewed or externally supplied tree can exhaust the stack.', 'Stack safety can be recovered by representing pending work as data. An explicit List can act as a work stack: take one node, add its children to the remaining work and tail-call with the updated accumulator.', 'This trades call-stack use for heap allocation and may change traversal order. Choose depth-first or breadth-first deliberately when order affects output, early termination or memory use.'], code: { label: 'Traverse a tree with an explicit work stack', language: 'scala 2.13', source: 'import scala.annotation.tailrec\n\nsealed trait Tree[+A]\ncase object Empty extends Tree[Nothing]\nfinal case class Node[A](\n  value: A,\n  left: Tree[A],\n  right: Tree[A]\n) extends Tree[A]\n\n@tailrec\ndef size[A](pending: List[Tree[A]], count: Int = 0): Int =\n  pending match {\n    case Nil => count\n    case Empty :: rest => size(rest, count)\n    case Node(_, left, right) :: rest =>\n      size(left :: right :: rest, count + 1)\n  }' } },
      { heading: 'Mutual recursion and effects need separate care', paragraphs: ['The compiler can optimise direct self-recursion in tail position, but mutually recursive methods do not receive the same guarantee. Two methods that call one another can still overflow even when each call appears last in its method.', 'Recursion across Future.flatMap callbacks also does not become safe merely because flatMap appears last. The execution model determines when callbacks run. Effect libraries such as Cats Effect provide stack-safe flatMap for effect programs, but pure recursive work performed before constructing the next effect can still overflow.', 'For general recursion expressed through an effect, Cats provides abstractions such as tailRecM. At application level, a collection combinator, an explicit work queue or a library traversal is often easier to understand than implementing the abstraction directly.'], code: { label: 'Do not hide eager recursion inside an effect constructor', language: 'scala / Cats Effect', source: 'def unsafeLoop(value: Int): IO[Int] =\n  if (value <= 0) IO.pure(0)\n  else unsafeLoop(value - 1).map(_ + 1)\n\n// The recursive call happens while building the IO value.\n// Prefer a stack-safe combinator or an explicit iterative state.' } },
      { heading: 'Collection operations are often the better vocabulary', paragraphs: ['Many recursive list functions are already captured by map, collect, exists, find and foldLeft. These operations state the intent directly, are familiar to Scala developers and use stack-safe implementations for ordinary strict collections.', 'Writing the recursion yourself is justified when the data is naturally recursive, traversal needs unusual control, several pieces of state must evolve together or early termination has domain-specific rules. It can also be useful when teaching or measuring an algorithm, but production code should not make the reader rediscover a standard fold.', 'A fold is not automatically clearer. When its accumulator becomes a tuple of several unrelated values, a named state case class or a small @tailrec loop can expose the transition more plainly.'], code: { label: 'Use the operation that names the intent', language: 'scala 2.13', source: 'val total: Int = values.foldLeft(0)(_ + _)\nval normalised: List[String] = values.map(_.trim.toLowerCase)\nval firstInvalid: Option[String] = values.find(value => !isValid(value))\n\nfinal case class State(total: BigDecimal, rejected: Vector[Payment])\n\nval result = payments.foldLeft(State(BigDecimal(0), Vector.empty)) {\n  case (state, payment) if payment.accepted =>\n    state.copy(total = state.total + payment.amount)\n  case (state, payment) =>\n    state.copy(rejected = state.rejected :+ payment)\n}' } },
      { heading: 'Test boundaries, not only examples', paragraphs: ['Recursive code deserves tests for the empty structure, one element, ordinary input and the largest realistic depth. Property-based tests can compare an implementation with a simpler reference or check invariants such as reversing twice returning the original list.', 'A @tailrec annotation proves that direct self-calls are optimised; it does not prove termination, correctness or sensible memory use. A loop can be constant-stack and infinite, or move a huge pending structure from the stack to the heap.', 'During review, identify the decreasing input, base case, accumulator invariant and maximum expected depth. If any of those are hard to state, the implementation is asking readers to trust more than the code demonstrates.'], bullets: ['Annotate intentional tail recursion with @tailrec', 'Check that every recursive branch moves toward a base case', 'Avoid repeated List append in accumulators', 'Use an explicit work structure for deeply nested trees or graphs', 'Prefer standard collection combinators when they express the operation directly', 'Test empty input and realistic worst-case depth'] },
    ],
  },
  {
    slug: 'map-and-flatmap-in-scala', title: '.map and .flatMap in Scala: follow the types', category: 'Functional Scala', topic: 'Scala', readTime: '11 min read',
    summary: 'A type-led guide to transforming and sequencing Option, Either, collections, Future and IO, including for-comprehension translation and common nesting mistakes.',
    sections: [
      { heading: 'map changes the value while preserving the shape', paragraphs: ['Given a context F[A] and a function A => B, map produces F[B]. It transforms the value inside the context while retaining the context’s structure: Some remains optional, Right remains capable of carrying the same error type, and Future remains asynchronous.', 'The function passed to map returns a plain B. If it returns another contextual value F[B], the result becomes F[F[B]]. That nesting may be meaningful, but it is often the signal that the next operation is already effectful and flatMap is required.', 'Reading the types is more reliable than memorising syntax. Ask what you currently have, what the callback returns and what the whole expression should return.'], code: { label: 'Transform without changing the surrounding context', language: 'scala 2.13', source: 'val raw: Option[String] = Some("  ADA  ")\nval normalised: Option[String] = raw.map(_.trim.toLowerCase)\n\nval amount: Either[String, BigDecimal] = Right(BigDecimal(20))\nval withTax: Either[String, BigDecimal] = amount.map(_ * BigDecimal("1.2"))\n\nval account: Future[Account] = repository.findRequired(id)\nval name: Future[String] = account.map(_.name)' } },
      { heading: 'flatMap sequences a function that already returns a context', paragraphs: ['flatMap takes A => F[B] rather than A => B and returns F[B]. The outer context controls whether and how the next function runs. Option skips it for None, Either skips it for Left, and Future schedules the continuation after successful completion.', 'Using map with an effectful function creates nesting such as Option[Option[Address]] or Future[Future[Account]]. Calling flatten can remove one layer when both layers have the same compatible shape, but flatMap states the sequencing intent directly.', 'If the two contexts differ—Future[Either[E, A]], for example—ordinary flatMap cannot erase both. Each layer represents different information and must be composed or transformed deliberately.'], code: { label: 'Avoid accidental nesting', language: 'scala 2.13', source: 'def parseId(raw: String): Option[AccountId] = ???\ndef find(id: AccountId): Option[Account] = ???\n\nval nested: Option[Option[Account]] =\n  parseId("a-17").map(find)\n\nval account: Option[Account] =\n  parseId("a-17").flatMap(find)\n\nval alsoAccount: Option[Account] = nested.flatten' } },
      { heading: 'A for-comprehension is translated into these operations', paragraphs: ['A for-comprehension with several generators becomes nested flatMap calls, with map normally used for the final yield. This explains why every generator generally needs to use the same surrounding context.', 'Assignments inside a comprehension are transformations of values already produced. Guards use withFilter, whose behaviour and cost depend on the type. A guard on Option can produce None; a collection guard removes elements; not every custom effect provides a useful withFilter.', 'When a comprehension fails to compile, expand it mentally or in a scratch file. The mismatch is usually visible at the first generator whose callback returns a different shape.'], code: { label: 'See the flatMap and map beneath the syntax', language: 'scala 2.13', source: 'val result: Either[OrderError, Order] = for {\n  account <- loadAccount(accountId)\n  amount  <- Amount.from(rawAmount)\n  order   <- Order.create(account, amount)\n} yield order\n\nval equivalent: Either[OrderError, Order] =\n  loadAccount(accountId).flatMap { account =>\n    Amount.from(rawAmount).flatMap { amount =>\n      Order.create(account, amount).map { order =>\n        order\n      }\n    }\n  }' } },
      { heading: 'Collections use flatMap to express multiplicity', paragraphs: ['For List, flatMap applies a function that returns a List to every element and concatenates the results. The next step can produce zero, one or many values, so flatMap expresses both transformation and changed multiplicity.', 'This is why a for-comprehension over two lists produces combinations rather than sequencing one asynchronous action. The method names are shared, but the concrete type determines the operational meaning.', 'Option can be viewed as zero-or-one multiplicity, which makes its relationship to collection operations intuitive. Future and IO need a different mental model because they represent computations, not merely containers.'], code: { label: 'One input can produce several outputs', language: 'scala 2.13', source: 'val sizes  = List("small", "large")\nval colours = List("sage", "plum")\n\nval variants: List[String] = for {\n  size   <- sizes\n  colour <- colours\n} yield s"$size-$colour"\n\n// List("small-sage", "small-plum",\n//      "large-sage", "large-plum")' } },
      { heading: 'Future runs callbacks through an ExecutionContext', paragraphs: ['Future.map and flatMap register callbacks that run through an ExecutionContext after successful completion. If the original Future fails, the transformation is skipped and the failure propagates. If the callback throws, the returned Future becomes failed.', 'Avoid blocking database or network work inside a map callback on Play’s default execution context. The callback may look like an ordinary function, but its thread usage affects request throughput. Use an execution context intended for blocking work or an asynchronous client.', 'Creating independent Futures before a for-comprehension allows them to begin independently; creating the second inside flatMap makes it dependent and therefore sequential. Choose based on data dependency rather than surface neatness.'], code: { label: 'Construction position changes concurrency', language: 'scala 2.13', source: '// Independent operations are started before they are combined.\nval accountF = accounts.find(accountId)\nval scoreF   = scores.find(accountId)\n\nval combined: Future[Assessment] = for {\n  account <- accountF\n  score   <- scoreF\n} yield Assessment(account, score)\n\n// If scores.find needs account, create it inside flatMap instead.' } },
      { heading: 'IO describes composition before the runtime executes it', paragraphs: ['With Cats Effect IO, map and flatMap construct a larger description of work. They do not execute the effect at each line. The runtime interprets the completed program at the application boundary.', 'Use map for pure transformation of a computed value and flatMap when the next step itself returns IO. Pure calculations do not need to be wrapped in IO merely to make a for-comprehension visually uniform.', 'Resource builds on this compositional model to pair acquisition with release. When work involves files, connections or other lifecycles, composing Resource values is safer than acquiring in one flatMap and hoping a later callback always closes them.'], code: { label: 'Keep pure transformation distinct from the next effect', language: 'scala / Cats Effect', source: 'def load(id: AccountId): IO[Account] = ???\ndef save(account: Account): IO[Unit] = ???\n\ndef rename(id: AccountId, name: AccountName): IO[Account] =\n  load(id).flatMap { account =>\n    val renamed = account.copy(name = name) // pure\n    save(renamed).map(_ => renamed)         // next effect\n  }' } },
      { heading: 'Let the desired result type choose the operator', paragraphs: ['Use map when the callback returns the plain value you want inside the same context. Use flatMap when the callback already returns that context and the operations are dependent. Use separate combinators for independent effects when the concrete library provides them.', 'Do not reach for flatMap simply because it feels more powerful. map states a stronger constraint: the callback is an ordinary transformation and cannot introduce another effect of the same type. That restriction makes code easier to reason about.', 'When types become deeply nested, naming intermediate results and the intended final type usually helps more than adding syntax. The compiler error is often describing a real unresolved design question about absence, failure, asynchrony or effect execution.'] },
    ],
  },
  {
    slug: 'implicits-and-context-bounds-in-scala', title: 'Implicits in Scala: parameters, scope and context bounds', category: 'Scala type system', topic: 'Scala', readTime: '14 min read',
    summary: 'How implicit parameters, implicit scope and context bounds work in Scala 2.13, how Scala 3 expresses the same ideas, and where invisible dependencies become a maintenance problem.',
    sections: [
      { heading: 'An implicit parameter is still a parameter', paragraphs: ['Scala 2.13 can fill an implicit parameter when the caller omits it and exactly one suitable value can be found. The dependency remains part of the method signature; the compiler is performing argument resolution rather than creating a global value.', 'This is useful for stable contextual capabilities such as an Ordering, ExecutionContext or typeclass instance. It becomes harder to reason about when large services, request-specific state or behaviour with surprising side effects arrive implicitly.', 'A caller can always pass the argument explicitly. Doing so is useful while debugging resolution and at boundaries where the chosen instance deserves to be visible.'], code: { label: 'Make the inferred argument visible', language: 'scala 2.13', source: 'final case class TraceId(value: String)\n\ndef audit(message: String)(implicit traceId: TraceId): String =\n  s"[${traceId.value}] $message"\n\nimplicit val currentTrace: TraceId = TraceId("trace-17")\n\naudit("account loaded")\naudit("account loaded")(currentTrace)' } },
      { heading: 'Implicit scope determines which value wins', paragraphs: ['The compiler first considers eligible identifiers available without a prefix, including local definitions, inherited members and imports. It also considers the implicit scope associated with the requested type, especially companion objects of the involved types.', 'A canonical typeclass instance often belongs in the companion of the data type or typeclass so it can be found without a broad import. Alternative policies should be named and imported close to the place selecting them.', 'No candidate produces a missing implicit error; several equally eligible candidates produce an ambiguity. Adding a wildcard import until the error disappears can make instance ownership less predictable. Ask which exact type is required and where its instance should live.'], code: { label: 'Keep the default instance discoverable', language: 'scala 2.13', source: 'trait Display[A] {\n  def apply(value: A): String\n}\n\nfinal case class AccountId(value: String)\n\nobject AccountId {\n  implicit val displayAccountId: Display[AccountId] =\n    new Display[AccountId] {\n      def apply(value: AccountId): String = value.value\n    }\n}\n\ndef display[A](value: A)(implicit D: Display[A]): String = D(value)\n\ndisplay(AccountId("a-17"))' } },
      { heading: 'A context bound is shorthand for evidence', paragraphs: ['A declaration such as [A: Ordering] means the method requires an implicit Ordering[A]. In Scala 2.13 it is essentially shorthand for an additional implicit parameter and does not change A itself.', 'Use implicitly to retrieve the evidence when the method body needs it, or name the implicit parameter when the instance is central to the implementation. Multiple context bounds state multiple independent capabilities.', 'A context bound says that an operation is generic over A but requires known behaviour for A. If there is only one concrete type and no useful generic caller, an ordinary method or dependency may be simpler.'], code: { label: 'Expand a context bound mentally', language: 'scala 2.13', source: 'def earliest[A: Ordering](values: List[A]): Option[A] =\n  values.sorted.headOption\n\n// Equivalent requirement, with the evidence named:\ndef earliestExplicit[A](\n  values: List[A]\n)(implicit ordering: Ordering[A]): Option[A] =\n  values.sorted(ordering).headOption\n\ndef compare[A: Ordering](left: A, right: A): Int =\n  implicitly[Ordering[A]].compare(left, right)' } },
      { heading: 'Implicit conversions deserve restraint', paragraphs: ['Implicit parameters and implicit conversions use related resolution machinery but solve different problems. A conversion lets a value be treated as another type or supplies missing syntax through an implicit class. That can make an API pleasant, but it also makes method availability and runtime work less obvious.', 'Prefer implicit classes for small extension syntax in Scala 2.13 and keep their bodies thin. Avoid broad conversions between domain values: automatically converting String to AccountId bypasses the point of validating and distinguishing the identifier.', 'Compiler flags such as -feature help reveal conversion use. In review, inspect imports when a method appears to come from nowhere and confirm that the added syntax does not conceal I/O or expensive work.'], code: { label: 'Add syntax without weakening construction', language: 'scala 2.13', source: 'object DisplaySyntax {\n  implicit final class DisplayOps[A](private val value: A) extends AnyVal {\n    def display(implicit D: Display[A]): String = D(value)\n  }\n}\n\nimport DisplaySyntax._\nAccountId("a-17").display\n\n// Do not add an implicit String => AccountId conversion;\n// construct and validate the domain value explicitly.' } },
      { heading: 'Scala 3 separates the concepts', paragraphs: ['Scala 3 uses given for contextual values, using for contextual parameters and extension for extension methods. summon retrieves contextual evidence. The terminology makes intent clearer, but the same design questions about visibility, ownership and ambiguity remain.', 'Migration is not only a syntax rewrite. Import behaviour and implicit resolution differ in places, and a previously selected instance may become ambiguous or stop being found. Protect behaviour that depends on ordering, codecs or another policy with direct tests.', 'Use contextual abstraction for a real capability or context. Constructor parameters remain the clearer choice for most application services because their lifecycle and dependencies are visible where the object is assembled.'], code: { label: 'Express the same capability in Scala 3', language: 'scala 3', source: 'trait Display[A]:\n  def apply(value: A): String\n\ngiven Display[AccountId] with\n  def apply(value: AccountId): String = value.value\n\ndef display[A: Display](value: A): String =\n  summon[Display[A]](value)\n\nextension [A: Display](value: A)\n  def display: String = summon[Display[A]](value)' } },
      { heading: 'Review the hidden argument as an API decision', paragraphs: ['An implicit is healthy when callers can predict what will be selected and the dependency represents stable context or generic evidence. It is a smell when changing an import changes important behaviour, when several instances compete routinely or when reading a call gives no clue that I/O or mutable state is involved.', 'Keep implicit scopes narrow, give alternative instances descriptive names and avoid catch-all fallback instances. Compiler diagnostics become much easier when the requested type is precise and instance chains remain shallow.', 'The test is not whether implicits are advanced Scala. It is whether inference removes repetition while preserving the ability to understand the program from its types and module boundaries.'], bullets: ['Can the required contextual type be seen in the signature?', 'Is there one obvious owner for the default instance?', 'Would an explicit constructor parameter make an application dependency clearer?', 'Can a broad import silently change the selected behaviour?', 'Does extension syntax remain cheap and unsurprising?', 'Are important instance choices covered by direct tests?'] },
    ],
  },
  {
    slug: 'category-theory-in-practical-scala', title: 'Category theory in practical Scala: useful vocabulary, not the goal', category: 'Functional Scala', topic: 'Scala', readTime: '15 min read',
    summary: 'How category-theoretic ideas influence map, flatMap, typeclasses and effect libraries—and how to use that vocabulary without turning application code into an abstraction exercise.',
    sections: [
      { heading: 'Begin with objects, arrows and composition', paragraphs: ['Category theory is a branch of mathematics concerned less with what individual things contain and more with how they relate and compose. A category has objects and arrows between those objects. Every object has an identity arrow, and compatible arrows can be composed to form another arrow.', 'Imagine three objects A, B and C. An arrow f takes us from A to B, and g takes us from B to C. Composition gives g ∘ f, a route from A directly to C. The important promise is that composition follows consistent laws, so a larger route can be assembled from smaller ones without its meaning depending on arbitrary grouping.', 'The names can sound remote from application development, but the basic instinct is familiar: define small transformations with compatible boundaries, then combine them predictably. The diagram introduces the mathematical vocabulary before we translate it—carefully—into Scala.'], diagram: 'category-composition' },
      { heading: 'The influence on Scala is real, but usually indirect', paragraphs: ['Functional programming borrows category-theoretic vocabulary because programs repeatedly face the same question: how can small transformations be combined without losing the structure around their values?', 'Scala does not require category theory to write an API, model a domain or maintain a Play service. Its type system does, however, make abstractions such as higher-kinded types and typeclasses expressible. Libraries such as Cats use those features to provide lawful interfaces for composition.', 'Most application code encounters the results rather than the mathematics. Calling map on Option, sequencing Either with flatMap or combining independent validations can be useful without describing categories or proving theorems. The theory explains why the operations fit together; it need not dominate the application vocabulary.'], code: { label: 'The practical surface is familiar Scala', language: 'scala 2.13', source: 'val normalised: Option[String] =\n  submittedName.map(_.trim).filter(_.nonEmpty)\n\nval account: Either[OpenError, Account] = for {\n  name    <- AccountName.from(rawName)\n  balance <- OpeningBalance.from(rawBalance)\n  account <- Account.open(name, balance)\n} yield account\n\n// Application code can use composition without discussing\n// category-theoretic terminology at each call site.' } },
      { heading: 'Types and functions provide an analogy, not a perfect model', paragraphs: ['A common introduction treats types as objects and functions as morphisms between them. That is a useful intuition because functions compose and identity functions leave values unchanged. It is still a simplified model of real Scala.', 'Scala functions can throw, fail to terminate, mutate state or observe the outside world. Subtyping, null and JVM runtime behaviour add details that the clean mathematical model does not capture automatically. Effect types and disciplined functional design make more of that behaviour explicit, but the implementation remains a program running on a real platform.', 'Use the analogy to reason about composition, not to claim that any Scala function is automatically a pure mathematical arrow. The value comes from identifying which assumptions make a refactoring safe.'], code: { label: 'Pure composition has a predictable shape', language: 'scala 2.13', source: 'val trim: String => String = _.trim\nval lower: String => String = _.toLowerCase\nval normalise: String => String = trim.andThen(lower)\n\nnormalise("  ADA  ") // "ada"\n\n// If either function also writes a database or reads the clock,\n// the same type no longer tells the complete behavioural story.' } },
      { heading: 'Functor explains the recurring shape of map', paragraphs: ['A Functor provides map for a type constructor F[_]. Given F[A] and A => B, map produces F[B] without discarding the surrounding structure. For Option the structure is possible absence; for List it is multiplicity; for Future it is asynchronous completion.', 'A lawful map preserves identity and composition. Mapping the identity function should not change the value, and mapping two pure functions in succession should agree with mapping their composition. These laws make helper extraction and pipeline refactoring predictable.', 'The shared abstraction does not make the contexts operationally equivalent. List.map visits elements, Future.map schedules a callback through an ExecutionContext and IO.map extends a description of work. Generic vocabulary removes repeated structure, not the need to understand the concrete type.'], code: { label: 'Functor laws protect ordinary refactoring', language: 'scala / pseudocode', source: '// Identity\nfa.map(identity) == fa\n\n// Composition\nfa.map(f).map(g) == fa.map(f.andThen(g))\n\nval displayNames: Option[String] =\n  account.map(_.name).map(_.trim)\n\nval sameShape: Option[String] =\n  account.map(value => value.name.trim)' } },
      { heading: 'Monad describes dependent composition', paragraphs: ['Monad adds the ability to place a value in a context and sequence a function that returns the same context. In Scala this appears through pure and flatMap. A for-comprehension is the application-facing syntax normally used for the sequence.', 'Option stops at None, Either propagates Left and Future continues after successful asynchronous completion. The common interface is valuable when a reusable function truly needs only dependent sequencing.', 'The monad laws—left identity, right identity and associativity—constrain how that sequencing behaves. They matter because extracting a helper or regrouping flatMap calls should not silently change a program. They are engineering guarantees for composition, not decorations added to make code sound mathematical.'], code: { label: 'A law supports helper extraction', language: 'scala / pseudocode', source: '// Associativity\nfa.flatMap(f).flatMap(g) ==\n  fa.flatMap(a => f(a).flatMap(g))\n\n// That equivalence allows a sequence to be regrouped around\n// a named workflow without changing its declared meaning.' } },
      { heading: 'Other abstractions solve more specific problems', paragraphs: ['Applicative composition combines independent contextual values. In Cats, mapN can build a result from independent validations or effects without pretending the second value depends on the first. Traverse applies an effectful function across a collection and turns List[F[A]] into F[List[A]] with defined sequencing behaviour.', 'Semigroup and Monoid describe ways to combine values, with Monoid also supplying an identity element. They belong to the broader algebraic vocabulary used by functional libraries and support operations such as combining validation errors, totals or configuration fragments.', 'Names are useful when they identify a capability already present in the problem. They become noise when a team must learn several abstractions to understand a calculation that could have remained a small domain function.'], code: { label: 'Use the operation that matches the dependency', language: 'scala 2.13 / Cats', source: 'import cats.syntax.all._\n\nval name: Either[List[String], AccountName] = validateName(rawName)\nval email: Either[List[String], Email] = validateEmail(rawEmail)\n\n// The validations are independent, so applicative composition fits.\nval request: Either[List[String], Registration] =\n  (name, email).mapN(Registration.apply)\n\n// Dependent steps would instead require flatMap.' } },
      { heading: 'Typeclasses bring the vocabulary into Scala', paragraphs: ['Scala encodes many of these capabilities as typeclasses: parameterised traits with instances for concrete types. Implicit parameters in Scala 2 and given or using in Scala 3 allow generic code to request evidence such as Monad[F] or Semigroup[A].', 'This supports reusable libraries and tagless-final programs. A workflow can state that it requires sequencing without selecting IO or Future in the same module, while an interpreter supplies the concrete effect at the application boundary.', 'The abstraction has a cost. F[_], contextual evidence and syntax imports add concepts to signatures and compiler errors. Use them when multiple interpreters, reusable effect-polymorphic logic or a genuine capability boundary repays that cost—not because abstract code is presumed to be more functional.'], code: { label: 'A generic signature should earn its generality', language: 'scala 2.13 / Cats', source: 'def loadAndScore[F[_]: Monad](\n  load: AccountId => F[Account],\n  score: Account => F[Score],\n  id: AccountId\n): F[Assessment] =\n  for {\n    account <- load(id)\n    value   <- score(account)\n  } yield Assessment(account, value)\n\n// If every caller uses Future and no reuse is expected, a concrete\n// Future signature may communicate the application more honestly.' } },
      { heading: 'Domain language should remain in charge', paragraphs: ['An account system should primarily talk about accounts, balances and decisions. Functor and Monad describe how computations compose; they do not identify the business rules, valid states or useful service boundaries.', 'A technically lawful abstraction can still be badly placed. A generic repository algebra may leak storage concepts, an error hierarchy may be too broad, and a tagless-final service may obscure a simple operation behind type parameters. Category theory cannot decide those application responsibilities.', 'Keep mathematical vocabulary near infrastructure, library and composition concerns where it adds precision. Keep domain APIs expressed through meaningful case classes, sealed traits and operations. The two levels can work together without competing for every name in the codebase.'], code: { label: 'Keep the business decision concrete', language: 'scala 2.13', source: 'sealed trait WithdrawError\nobject WithdrawError {\n  case object AccountClosed extends WithdrawError\n  final case class InsufficientFunds(available: BigDecimal)\n      extends WithdrawError\n}\n\ndef withdraw(\n  account: Account,\n  amount: PositiveAmount\n): Either[WithdrawError, Account] = ???\n\n// Either supplies composition; the domain types explain the decision.' } },
      { heading: 'Be cautious without dismissing the theory', paragraphs: ['Avoiding category theory entirely can make library design and functional Scala APIs seem arbitrary. Learning the basic relationships between map, flatMap, applicative composition and laws helps engineers predict behaviour and read Typelevel code with less guesswork.', 'The opposite mistake is treating abstraction as the outcome. Warning signs include generalising before a second use exists, introducing F[_] throughout a small concrete service, using mathematical names for domain operations and accepting difficult inference as proof of sophistication.', 'A practical standard is simple: use the abstraction when it removes real duplication, states a capability accurately or protects refactoring through laws. Prefer concrete code when it makes execution, failure and ownership easier to see. The strongest Scala code is not the most abstract code; it is the code whose abstractions match the problem.'], bullets: ['Does this abstraction describe a repeated composition problem?', 'Which law or capability makes the code safer to change?', 'Do callers genuinely benefit from effect polymorphism?', 'Are execution and failure semantics still visible?', 'Does domain vocabulary remain clearer than library vocabulary?', 'Would Option, Either, Future or IO directly be easier to own?'] },
    ],
  },
  {
    slug: 'tagless-final-in-scala', title: 'Tagless-final in Scala: capabilities without the ceremony', category: 'Functional Scala', topic: 'Scala', readTime: '15 min read',
    summary: 'A practical account of tagless-final programs, effect capabilities, interpreters and testability—including when a concrete IO or Future service is the better design.',
    sections: [
      { heading: 'Separate the program from the effect that runs it', paragraphs: ['Tagless-final code describes required operations in terms of abstract capabilities and an effect type F[_]. The program composes those capabilities without committing to Future, Cats Effect IO or another concrete runtime at the point where the business workflow is defined.', 'A small algebra—usually a trait parameterised by F—states what the program can do. An interpreter implements the algebra for a concrete effect and infrastructure. The application assembles the interpreter and runs the resulting effect at its boundary.', 'The value is not the unusual name. It is the ability to keep a workflow dependent on narrow operations while delaying a concrete execution choice. That only helps when the separation corresponds to a real boundary.'], code: { label: 'Describe the capability the workflow needs', language: 'scala 2.13 / Cats', source: 'trait AccountRepository[F[_]] {\n  def find(id: AccountId): F[Option[Account]]\n  def save(account: Account): F[Unit]\n}\n\ntrait Audit[F[_]] {\n  def accountRenamed(id: AccountId): F[Unit]\n}\n\nfinal class RenameAccount[F[_]: Monad](\n  accounts: AccountRepository[F],\n  audit: Audit[F]\n) {\n  def apply(id: AccountId, name: AccountName): F[Either[RenameError, Account]] = ???\n}' } },
      { heading: 'Algebras should describe application capabilities', paragraphs: ['An algebra that mirrors every method of a database driver does not create a useful abstraction; it relocates the driver API. Prefer operations meaningful to the application, such as find account or save payment, with typed inputs and results.', 'Keep capabilities cohesive. One enormous trait containing persistence, logging, time, configuration and HTTP calls makes every interpreter and test implement unrelated behaviour. Several tiny one-method traits can be equally noisy, so group operations by ownership and change cycle rather than following a rule mechanically.', 'The algebra is a contract. Returning raw JSON or throwing undocumented exceptions makes the supposedly abstract program depend on details the type does not disclose.'], code: { label: 'Model the application operation, not the database API', language: 'scala 2.13', source: 'trait AccountRepository[F[_]] {\n  def find(id: AccountId): F[Option[Account]]\n  def save(account: Account): F[Unit]\n}\n\n// Avoid leaking a generic document query language through\n// the application merely to make the wrapper reusable.' } },
      { heading: 'Typeclass constraints state how the program composes', paragraphs: ['A workflow needs evidence for the operations it performs on F. Monad supplies pure, map and flatMap for dependent sequencing. A more specific Cats Effect capability may be required for errors, time, concurrency or resource management.', 'Ask for the weakest capability that accurately describes the program, but do not split a readable signature into a long list of constraints for theoretical purity. The chosen constraints are part of the API and should help a reader understand what execution features are available.', 'Business calculations that are already pure do not need F. Keep them as ordinary functions and lift only their results where composition requires it. This leaves more logic testable without an effect runtime.'], code: { label: 'Keep pure decisions outside the effect', language: 'scala 2.13 / Cats', source: 'def rename(account: Account, name: AccountName): Either[RenameError, Account] =\n  if (account.isClosed) Left(RenameError.AccountClosed)\n  else Right(account.copy(name = name))\n\ndef program[F[_]: Monad](\n  repository: AccountRepository[F],\n  id: AccountId,\n  name: AccountName\n): F[Either[RenameError, Account]] =\n  repository.find(id).map {\n    case None          => Left(RenameError.NotFound(id))\n    case Some(account) => rename(account, name)\n  }' } },
      { heading: 'Interpreters own operational behaviour', paragraphs: ['An IO interpreter can use a database-backed repository and describe blocking work with IO.blocking. A test interpreter can use an in-memory state. Both satisfy the same algebra, but they are not assumed to have identical latency, consistency or concurrency behaviour.', 'Resource acquisition, retries, logging and transaction boundaries belong where the required operational context is available. Hiding them inside generic business functions makes the program look more portable than it really is.', 'Tests against an in-memory interpreter prove workflow decisions, not production database semantics. Keep integration tests for the real interpreter, including serialisation, queries, indexes and failure behaviour.'], code: { label: 'One concrete interpreter for IO', language: 'scala / Cats Effect', source: 'final class MongoAccountRepository(\n  collection: AccountCollection\n) extends AccountRepository[IO] {\n  def find(id: AccountId): IO[Option[Account]] =\n    IO.fromFuture(IO(collection.find(id)))\n\n  def save(account: Account): IO[Unit] =\n    IO.fromFuture(IO(collection.save(account))).void\n}' } },
      { heading: 'Testing can use values without mocking every call', paragraphs: ['A small stateful or deterministic interpreter can exercise a workflow across several operations without configuring an interaction script for every method. The test can assert the returned value and final state, which is usually closer to the behaviour that matters.', 'This is not a reason to create an interpreter solely to avoid Mockito. If a concrete service has one dependency and one effect type, a focused stub may be simpler. Tagless-final pays off when several interpreters or reusable effect-polymorphic programs are genuine requirements.', 'Keep laws or shared contract tests for interpreters when consistency matters. Otherwise two implementations can satisfy the same method signatures while disagreeing about missing records, duplicate writes or error handling.'], code: { label: 'A small deterministic test interpreter', language: 'scala 2.13 / Cats', source: 'import cats.Id\n\nfinal class InMemoryAccounts(\n  initial: Map[AccountId, Account]\n) extends AccountRepository[Id] {\n  private var state = initial\n\n  def find(id: AccountId): Option[Account] = state.get(id)\n  def save(account: Account): Unit =\n    state = state.updated(account.id, account)\n\n  def current: Map[AccountId, Account] = state\n}' } },
      { heading: 'Concrete effects are often the honest choice', paragraphs: ['A Play service returning Future may be entirely appropriate when it will never run under another effect and its team understands that model. A Cats Effect application written directly in IO can still be modular, testable and carefully designed.', 'Warning signs include F[_] threaded through every data type, many algebras with one production interpreter, difficult compiler errors and tests that exist mainly to prove wiring. Abstraction has a carrying cost in signatures, imports, inference and onboarding.', 'Adopt tagless-final at a boundary where capability abstraction produces leverage. Keep the rest concrete until a second execution model, reusable module or testing requirement demonstrates the need.'], bullets: ['Does the algebra express an application capability?', 'Is effect polymorphism useful to more than a hypothetical caller?', 'Are pure decisions still plain functions?', 'Are production interpreter semantics integration-tested?', 'Would direct IO or Future make the module easier to own?', 'Can the team diagnose the resulting types in production code?'] },
    ],
  },
  {
    slug: 'over-mocking-scala-tests', title: 'When Scala tests mock too much', category: 'Testing', topic: 'Scala', topics: ['Testing'], readTime: '13 min read',
    summary: 'Why interaction-heavy unit tests become coupled to implementation, how to recognise the damage, and how state, stubs, fakes, contract tests and integration tests restore useful confidence.',
    sections: [
      { heading: 'A passing mock verifies only the conversation you specified', paragraphs: ['Mocks are useful when an interaction itself is the behaviour: an audit event must be emitted once, a payment must not be submitted twice or a notification must follow a successful change. Problems begin when every collaborator is mocked and the test reproduces the implementation call by call.', 'Such a test can pass while repository queries, JSON codecs or dependency wiring fail in the real application. It can also fail after a safe refactor that preserves the public result but changes the order or number of internal calls.', 'The question is not whether Mockito is acceptable. It is whether the assertion provides evidence about a requirement or merely confirms that the production method matches the test author’s script.'], code: { label: 'A test coupled to internal choreography', language: 'scala 2.13 / Mockito', source: 'when(repository.find(id)).thenReturn(Future.successful(Some(account)))\nwhen(repository.save(updated)).thenReturn(Future.successful(()))\n\nservice.rename(id, name).futureValue shouldBe Right(updated)\n\nverify(repository, times(1)).find(id)\nverify(repository, times(1)).save(updated)\nverifyNoMoreInteractions(repository)\n\n// A cache or combined repository operation can preserve behaviour\n// while breaking this test.' } },
      { heading: 'Common symptoms appear in the test design', paragraphs: ['Long setup blocks, deep mock graphs and repeated lenient stubbing indicate that the test boundary may be too wide. Tests that know private call ordering or verify every getter make refactoring costly without adding meaningful protection.', 'Another smell is a mock returning a mock. It often means the production code navigates several collaborators or exposes infrastructure shapes instead of asking for one application capability. Frequent static or singleton mocking points to dependencies that are difficult to substitute at a real boundary.', 'A suite can contain many fast unit tests and still have low confidence if codecs, database behaviour and framework wiring are absent. Count the behaviours and risks covered, not only the number of test cases.'], bullets: ['Most lines arrange mock behaviour rather than domain input', 'Tests break when calls are reordered but output is unchanged', 'verifyNoMoreInteractions appears throughout ordinary service tests', 'Mocks return other mocks or framework objects', 'The same repository behaviour is restubbed in many classes', 'Few tests cross JSON, persistence or application wiring boundaries'] },
      { heading: 'Assert observable state and results first', paragraphs: ['Start from the public outcome: the returned Either, updated entity, persisted record or emitted event. Verify a call only when that call is itself contractually important or when no stable state can expose the behaviour.', 'A simple stub supplies predetermined data without asserting how it was consumed. A fake implements a small working version of a dependency, often in memory. Both can let the service change its internal route while preserving the same externally visible test.', 'Do not build a complete imitation of MongoDB or an HTTP server in memory. Once a fake begins reproducing query semantics, concurrency and failure modes, a focused integration test against the real boundary is more trustworthy.'], code: { label: 'Test the transition through a small fake', language: 'scala 2.13 / ScalaTest', source: 'final class InMemoryAccounts(initial: List[Account]) extends AccountRepository {\n  private var accounts = initial.map(a => a.id -> a).toMap\n\n  def find(id: AccountId): Future[Option[Account]] =\n    Future.successful(accounts.get(id))\n\n  def save(account: Account): Future[Unit] = {\n    accounts = accounts.updated(account.id, account)\n    Future.successful(())\n  }\n\n  def stored(id: AccountId): Option[Account] = accounts.get(id)\n}\n\nservice.rename(id, name).futureValue shouldBe Right(expected)\nrepository.stored(id) shouldBe Some(expected)' } },
      { heading: 'Move infrastructure claims into integration tests', paragraphs: ['A repository unit test with a mocked collection cannot prove that the actual query finds the intended MongoDB document, that codecs preserve fields or that indexes support the access pattern. Those risks belong in an integration test using the real persistence adapter and a controlled database.', 'Controller tests should exercise Play request parsing, validation, routing and response JSON when those are the concern. Service tests can stay focused on typed commands and results. Keeping the boundaries distinct avoids both an enormous end-to-end suite and a unit suite that mocks away every important integration.', 'Contract tests can define shared behaviour for production and test implementations. They are useful when a fake is relied on broadly, but they do not eliminate a smaller number of full-path acceptance tests.'], code: { label: 'Share the behaviour expected of repository implementations', language: 'scala 2.13 / ScalaTest', source: 'trait AccountRepositoryContract { this: AsyncWordSpec with Matchers =>\n  def repository(): AccountRepository\n\n  "an account repository" should {\n    "round-trip an account" in {\n      val repo = repository()\n      repo.save(account).futureValue\n      repo.find(account.id).futureValue shouldBe Some(account)\n    }\n  }\n}\n\n// Run for the real adapter and any fake used by service tests.' } },
      { heading: 'Interaction assertions should protect meaningful boundaries', paragraphs: ['Some requirements are interactions. A failed validation must not write, an idempotency rule must avoid a second external submission, and an audit record may be legally or operationally significant. Verify those calls narrowly.', 'Avoid exact ordering unless order changes correctness. Prefer never for a prohibited side effect and an argument captor when the content sent across the boundary is the result under test. Broad verifyNoMoreInteractions often freezes harmless implementation details.', 'Time, randomness and generated identifiers are easier to test through small explicit interfaces or supplied functions than through static mocking. These dependencies also become visible in the production constructor rather than hidden ambient behaviour.'], code: { label: 'Verify the interaction that carries the requirement', language: 'scala 2.13 / Mockito', source: 'service.rename(closedAccount.id, newName).futureValue shouldBe\n  Left(RenameError.AccountClosed)\n\nverify(repository, never()).save(any[Account])\n\n// The absence of a write matters. The number of reads or internal\n// helper calls does not need to be specified.' } },
      { heading: 'Rebalance the suite around risk', paragraphs: ['Keep pure domain rules under fast value-based unit tests. Use focused service tests with stubs or fakes for branching workflows. Test actual JSON, persistence and framework adapters at their boundaries, then retain a small number of acceptance tests for critical journeys.', 'Replace over-mocked tests gradually. Identify what each test was meant to prove, write the observable assertion at the right boundary and only then remove interaction setup. Deleting all mocks at once can discard the few tests that were protecting an important side effect.', 'A maintainable suite permits internal refactoring while failing for behavioural change. If tests do the opposite, changing the test doubles is not enough; the test boundary and the production design need review together.'], bullets: ['What user, caller or operational behaviour does this test prove?', 'Could the implementation be safely refactored without changing the assertion?', 'Which real integration risk is currently mocked away?', 'Would a stub, fake or explicit dependency be smaller?', 'Is an interaction being asserted because it matters or because it is visible?', 'Does the suite include failure and recovery behaviour at real boundaries?'] },
    ],
  },
  {
    slug: 'unit-and-integration-testing-boundaries', title: 'Unit and integration testing: choose the boundary that proves the behaviour', category: 'Testing strategy', topic: 'Testing', topics: ['Architecture', 'Scala'], readTime: '17 min read',
    summary: 'How unit and integration tests provide different evidence, where mocks and real adapters belong, and how to build a suite that stays fast without testing away production risk.',
    sections: [
      { heading: 'The distinction is the boundary under test', paragraphs: ['A unit test exercises one coherent unit of behaviour with its external dependencies controlled. That unit may be a pure function, a class or a small group of closely related objects. It is not defined by whether the test uses a particular annotation or finishes within a millisecond.', 'An integration test checks that separately implemented parts agree at a real boundary. It may exercise routing and JSON decoding, a repository and database, dependency injection, or an application and an external API substitute. The important point is that the integration behaviour itself is present rather than mocked away.', 'Speed is a consequence of these boundaries, not the complete definition. Unit tests are usually fast and precise; integration tests are usually slower and require more setup. Both should answer a specific question about behaviour.'] },
      { heading: 'Unit tests are strongest around decisions', paragraphs: ['Pure domain rules are excellent unit-test candidates. Inputs and outputs are explicit, failures are reproducible, and the test does not need framework or persistence setup.', 'Test representative equivalence classes and boundaries rather than every possible value. For a withdrawal rule, useful cases might be an exact available balance, one amount above it, a closed account and an invalid amount. The assertion should describe the decision, not helper methods used to reach it.', 'Keep construction honest. If production code can only create PositiveAmount through validation, tests should normally use the same path rather than bypassing the invariant with unsafe fixtures.'], code: { label: 'Protect the rule with values', language: 'scala 2.13 / ScalaTest', source: '"withdraw" should "reject an amount above the available balance" in {\n  val account = openAccount(balance = BigDecimal("100.00"))\n  val amount = PositiveAmount.from(BigDecimal("100.01")).toOption.get\n\n  account.withdraw(amount) shouldBe\n    Left(WithdrawalError.InsufficientFunds(\n      available = BigDecimal("100.00"),\n      requested = BigDecimal("100.01")\n    ))\n}\n\n// No controller, database or mock is needed to prove this rule.' } },
      { heading: 'A service unit test can control collaborators without scripting everything', paragraphs: ['Application services often coordinate repositories, clocks or external operations. A small stub or fake can provide controlled behaviour while the test asserts the service result and observable state.', 'Mocks are appropriate when an interaction is the requirement, such as preventing a write after failed validation or emitting an audit event. Verifying every call and its exact order couples the test to implementation without proving that the real adapter works.', 'A fake repository is not an integration test merely because several classes are involved. It proves service behaviour against the fake’s semantics. Keep separate integration evidence for the production repository.'], code: { label: 'Assert the result and stored state', language: 'scala 2.13 / ScalaTest', source: 'val accounts = new InMemoryAccounts(List(openAccount))\nval service = new RenameAccount(accounts)\n\nservice.rename(openAccount.id, AccountName("New name")).futureValue shouldBe\n  Right(openAccount.copy(name = AccountName("New name")))\n\naccounts.find(openAccount.id).futureValue.map(_.name) shouldBe\n  Some(AccountName("New name"))' } },
      { heading: 'Integration tests belong where assumptions cross', paragraphs: ['Serialization, SQL or MongoDB queries, routing, dependency injection and framework configuration contain behaviour that a mocked unit test cannot verify. Use the real adapter or framework boundary when those details are part of the risk.', 'Keep an integration test focused. A repository test can prove document round-tripping, missing records, uniqueness and query behaviour without starting a browser. A Play route test can prove request parsing, validation and response JSON without exercising an unrelated third-party system.', 'Name the integration being tested. “Creates account” is vague; “accepts the supported JSON shape and returns the persisted account response” describes the evidence and makes failures easier to place.'], code: { label: 'Exercise Play routing and JSON together', language: 'scala 2.13 / Play / ScalaTest', source: '"POST /accounts" should {\n  "reject a blank display name at the HTTP boundary" in {\n    val request = FakeRequest(POST, "/accounts")\n      .withJsonBody(Json.obj("displayName" -> ""))\n\n    val result = route(app, request).value\n\n    status(result) shouldBe BAD_REQUEST\n    contentAsJson(result) shouldBe Json.obj(\n      "code" -> "invalid_display_name"\n    )\n  }\n}' } },
      { heading: 'Use real persistence semantics where they matter', paragraphs: ['A repository mock cannot prove field names, indexes, uniqueness, transaction behaviour or whether a query matches the stored representation. Integration tests should apply the real mapping and talk to a controlled database compatible with production.', 'Start each test from known data and verify externally visible repository behaviour. Avoid assertions against incidental driver calls. If production relies on a unique constraint, exercise the duplicate path and confirm how the adapter translates the failure.', 'A lightweight substitute can be useful only when its semantics match the claims being tested. An in-memory map cannot stand in for MongoDB query behaviour, and a different relational engine may disagree with PostgreSQL on types, constraints or SQL.'], bullets: ['Round-trip representative records', 'Read older supported representations where compatibility matters', 'Exercise missing and duplicate data', 'Apply migrations from a clean database', 'Check the important production-shaped query and index assumptions'] },
      { heading: 'Do not use integration tests to compensate for tangled design', paragraphs: ['If every business rule requires booting the full application, the production boundary may be too broad. Extract pure decisions and typed application operations so they can be tested directly, then retain integration tests for the framework and infrastructure joins.', 'The opposite extreme is equally risky: replacing every dependency with a mock can produce a fast suite that never exercises the paths most likely to fail in production. Test design should follow risk, not a fixed percentage of unit and integration tests.', 'A healthy suite often has many focused unit tests, a smaller set of adapter and boundary integration tests, and a very small number of full journeys. That shape is a consequence of where behaviour lives rather than a quota.'] },
      { heading: 'Test failure channels, not only successful composition', paragraphs: ['Integrations fail in ways pure domain functions do not: timeouts, unavailable databases, malformed payloads, duplicate keys and incompatible stored data. The application boundary should preserve enough meaning to respond appropriately.', 'Do not make an integration suite unreliable by injecting random infrastructure failures into every run. Test deterministic failure cases at the narrowest real boundary and use focused application tests for retry, fallback and error-translation policies.', 'Keep absence separate from operational failure. A database outage should not pass a test merely because the service returns the same empty Option used for a missing record.'], code: { label: 'Keep domain absence and failed infrastructure distinct', language: 'scala 2.13', source: 'repository.find(missingId).futureValue shouldBe None\n\nrecoverToExceptionIf[RepositoryUnavailable] {\n  repositoryWithUnavailableDatabase.find(existingId)\n}\n\n// The service boundary can now translate these paths differently.' } },
      { heading: 'Asynchronous tests must wait for the assertion', paragraphs: ['A test that starts a Future and returns before it completes can pass before the assertion runs. Return the assertion future or use the asynchronous support provided by the test framework. Avoid Thread.sleep: it makes a timing guess and slows the suite even when the operation completes immediately.', 'Control eventual consistency with bounded polling against an observable condition. Give failures a useful timeout message and keep the overall test deadline explicit.', 'Isolation also matters. Shared mutable fixtures make failures depend on test order and parallel execution. Give each test unique identifiers and clean ownership of the data it creates.'], code: { label: 'Return the asynchronous assertion', language: 'scala 2.13 / ScalaTest', source: '"save" should {\n  "make the account available to a later read" in {\n    for {\n      _      <- repository.save(account)\n      stored <- repository.find(account.id)\n    } yield stored shouldBe Some(account)\n  }\n}\n\n// ScalaTest observes the returned Future[Assertion].' } },
      { heading: 'Make local and CI feedback intentional', paragraphs: ['Run fast unit tests on every ordinary change. Run focused integration suites whenever their application or adapter changes, and run the complete required set before merge. Parallelise independent suites only when test data and shared infrastructure support it.', 'A separate integration task can make ownership and runtime visible, but it should not become an optional check nobody runs. Provide one documented command that starts required dependencies, applies migrations and executes the suite from a clean checkout.', 'Track duration and flakiness. A slow test with high-value evidence may be worth keeping; an unreliable test that nobody trusts is not protecting delivery. Diagnose it, narrow it or redesign its data and synchronisation rather than retrying indefinitely.'] },
      { heading: 'Choose the smallest boundary that can prove the claim', paragraphs: ['Start each test with a sentence: what could be wrong, and which real components must run to reveal it? A pricing rule needs values. A JSON compatibility claim needs the codec. A repository query needs the database adapter and compatible database. A wired endpoint may need the application.', 'Do not ask one end-to-end test to diagnose every layer. Keep lower-level tests around important decisions so a full-path failure is supported by faster, more precise evidence.', 'Unit and integration testing are not competing schools. They are different instruments. A maintainable suite uses each where its evidence is strongest and leaves as little important behaviour as possible protected only by an imitation.'], bullets: ['Can a pure input and output prove this behaviour?', 'Which dependency semantics are part of the claim?', 'Has a mock removed the risk the test is meant to cover?', 'Can the failure identify the responsible boundary?', 'Is test data isolated and repeatable?', 'Will the suite still help after an internal refactor?'] },
    ],
  },
  {
    slug: 'end-to-end-browser-testing-that-earns-its-cost', title: 'End-to-end browser testing that earns its cost', category: 'Browser automation', topic: 'Testing', topics: ['Software Delivery'], readTime: '16 min read',
    summary: 'A practical approach to selecting valuable browser journeys, writing stable Selenium tests, controlling data and authentication, and turning failures into useful delivery evidence.',
    sections: [
      { heading: 'A browser test should protect a complete user capability', paragraphs: ['An end-to-end browser test drives the application through a real browser and observes behaviour through the interface a user receives. At its widest boundary it may include the frontend, server, authentication and database. That reach makes it valuable and comparatively expensive.', 'Reserve this boundary for journeys whose integration matters: signing in, creating a key record, completing a critical workflow or seeing a meaningful error. Testing every validation permutation through a browser produces slow, repetitive feedback that belongs closer to the responsible code.', 'Write the capability in user language before automating it. “The create button works” is an implementation detail; “an authorised user can create an account and see it after returning” states durable behaviour.'] },
      { heading: 'Use a small portfolio of journeys rather than a giant scenario', paragraphs: ['One enormous scenario that creates every kind of data and visits every screen becomes difficult to diagnose and impossible to run independently. Split journeys where each has its own setup, action and useful outcome.', 'Do not make every test log in through the interface if authentication is not the behaviour under test. Establish an authenticated state through a supported test setup where appropriate, while keeping a smaller dedicated journey that proves the actual sign-in redirect and callback.', 'A useful browser suite is intentionally incomplete. Unit and integration tests should carry most combinations, edge cases and failure rules. The browser suite checks that critical assembled paths remain available.'], bullets: ['Critical revenue or service journey', 'Authentication and authorisation boundary', 'A high-risk browser/server integration', 'A regression that lower-level tests cannot expose', 'A production route that must remain deployable'] },
      { heading: 'Selectors are part of the test interface', paragraphs: ['CSS classes used for layout and deeply nested selectors change during harmless design work. Prefer semantic roles, labels, names and stable test identifiers when no meaningful accessible selector exists.', 'A stable selector should identify what the element means, not where it happens to sit. data-testid="submit-account" is more durable than div:nth-child(3) button, although a properly labelled button located by its accessible name can serve both users and tests.', 'Do not fill the application with identifiers for every element. Add a test-specific hook at unstable boundaries and keep it independent of styling.'], code: { label: 'Locate elements by meaning or an intentional hook', language: 'java / Selenium', source: 'var email = driver.findElement(By.id("email"));\nemail.sendKeys("engineer@example.test");\n\nvar submit = driver.findElement(\n    By.cssSelector("[data-testid=submit-account]")\n);\nsubmit.click();\n\n// Avoid selectors coupled to layout:\n// .form > div:nth-child(3) > button' } },
      { heading: 'Wait for state, never for an assumed duration', paragraphs: ['Modern interfaces update asynchronously. A fixed sleep can be longer than necessary on a fast run and still fail under a slower CI runner. Wait for the observable condition that makes the next action valid.', 'Selenium explicit waits can wait for visibility, clickability, URL changes or application-specific state. Keep the timeout bounded and include enough context in the assertion to explain what never appeared.', 'Implicit and explicit waits can interact in confusing ways. Choose a consistent waiting approach and avoid hiding long retry periods inside page-object methods. A test should fail near the unmet condition.'], code: { label: 'Wait for the result the user should see', language: 'java / Selenium', source: 'var wait = new WebDriverWait(driver, Duration.ofSeconds(10));\n\nvar confirmation = wait.until(\n    ExpectedConditions.visibilityOfElementLocated(\n        By.cssSelector("[data-testid=account-created]")\n    )\n);\n\nassertEquals("Account created", confirmation.getText());' } },
      { heading: 'Own the test data lifecycle', paragraphs: ['Browser tests become order-dependent when they assume a shared customer, mutate a common account or rely on whichever record another test left behind. Create distinct data for each scenario and make cleanup or expiry part of the environment design.', 'Use supported APIs or setup utilities to establish prerequisite state more quickly than clicking through unrelated screens. The browser should perform the action under test; setup does not need to mimic a user when the setup route is already protected elsewhere.', 'Keep data recognisable as synthetic and never point destructive browser automation at production. Parallel runs need unique identifiers and isolation from each other.'], code: { label: 'Generate traceable, isolated data', language: 'java', source: 'var runId = UUID.randomUUID().toString();\nvar email = "browser-test+" + runId + "@example.test";\n\nvar account = testData.createAccount(email);\n\ntry {\n  accountPage.open(account.id());\n  // Exercise the browser behaviour under test.\n} finally {\n  testData.deleteAccount(account.id());\n}' } },
      { heading: 'Treat authentication as an external boundary', paragraphs: ['Redirects, cookies, callback URLs and session expiry make authentication a valuable integration to test, but they can also dominate the suite. Separate tests of the sign-in journey from ordinary authenticated feature tests.', 'Use dedicated test identities with the minimum permissions required. Never embed credentials in source or print them in failure logs. CI secrets should be scoped to the test environment.', 'Test authorisation through observable behaviour as well as navigation. Hiding a button is not proof that the server rejects the operation; an integration test at the API boundary should carry the detailed permission matrix.'] },
      { heading: 'Page objects should expose behaviour, not Selenium', paragraphs: ['A page object can centralise stable selectors and common interactions. Its methods should describe user intent—renameAccount or displayedBalance—rather than merely wrapping click and findElement.', 'Avoid a single inheritance hierarchy representing the whole site. Large page objects become another application whose internal state is difficult to understand. Compose small page or component objects around durable interface regions.', 'Assertions can remain in the test when they express the scenario clearly. Hiding every assertion inside isSuccessful methods makes it harder to see what the test actually proves.'], code: { label: 'Keep browser mechanics behind a small behaviour-oriented object', language: 'java / Selenium', source: 'final class AccountPage {\n  private final WebDriver driver;\n  private final WebDriverWait wait;\n\n  void renameTo(String name) {\n    var field = driver.findElement(By.id("display-name"));\n    field.clear();\n    field.sendKeys(name);\n    driver.findElement(By.cssSelector("[data-testid=save-account]")).click();\n  }\n\n  String displayedName() {\n    return wait.until(ExpectedConditions.visibilityOfElementLocated(\n        By.cssSelector("[data-testid=account-name]")\n    )).getText();\n  }\n}' } },
      { heading: 'Cucumber helps when the scenario language is genuinely shared', paragraphs: ['Cucumber can express examples in language readable by product and engineering participants. It is useful when those examples are reviewed collaboratively and represent durable behaviour.', 'Feature files become ceremony when steps contain low-level clicks, scenarios duplicate unit-test combinations or nobody outside the automation code reads them. Keep steps domain-oriented and resist building a general-purpose English programming language.', 'A scenario outline is appropriate for a small set of meaningful business examples. Large input matrices usually belong in parameterised unit or API tests.'], code: { label: 'Keep the scenario at user capability level', language: 'gherkin / Cucumber', source: 'Feature: Rename an account\n\n  Scenario: An authorised user renames an open account\n    Given an open account owned by the signed-in user\n    When the user changes the account name to "Household bills"\n    Then "Household bills" is shown as the account name\n    And the new name remains after the page is reloaded' } },
      { heading: 'A failed test needs evidence from every useful layer', paragraphs: ['Capture a screenshot, current URL and browser console output on failure. Preserve server logs and correlation identifiers for the same run so a UI symptom can be followed into the application.', 'Record the browser and application version, environment and test-data identifier. A screenshot of a spinner without request or server evidence rarely explains whether the problem is rendering, an API failure or unavailable data.', 'Retain artifacts for failed CI runs for long enough to investigate, while ensuring screenshots and logs do not expose real personal data or secrets.'] },
      { heading: 'Flakiness is a defect in the delivery signal', paragraphs: ['A flaky test trains the team to rerun failures instead of reading them. Common causes include shared data, fixed sleeps, animation, unstable selectors, environment contention and assertions made before state has settled.', 'Quarantine can prevent one known failure from blocking unrelated work while it is investigated, but it needs an owner and removal condition. Unlimited automatic retries hide the failure rate and multiply suite duration.', 'Track which tests fail and why. Fix the synchronisation or isolation problem, narrow the journey, or move the assertion to a more appropriate boundary. Do not keep a browser test solely because it took effort to write.'] },
      { heading: 'Run the smallest trustworthy browser suite in delivery', paragraphs: ['Run a critical smoke set against each deployable build or preview environment, then run broader browser coverage at the point its feedback can still influence release. Parallel execution helps only when the environment and data are isolated.', 'Browser automation does not replace exploratory testing, accessibility review or lower-level automated tests. It proves selected executable journeys through a particular environment.', 'A good browser suite is judged by the decisions it supports: whether a build can move forward, whether a critical integration still works and whether a failure gives the team enough evidence to respond.'], bullets: ['Does this scenario protect an important complete journey?', 'Could a unit or integration test prove the same rule more precisely?', 'Are selectors independent of visual layout?', 'Does every asynchronous action wait for observable state?', 'Can tests run independently and in parallel?', 'Will a CI failure include useful browser and server evidence?'] },
    ],
  },
  {
    slug: 'folds-in-scala', title: 'Folds in Scala: turning collections into results', category: 'Functional Scala', topic: 'Scala', readTime: '13 min read',
    summary: 'A type-led guide to foldLeft, foldRight, reduce and scan, with accumulator design, evaluation order, performance and practical alternatives.',
    sections: [
      { heading: 'A fold replaces a collection with accumulated state', paragraphs: ['foldLeft begins with an initial value and combines it with each collection element from left to right. The accumulator can be a number, collection, case class or any other type representing the state produced so far.', 'The initial value handles empty input and fixes the accumulator type. That makes fold more general and safer than reduce, which starts from an element of the collection and cannot produce a result for an empty collection without wrapping or throwing.', 'Read a fold by naming the accumulator invariant: total is the sum already visited, or byId contains every account processed so far. If that sentence is unclear, the fold is probably doing too much.'], code: { label: 'State the empty result and transition', language: 'scala 2.13', source: 'val total: BigDecimal = payments.foldLeft(BigDecimal(0)) {\n  case (runningTotal, payment) =>\n    runningTotal + payment.amount\n}\n\nval byId: Map[AccountId, Account] = accounts.foldLeft(Map.empty[AccountId, Account]) {\n  case (result, account) => result.updated(account.id, account)\n}' } },
      { heading: 'foldLeft and foldRight associate differently', paragraphs: ['foldLeft evaluates the accumulator from the beginning: ((zero op a) op b) op c. foldRight associates from the other end: a op (b op (c op zero)). The difference matters for non-associative operations and when constructing ordered results.', 'In strict Scala collections, do not assume foldRight is a general solution for lazy short-circuiting. Its behaviour depends on the collection implementation and function signature. Methods such as exists, find and collectFirst communicate early termination more directly.', 'For List construction, foldRight with :: preserves order, while foldLeft with :: reverses it. A left fold can prepend efficiently and call reverse once when stack behaviour or a more natural forward traversal matters.'], code: { label: 'See how direction changes construction', language: 'scala 2.13', source: 'val values = List(1, 2, 3)\n\nval preserved: List[String] =\n  values.foldRight(List.empty[String]) { (value, result) =>\n    value.toString :: result\n  }\n\nval reversed: List[String] =\n  values.foldLeft(List.empty[String]) { (result, value) =>\n    value.toString :: result\n  }\n\n// preserved == List("1", "2", "3")\n// reversed  == List("3", "2", "1")' } },
      { heading: 'reduce has no independent empty value', paragraphs: ['reduceLeft and reduceRight combine elements using an operation whose input and result are tied to the collection element type. Calling reduce on an empty collection throws UnsupportedOperationException; reduceOption returns None instead.', 'Use reduce when the domain guarantees at least one value and combining like values is the actual operation. Use fold when empty input has a meaningful result or the accumulator has a different type.', 'Operations such as subtraction expose direction immediately. Even associative operations may not be safe to reorder when floating-point rounding or side effects are involved. Keep fold functions pure so traversal order is not also controlling hidden external behaviour.'], code: { label: 'Choose explicit empty semantics', language: 'scala 2.13', source: 'val values = List(10, 3, 2)\n\nvalues.reduceLeft(_ - _)  // (10 - 3) - 2 == 5\nvalues.reduceRight(_ - _) // 10 - (3 - 2) == 9\n\nval maximum: Option[Int] = values.reduceOption(_ max _)\nval total: Int = List.empty[Int].foldLeft(0)(_ + _)' } },
      { heading: 'A named accumulator can rescue a dense fold', paragraphs: ['Tuples are acceptable for two obvious values, but a fold accumulating several counters, collections and flags becomes positional code. A case class names each part of the state and provides a natural place to document the invariant.', 'Avoid repeatedly copying large immutable collections inefficiently. Vector appends are reasonable; List prepends are cheap; repeated List :+ is not. For performance-sensitive construction, use an appropriate builder and return an immutable value at the boundary.', 'Do not perform Future or IO work inside an ordinary fold and assume it has been sequenced. The accumulator type must carry the effect, or a library traversal such as traverse should express the intended ordering and failure semantics.'], code: { label: 'Name multi-part accumulation', language: 'scala 2.13', source: 'final case class Summary(\n  acceptedTotal: BigDecimal,\n  rejectedIds: Vector[PaymentId]\n)\n\nval summary = payments.foldLeft(Summary(BigDecimal(0), Vector.empty)) {\n  case (state, payment) if payment.accepted =>\n    state.copy(acceptedTotal = state.acceptedTotal + payment.amount)\n  case (state, payment) =>\n    state.copy(rejectedIds = state.rejectedIds :+ payment.id)\n}' } },
      { heading: 'scan exposes every intermediate accumulator', paragraphs: ['scanLeft behaves like foldLeft but returns the initial value and every intermediate state. It is useful for running totals, state histories and debugging a transition. The result contains one more element than the input because it includes the seed.', 'A scan can consume substantial memory because it retains every state. Use fold when only the final result matters, and Iterator or streaming abstractions when intermediate states must be processed without materialising them all.', 'Standard operations are usually clearer than clever folds. Prefer map for one-to-one transformation, filter for selection, groupMapReduce for grouped aggregation and find for the first match. Reach for fold when a genuine state transition connects the elements.'], code: { label: 'Keep the history only when it is the result', language: 'scala 2.13', source: 'val balances: List[BigDecimal] =\n  transactions.scanLeft(openingBalance) {\n    case (balance, Credit(amount)) => balance + amount\n    case (balance, Debit(amount))  => balance - amount\n  }\n\n// One seed plus one balance for every transaction.' } },
      { heading: 'Review the algebra, not only the syntax', paragraphs: ['Parallel or regrouped folding is safe only when the combination operation has the required identity and associativity. String concatenation and numeric addition have familiar identities; a process that sends notifications or depends on element order is not a lawful parallel reduction.', 'A fold should make input, state and transition visible. If it contains returns, exceptions used for early exit or mutable state outside the accumulator, use a more specific collection method or an explicit loop.', 'Test empty, singleton and representative multi-element input. When order matters, include values that make an accidental reversal visible rather than only comparing totals.'], bullets: ['What does the accumulator mean after each element?', 'What is the correct result for empty input?', 'Does left-to-right or right-to-left order matter?', 'Is the combination associative, or must it stay sequential?', 'Is a named state clearer than a tuple?', 'Would map, find, exists or groupMapReduce state the intent better?'] },
    ],
  },
  {
    slug: 'pattern-matching-in-scala', title: 'Pattern matching in Scala: more than a switch statement', category: 'Scala', topic: 'Scala', readTime: '14 min read',
    summary: 'How Scala patterns deconstruct algebraic data types, collections and extractors; where exhaustivity helps; and how guards, partial functions and overly broad matches create risk.',
    sections: [
      { heading: 'A pattern tests a shape and binds its parts', paragraphs: ['Scala match evaluates cases from top to bottom. A case can test a constant, type or constructor shape and bind names to values inside that shape. The right-hand side runs for the first matching case.', 'Case-class patterns use the companion extractor generated for the class. Matching is therefore about structure rather than manually calling fields and checking tags. This is especially useful with sealed traits and case classes representing a closed domain.', 'A match should normally produce a value. Assigning the result to an explicit type helps the compiler reveal branches that accidentally return Unit, a broad Any or inconsistent effect types.'], code: { label: 'Deconstruct a closed domain value', language: 'scala 2.13', source: 'sealed trait PaymentResult\nobject PaymentResult {\n  final case class Accepted(reference: String) extends PaymentResult\n  final case class Declined(reason: DeclineReason) extends PaymentResult\n  case object TimedOut extends PaymentResult\n}\n\ndef message(result: PaymentResult): String = result match {\n  case PaymentResult.Accepted(reference) => s"accepted: $reference"\n  case PaymentResult.Declined(reason)     => s"declined: ${reason.code}"\n  case PaymentResult.TimedOut             => "timed out"\n}' } },
      { heading: 'Sealed hierarchies make exhaustivity useful', paragraphs: ['When every direct subtype is known to the compiler, it can warn that a match omits a possible case. This turns adding a new domain state into a list of decisions that may need updating.', 'A wildcard case suppresses that help. Use it when unknown input is genuinely part of the contract, not to silence a warning on a closed model. Matching a broad parent type from another module may remain non-exhaustive because new implementations can appear.', 'Compiler warnings should be visible in CI. An exhaustivity warning that scrolls past in a local build is not protecting a production decision.'], code: { label: 'Let a new case expose missing decisions', language: 'scala 2.13', source: 'sealed trait AccountStatus\nobject AccountStatus {\n  case object Pending extends AccountStatus\n  case object Active extends AccountStatus\n  case object Closed extends AccountStatus\n}\n\ndef canWithdraw(status: AccountStatus): Boolean = status match {\n  case AccountStatus.Pending => false\n  case AccountStatus.Active  => true\n  case AccountStatus.Closed  => false\n}\n\n// Adding Suspended asks this function for an explicit decision.' } },
      { heading: 'Patterns work naturally with Option, Either and collections', paragraphs: ['Matching Some and None is useful when each branch contains different behaviour. For simple transformations, Option.fold, map or getOrElse can be shorter and preserve the optional structure more clearly.', 'List patterns expose empty, head and tail cases. Exact-length patterns are readable for small protocol-like inputs, while recursive head :: tail processing suits structural algorithms. Remember that Seq extractors may inspect the collection to determine its shape.', 'Either matching is clearest at boundaries where Left and Right become different HTTP responses or commands. Within a fail-fast workflow, map, flatMap and a for-comprehension usually avoid repeatedly unpacking the same context.'], code: { label: 'Match where branches make different decisions', language: 'scala 2.13 / Play', source: 'def render(result: Either[FindError, Account]): Result = result match {\n  case Right(account) => Ok(Json.toJson(AccountResponse.from(account)))\n  case Left(FindError.NotFound(id)) =>\n    NotFound(Json.obj("accountId" -> id.value))\n  case Left(FindError.AccessDenied) => Forbidden\n}\n\ndef describe(values: List[String]): String = values match {\n  case Nil          => "empty"\n  case only :: Nil  => s"one value: $only"\n  case head :: tail => s"first: $head, plus ${tail.size}"\n}' } },
      { heading: 'Guards refine a matched shape', paragraphs: ['A guard adds a Boolean condition after a pattern. Cases are still tried in order, so an earlier broad case can make a guarded case unreachable. Keep more specific patterns before general ones.', 'Guards are appropriate for conditions that do not define a new structural type. If the same validation appears throughout the application, a refined domain value or distinct case may make the constraint visible before matching.', 'Avoid guards with side effects or expensive calls. Their evaluation is part of case selection and may be repeated as the match evolves, which makes control flow difficult to see and test.'], code: { label: 'Use guards for local value conditions', language: 'scala 2.13', source: 'def band(balance: BigDecimal): BalanceBand = balance match {\n  case value if value < 0    => BalanceBand.Overdrawn\n  case value if value == 0   => BalanceBand.Empty\n  case value if value < 1000 => BalanceBand.Standard\n  case _                     => BalanceBand.High\n}' } },
      { heading: 'Type patterns cannot recover erased type arguments', paragraphs: ['On the JVM, generic type arguments are normally erased. A pattern such as case values: List[String] cannot reliably distinguish List[String] from List[Int] at runtime, and the compiler warns that the type test is unchecked.', 'Match on a non-erased outer type, preserve evidence such as a ClassTag when the use case genuinely supports it, or redesign the boundary so the variant is represented by a sealed type. Inspecting the first element is not a safe substitute because the collection may be empty or heterogeneous through unsafe input.', 'Type patterns are also a design signal. Repeatedly matching concrete implementations can mean a missing method on a sealed domain model or an algebra that has become too broad.'], code: { label: 'Represent variants explicitly instead of matching erased types', language: 'scala 2.13', source: 'sealed trait FieldValues\nobject FieldValues {\n  final case class Text(values: List[String]) extends FieldValues\n  final case class Numbers(values: List[Int]) extends FieldValues\n}\n\ndef count(values: FieldValues): Int = values match {\n  case FieldValues.Text(items)    => items.size\n  case FieldValues.Numbers(items) => items.size\n}\n\n// Avoid: case strings: List[String] => ...' } },
      { heading: 'Extractors define what a pattern exposes', paragraphs: ['An object with unapply can provide a pattern without exposing a type’s representation. Extractors are useful for validated identifiers and stable views over a value, but complex extractors can hide parsing, allocation or failure behind innocent-looking syntax.', 'Keep unapply pure and inexpensive. If validation needs a detailed error, a constructor returning Either is more informative than an extractor that can only decline the match with None.', 'PartialFunction uses the same pattern vocabulary for behaviour defined only on some inputs. Methods such as collect and collectFirst apply partial functions safely; calling a partial function directly on an unsupported input throws MatchError unless isDefinedAt is checked.'], code: { label: 'Use collect for a partial transformation', language: 'scala 2.13', source: 'val closedIds: List[AccountId] = events.collect {\n  case AccountClosed(id, _) => id\n}\n\nval renderKnown: PartialFunction[DomainEvent, String] = {\n  case AccountOpened(id, _) => s"opened ${id.value}"\n  case AccountClosed(id, _) => s"closed ${id.value}"\n}\n\n// collect checks where the partial function is defined.' } },
      { heading: 'Keep matches close to the decision they own', paragraphs: ['Pattern matching is strongest when one component owns a complete decision over a closed model: a domain transition, JSON presenter or error-to-HTTP mapping. Scattered matches on the same hierarchy can make every new case require edits across unrelated modules.', 'Moving all behaviour onto methods is not automatically better. A presenter often should own how every error becomes an HTTP response, while the error types should remain independent of Play. Choose the side whose responsibility the decision represents.', 'Review for exhaustivity, order, wildcard use and erased type tests. Then ask whether the match is exposing a meaningful domain choice or compensating for a value whose type no longer describes its possible states.'], bullets: ['Is the matched hierarchy closed and exhaustively handled?', 'Does a wildcard hide a future domain decision?', 'Are specific cases placed before broader patterns?', 'Would map, fold or collect express the operation more directly?', 'Is a guard repeating validation that belongs in a domain type?', 'Does the component performing the match own the decision?'] },
    ],
  },
  {
    slug: 'futures-in-scala-application-code-and-tests', title: 'Using Futures in Scala application code and tests', category: 'Scala concurrency', topic: 'Scala', readTime: '15 min read',
    summary: 'How Scala Future starts, composes and fails; how ExecutionContext choices affect Play services; and how to test asynchronous behaviour without sleeps or misleading mocks.',
    sections: [
      { heading: 'A Future represents one running or completed result', paragraphs: ['Scala Future[A] represents a value that may become available later or fail with a Throwable. Creating a Future with Future { ... } submits its body to an ExecutionContext immediately. It is eager, unlike an effect value such as Cats Effect IO that describes work for later interpretation.', 'A Future memoises its completion. Several callbacks attached to the same instance observe the same success or failure; they do not rerun its body. Calling a method that creates a new Future several times is different because each call creates and schedules new work.', 'Keep construction visible when timing matters. A val holding an existing Future and a def returning a fresh Future have similar types at the call site but different execution behaviour.'], code: { label: 'One Future instance has one completion', language: 'scala 2.13', source: 'def fresh(): Future[UUID] = Future(UUID.randomUUID())\n\nval shared: Future[UUID] = fresh()\nval first  = shared.map(identity)\nval second = shared.map(identity) // observes the same completion\n\nval another: Future[UUID] = fresh() // schedules new work' } },
      { heading: 'map and flatMap sequence successful completion', paragraphs: ['map transforms a successful result and propagates an existing failure. flatMap is required when the next function returns another Future. If a callback throws, the Future returned by map or flatMap completes as a failure.', 'A for-comprehension translates to flatMap and map. Creating every independent Future before the comprehension lets the operations start independently; creating the second inside a generator makes it wait for the first.', 'Parallelism is not automatically faster or safer. Start work independently only when there is no data dependency, the downstream system can accept the concurrency and failure of one operation does not require preventing the other from starting.'], code: { label: 'Construction position controls when work can start', language: 'scala 2.13', source: 'val accountF: Future[Account] = accounts.find(accountId)\nval scoreF: Future[Score] = scores.find(accountId)\n\nval assessmentF: Future[Assessment] = for {\n  account <- accountF\n  score   <- scoreF\n} yield Assessment(account, score)\n\n// Dependent: the second call starts only after account arrives.\nval historyF = accounts.find(accountId).flatMap { account =>\n  history.forAccount(account.id)\n}' } },
      { heading: 'The ExecutionContext is an operational dependency', paragraphs: ['Every transformation needs an ExecutionContext on which its callback can run. In a Play application, the default context is intended for asynchronous, non-blocking application work. Blocking database, file or network calls can occupy those threads and reduce request throughput.', 'Moving a blocking call into Future does not make the call non-blocking; it moves the wait to a thread. Isolate unavoidable blocking work on an appropriately configured execution context and keep the ownership of that context clear in application wiring.', 'Do not create a new thread pool per request or service instance. Pool size, queueing and shutdown are application concerns. Monitor saturation and latency rather than assuming the presence of Future means concurrency is healthy.'], code: { label: 'Isolate an unavoidable blocking adapter', language: 'scala 2.13 / Play', source: 'import scala.concurrent.{blocking, ExecutionContext, Future}\n\nfinal class LegacyAccountRepository(\n  client: BlockingAccountClient,\n  blockingEc: ExecutionContext\n) {\n  def find(id: AccountId): Future[Option[Account]] =\n    Future {\n      blocking(client.find(id))\n    }(blockingEc)\n}\n\n// The controller and service need not know how the adapter blocks.' } },
      { heading: 'Keep expected outcomes distinct from failed Futures', paragraphs: ['A failed Future means no normal result was produced: an unexpected exception escaped, a database was unavailable or another operational failure occurred. A value such as Future[Either[RenameError, Account]] can distinguish that channel from a known application rejection.', 'recover transforms selected failures into successful values; recoverWith starts another asynchronous recovery. Catch only failures the current boundary can interpret. Recovering every Throwable into an empty result can turn an outage or defect into false business data.', 'Future has no general cancellation or resource-lifetime model. A request timing out does not necessarily stop the underlying work. APIs that acquire resources must own their release independently of whether a caller continues waiting.'], code: { label: 'Recover only the failure this boundary owns', language: 'scala 2.13', source: 'def find(id: AccountId): Future[Either[FindError, Account]] =\n  repository.find(id).map {\n    case Some(account) => Right(account)\n    case None          => Left(FindError.NotFound(id))\n  }.recover {\n    case error: InvalidStoredAccount =>\n      Left(FindError.InvalidData(error.field))\n  }\n\n// Connection failures still fail the Future for the outer boundary to handle.' } },
      { heading: 'Test completion instead of waiting for time to pass', paragraphs: ['Never use Thread.sleep to give a Future time to finish. It makes tests slow and timing-dependent. ScalaTest provides ScalaFutures and asynchronous suite styles that complete the test from the Future itself.', 'futureValue is convenient for focused tests when patience settings are sensible. When testing a failure, inspect failed.futureValue or recoverToExceptionIf rather than wrapping Await.result in an intercept block. Await is best kept at process boundaries and out of ordinary production composition.', 'Use Future.successful and Future.failed for dependencies whose answer is already known. Constructing Future { value } in a stub schedules work that the test does not need and makes execution depend unnecessarily on a thread pool.'], code: { label: 'Assert asynchronous success and failure directly', language: 'scala 2.13 / ScalaTest', source: 'class AccountServiceSpec\n    extends AsyncWordSpec\n    with Matchers {\n\n  "rename" should {\n    "return the updated account" in {\n      val repository = new StubRepository(Some(account))\n\n      service(repository).rename(account.id, newName).map { result =>\n        result shouldBe Right(expected)\n      }\n    }\n\n    "retain repository failure" in {\n      val failure = new RuntimeException("database unavailable")\n      val repository = StubRepository.failed(failure)\n\n      recoverToExceptionIf[RuntimeException] {\n        service(repository).rename(account.id, newName)\n      }.map(_ shouldBe failure)\n    }\n  }\n}' } },
      { heading: 'Control promises only when the timing is under test', paragraphs: ['Promise[A] gives a test explicit control over when a Future completes. It is useful for proving that a second operation does not begin before a prerequisite, or that independently created work is not accidentally serialised.', 'A Promise-heavy test can be as coupled as a mock-heavy one. Use it for a concurrency property visible in the service contract, not to reproduce every callback. Complete every Promise or ensure the test can terminate on failure.', 'ExecutionContext.parasitic can execute short callbacks on the completing thread, but using it broadly in tests can hide scheduling assumptions that differ in production. Prefer the same execution model as the application unless the test is deliberately isolated to pure, immediate transformations.'], code: { label: 'Control one meaningful completion boundary', language: 'scala 2.13 / ScalaTest', source: 'val accountResult = Promise[Account]()\nval repository = new StubRepository(accountResult.future)\n\nval result = service(repository).loadAndScore(accountId)\nscoring.requests shouldBe empty\n\naccountResult.success(account)\n\nwhenReady(result) { assessment =>\n  assessment.account shouldBe account\n}\nscoring.requests should contain(account.id)' } },
      { heading: 'Test the adapters Future cannot abstract away', paragraphs: ['A unit test can prove how a service composes successful and failed Futures. It cannot prove that the real database client is genuinely asynchronous, that the configured pool is large enough or that a Play action serialises failures correctly.', 'Add integration tests for the real repository and HTTP boundary, and observe thread pools, latency and failures under a representative workload. Production support needs logs with useful context at the boundary that finally handles a failed Future—not the same exception logged in every map and flatMap.', 'Review Future code by tracing construction, dependency and failure. Ask when the work starts, which execution context runs it, whether operations are independent, what a failed Future means and how the test knows completion occurred.'], bullets: ['Is blocking work isolated from Play’s default execution context?', 'Are independent Futures created before they are combined?', 'Do typed application rejections remain values rather than failed Futures?', 'Does recovery preserve unexpected operational failures?', 'Do tests wait on completion rather than elapsed time?', 'Are real adapters and failure paths covered beyond mocked unit tests?'] },
    ],
  },
  {
    slug: 'scala-syntactic-sugar', title: 'Scala syntactic sugar: what the compiler sees', category: 'Scala language', topic: 'Scala', readTime: '14 min read',
    summary: 'A practical guide to method-call shorthand, apply and update, operators, for-comprehensions, placeholders, varargs, string interpolation and the semantics hidden by concise Scala syntax.',
    sections: [
      { heading: 'Syntactic sugar is a shorter route to ordinary semantics', paragraphs: ['Scala provides concise forms that the compiler translates into method calls or more explicit expressions. Understanding that translation makes unfamiliar code easier to read and explains compiler errors that otherwise seem disconnected from the source.', 'Sugar is not automatically clearer. It works best when the expanded meaning is familiar and unsurprising. A custom operator, implicit conversion or expensive apply method can make a short expression conceal more than it communicates.', 'When a line does not type-check, expand one layer mentally: identify the receiver, method, arguments and expected result type. Most Scala syntax still follows those ordinary pieces.'], code: { label: 'Several expressions are method calls', language: 'scala 2.13', source: 'account.isActive       // selects a val or parameterless def\naccount rename newName // account.rename(newName), when used infix\nleft + right           // left.+(right)\n!account.isClosed      // !(account.isClosed)' } },
      { heading: 'apply and update power familiar-looking access', paragraphs: ['Calling an object as if it were a function invokes apply. Case-class companions provide apply for construction, function values implement apply, and collections use it for indexed or keyed access.', 'Assignment-shaped syntax invokes update when the left side is an application. values(2) = "new" becomes values.update(2, "new"). This is most common with mutable collections and does not make an immutable Map mutable.', 'Because apply can contain arbitrary code, parentheses do not guarantee cheap lookup or pure construction. APIs should keep apply unsurprising and use a named method when work, failure or I/O deserves attention.'], code: { label: 'Expand apply and update', language: 'scala 2.13', source: 'final case class AccountId(value: String)\n\nAccountId("a-17")          // AccountId.apply("a-17")\naccounts(id)               // accounts.apply(id); throws if absent\ntransformation(account)    // transformation.apply(account)\n\nval names = scala.collection.mutable.ArrayBuffer("Ada")\nnames(0) = "Grace"         // names.update(0, "Grace")' } },
      { heading: 'Operator syntax follows method and associativity rules', paragraphs: ['Most operators are method names. left + right calls left.+(right), so overloading and static receiver type determine the behaviour. Symbolic methods ending in a colon are right-associative: value :: list is translated as list.::(value).', 'Precedence is derived from the first character of the operator rather than a custom declaration. Mixing several symbolic operators can therefore be technically correct but difficult to review without knowing the precedence table.', 'Infix syntax also works for alphabetic one-argument methods in Scala 2.13. Dot notation is often clearer for application APIs, while familiar domain-neutral operators such as :: retain their conventional readability.'], code: { label: 'The colon changes the receiver', language: 'scala 2.13', source: 'val values = 1 :: 2 :: Nil\n\n// Right associative:\nval equivalent = Nil.::(2).::(1)\n\nval total = BigDecimal(10).+(BigDecimal(5))\nval clearer = BigDecimal(10) + BigDecimal(5)' } },
      { heading: 'For-comprehensions expand to map, flatMap and withFilter', paragraphs: ['Generators before the final yield normally become flatMap; the final transformation becomes map. Guards use withFilter. The concrete type supplies those methods, which is why a for-comprehension over List means combinations while one over Future means dependent asynchronous composition.', 'Value definitions inside a comprehension are translated through additional mappings and tuple-like intermediate values. A pattern in a generator may also introduce filtering. Dense comprehensions can therefore allocate or filter more than their surface suggests.', 'When the compiler reports a type mismatch inside a comprehension, expand it from the first generator. One callback often returns Option while the surrounding expression expects Either, Future or another context.'], code: { label: 'Read the methods beneath the comprehension', language: 'scala 2.13', source: 'val result: Either[OrderError, Order] = for {\n  account <- loadAccount(id)\n  if account.isActive\n  order <- createOrder(account, amount)\n} yield order\n\nval expanded = loadAccount(id).withFilter { account =>\n  account.isActive\n}.flatMap { account =>\n  createOrder(account, amount).map(order => order)\n}' } },
      { heading: 'Underscores rely on an expected function shape', paragraphs: ['Placeholder syntax such as values.map(_.name) asks the compiler to create a function whose missing parameter type comes from context. _ + _ creates two parameters in order. It is concise while the expected types are obvious.', 'Nested underscores, overloaded methods and repeated use of the same value can make inference ambiguous or change the intended number of parameters. Replace the shorthand with a named lambda when a compiler error or business condition needs explanation.', 'Partial application is related but distinct. In Scala 2.13, eta expansion can turn a method into a function where a function type is expected; an explicit underscore sometimes appears in older or inference-sensitive code.'], code: { label: 'Expand placeholders when intent becomes unclear', language: 'scala 2.13', source: 'accounts.map(_.name)\n// accounts.map(account => account.name)\n\nvalues.reduce(_ + _)\n// values.reduce((left, right) => left + right)\n\naccounts.filter(account =>\n  account.isActive && account.balance > minimum\n)' } },
      { heading: 'Varargs, named arguments and defaults affect call sites', paragraphs: ['A repeated parameter accepts zero or more arguments and is represented as a sequence inside the method. In Scala 2.13, an existing sequence is expanded at a call site with values: _*. Scala 3 uses values*.', 'Named arguments improve readability and allow parameters to be supplied out of declaration order. Default arguments are inserted by compiler-generated default getter methods. Changing parameter names can therefore break source callers using named arguments even when binary shape appears otherwise similar.', 'Defaults are resolved at the call site, not chosen dynamically by an override. Avoid long methods whose many Boolean defaults turn invocation into a configuration language; a parameter case class or explicit methods usually produce a clearer contract.'], code: { label: 'Call a repeated parameter explicitly', language: 'scala 2.13', source: 'def audit(category: String, messages: String*): AuditEntry = ???\n\nval messages = Seq("opened", "verified")\naudit(category = "account", messages: _*)\n\nfinal case class RetryPolicy(\n  attempts: Int = 3,\n  initialDelayMillis: Long = 100\n)' } },
      { heading: 'String interpolation is an extensible method call', paragraphs: ['s, f and raw interpolation are implemented through methods on StringContext. s inserts expressions and processes common escapes; f adds format checking; raw changes escape handling. Expressions beyond a simple identifier need braces.', 'Custom interpolators are possible through implicit or extension syntax, but they should earn their unfamiliarity through validation or a strongly typed result. They should not hide network access or expensive parsing.', 'Interpolation is not output escaping. Putting a value into an HTML, JSON, SQL or shell string does not make it safe for that context. Use the boundary library’s encoder or parameter mechanism.'], code: { label: 'Interpolation still needs boundary-safe encoding', language: 'scala 2.13', source: 'val message = s"account ${account.id.value} has balance ${account.balance}"\nval percentage = f"${ratio * 100}%.2f%%"\n\n// Prefer Play JSON construction to interpolating JSON text.\nval body = Json.obj(\n  "accountId" -> account.id.value,\n  "balance" -> account.balance\n)' } },
      { heading: 'Concise syntax should remain locally explainable', paragraphs: ['Other Scala conveniences include tuple construction, case-class copy, automatic companion methods, by-name parameters and pattern extractors. Some are pure syntax; others also introduce evaluation or generated methods, so understanding the specific translation matters more than labelling everything sugar.', 'During review, expand syntax that hides receiver choice, evaluation timing or failure. Keep familiar collection and for-comprehension idioms concise, but name complicated lambdas and avoid custom punctuation that only one module understands.', 'Good Scala can be compact without being cryptic. The target is code whose short form and expanded meaning tell the same story to the next engineer.'], bullets: ['Which method and receiver does this syntax select?', 'Does the short form hide failure, mutation or I/O?', 'Would an explicit lambda improve a complex predicate?', 'Does a for-comprehension keep one consistent context?', 'Could apply be mistaken for cheap construction or lookup?', 'Is boundary data encoded by the proper library rather than interpolation?'] },
    ],
  },
  {
    slug: 'java-records-sealed-types-domain-models', title: 'Java records and sealed types for honest domain models', category: 'Java', topic: 'Java', readTime: '13 min read',
    summary: 'How records, sealed interfaces, Optional and exhaustive decisions can replace nullable fields, string states and inheritance-heavy Java models.',
    sections: [
      { heading: 'Model the states the application actually permits', paragraphs: ['Java domain models often begin as mutable classes with nullable fields and a status string. That shape accepts combinations the business never intended: a declined payment with a settlement reference, or an active account with a closure reason.', 'Records are concise immutable data carriers. Sealed interfaces define a closed family of alternatives. Together they provide product types and sum types: values containing several fields, and values that must be exactly one of several cases.'], code: { label: 'Give each result only the data it can contain', language: 'java', source: 'public sealed interface PaymentResult\n    permits Accepted, Declined, TimedOut {}\n\npublic record Accepted(\n    PaymentId id,\n    SettlementReference reference\n) implements PaymentResult {}\n\npublic record Declined(\n    PaymentId id,\n    DeclineReason reason\n) implements PaymentResult {}\n\npublic record TimedOut(PaymentId id) implements PaymentResult {}' } },
      { heading: 'Records are values, not automatic domain objects', paragraphs: ['A record supplies final components, accessors, a canonical constructor and value-based equals, hashCode and toString. It does not validate meaning automatically. A public canonical constructor can still accept an empty identifier or negative amount.', 'Use a compact constructor for local invariants or a named factory when construction can fail with useful detail. Keep validation that depends on repositories or external services outside the record; construction should not conceal I/O.'], code: { label: 'Protect a local invariant at construction', language: 'java', source: 'public record AccountName(String value) {\n  public AccountName {\n    value = value == null ? "" : value.trim();\n    if (value.isEmpty()) {\n      throw new IllegalArgumentException("Account name is required");\n    }\n  }\n}\n\npublic record Money(BigDecimal amount, Currency currency) {\n  public Money {\n    Objects.requireNonNull(amount);\n    Objects.requireNonNull(currency);\n  }\n}' } },
      { heading: 'Closed alternatives make decisions reviewable', paragraphs: ['A sealed hierarchy allows only declared implementations. A switch over that hierarchy can make every case visible, so adding a new result prompts the compiler to identify decisions that need revisiting.', 'Avoid a default branch on a hierarchy the application owns. It suppresses the benefit of exhaustivity and can silently assign future cases the wrong behaviour. A default remains appropriate when the input is deliberately open-ended.'], code: { label: 'Translate every known result explicitly', language: 'java', source: 'public PaymentResponse render(PaymentResult result) {\n  return switch (result) {\n    case Accepted accepted ->\n        PaymentResponse.accepted(accepted.reference());\n    case Declined declined ->\n        PaymentResponse.declined(declined.reason());\n    case TimedOut ignored ->\n        PaymentResponse.retryLater();\n  };\n}' } },
      { heading: 'Optional is best at return boundaries', paragraphs: ['Optional<T> communicates that a method may return no value and gives callers operations such as map, flatMap, orElse and orElseThrow. It is usually clearer than returning null from a repository lookup.', 'Using Optional for every record component, collection element or method parameter can spread wrapping through the model. A command should normally state whether a field is required; use separate request shapes or overloads when absence has a particular meaning. Never store null inside Optional.'], code: { label: 'Turn absence into a decision at the service boundary', language: 'java', source: 'public Either<FindAccountError, Account> find(AccountId id) {\n  return repository.find(id)\n      .<Either<FindAccountError, Account>>map(Either::right)\n      .orElseGet(() -> Either.left(\n          new FindAccountError.NotFound(id)\n      ));\n}\n\n// If no Either type is used, a service-specific result hierarchy\n// can express the same decision.' } },
      { heading: 'Keep transport and persistence contracts deliberate', paragraphs: ['Serialising a record directly is convenient, but its component names and structure can become an external API. Renaming a domain component may then change JSON, database mappings and internal behaviour in one edit.', 'Reuse a record across layers when its contract and lifecycle genuinely match. Introduce request, response or persistence records when compatibility requirements differ. Mapping code is useful when it identifies a real boundary rather than satisfying a folder structure.'], code: { label: 'Make the HTTP representation explicit', language: 'java', source: 'public record AccountResponse(\n    String id,\n    String displayName,\n    BigDecimal balance\n) {\n  public static AccountResponse from(Account account) {\n    return new AccountResponse(\n        account.id().value(),\n        account.name().value(),\n        account.balance().amount()\n    );\n  }\n}' } },
      { heading: 'Prefer the smallest model that rules out real mistakes', paragraphs: ['Records and sealed types are useful when they expose a business distinction to the compiler. They do not require every string to become a wrapper or every Boolean to become a hierarchy.', 'Review the invalid states the current model permits, the callers that construct it and the boundaries that serialise it. Add types where they remove ambiguity or make an important decision exhaustive; leave ordinary data ordinary where the extra ceremony has no leverage.'], bullets: ['Can a value be constructed in a state the domain rejects?', 'Does a string or Boolean conceal several meaningful states?', 'Will a default switch branch hide a newly added case?', 'Is Optional expressing absence or spreading uncertainty?', 'Would changing a record component unintentionally change JSON or persistence?', 'Does each wrapper enforce or communicate something useful?'] },
    ],
  },
  {
    slug: 'testing-spring-boot-service-boundaries', title: 'Testing Spring Boot services at the right boundaries', category: 'Java testing', topic: 'Java', topics: ['Testing'], readTime: '14 min read',
    summary: 'A practical testing structure for Java and Spring Boot: pure unit tests, focused service tests, web slices, repository integration and fewer mocks that merely replay the implementation.',
    sections: [
      { heading: 'Different tests should answer different questions', paragraphs: ['A service test, controller test and repository test protect different risks. Treating all three as unit tests with mocked collaborators produces fast feedback but little evidence that validation, JSON, SQL or Spring wiring works together.', 'Begin with the behaviour at risk. Pure rules need ordinary JUnit tests. Service orchestration may need a stub repository. HTTP mapping belongs in a web test, while query and transaction behaviour require the real persistence adapter.'], code: { label: 'Keep a domain rule outside the Spring container', language: 'java', source: 'class AccountTest {\n  @Test\n  void closedAccountsCannotBeRenamed() {\n    var result = closedAccount.rename(new AccountName("Ada"));\n\n    assertEquals(\n        Either.left(RenameError.ACCOUNT_CLOSED),\n        result\n    );\n  }\n}\n\n// No application context is needed for a pure decision.' } },
      { heading: 'Service tests should assert outcomes before choreography', paragraphs: ['Mock a collaborator when the interaction is itself important, such as ensuring a rejected command never writes. Do not verify every read and helper call merely because Mockito makes them visible.', 'A small stub or in-memory fake can let a test assert the returned result and stored state. It survives refactoring from two repository calls to one while still failing if the public behaviour changes.'], code: { label: 'Verify only the prohibited side effect', language: 'java / Mockito', source: '@Test\nvoid doesNotSaveWhenTheAccountIsClosed() {\n  when(repository.find(id)).thenReturn(Optional.of(closedAccount));\n\n  var result = service.rename(id, newName);\n\n  assertEquals(Either.left(RenameError.ACCOUNT_CLOSED), result);\n  verify(repository, never()).save(any(Account.class));\n}\n\n// Exact read counts and helper ordering are not part of this rule.' } },
      { heading: 'Test the web contract through Spring MVC', paragraphs: ['Controller tests should prove request decoding, bean validation, status codes, headers and response JSON. Calling the controller method directly skips much of the machinery whose behaviour the endpoint promises.', 'A focused MVC slice can keep unrelated infrastructure out while retaining HTTP mapping. Mock the application service at this boundary because the test is concerned with translation, not service implementation.'], code: { label: 'Protect status and response shape', language: 'java / Spring Boot', source: '@WebMvcTest(AccountController.class)\nclass AccountControllerTest {\n  @Autowired MockMvc mvc;\n  @MockBean AccountService service;\n\n  @Test\n  void missingAccountReturns404() throws Exception {\n    when(service.find(new AccountId("a-17")))\n        .thenReturn(new FindResult.NotFound());\n\n    mvc.perform(get("/accounts/a-17"))\n        .andExpect(status().isNotFound());\n  }\n}' } },
      { heading: 'Repository behaviour needs a real database boundary', paragraphs: ['A mocked JdbcTemplate or repository interface cannot prove that SQL joins, constraints, mappings and migrations agree. Repository integration tests should execute representative queries against a controlled database with realistic schema.', 'Test transactions where ownership matters. A method-level unit test cannot prove that a multi-write operation rolls back, nor that lazy access remains valid outside the transaction. Keep the integration suite focused enough to remain diagnosable.'], code: { label: 'Exercise the persistence contract', language: 'java / JUnit', source: '@Test\nvoid roundTripsAnAccount() {\n  repository.save(account);\n\n  var loaded = repository.find(account.id());\n\n  assertEquals(Optional.of(account), loaded);\n}\n\n@Test\nvoid rejectsDuplicateExternalReference() {\n  repository.save(first);\n  assertThrows(DuplicateKeyException.class,\n      () -> repository.save(duplicate));\n}' } },
      { heading: 'Use the full application context selectively', paragraphs: ['A small number of SpringBootTest cases can prove that configuration and principal journeys assemble correctly. Loading the full context for every field validation or calculation increases suite time without increasing evidence.', 'Separate failures by boundary. When a full-context test fails, a narrower controller or repository test should usually locate the cause. If every test uses the entire application, failures become slower and harder to interpret.'], bullets: ['Pure domain rule: ordinary JUnit test', 'Service workflow: stub, fake or narrow mock', 'HTTP contract: MVC boundary test', 'SQL and mappings: repository integration test', 'Configuration and critical journey: selective full-context test', 'Production confidence: deployment checks and observable behaviour'] },
      { heading: 'A useful suite follows risk rather than a pyramid quota', paragraphs: ['The familiar test pyramid is guidance about feedback and cost, not a required percentage. A database-heavy service may need more integration evidence; a calculation library may be mostly pure unit tests.', 'Measure whether the suite catches meaningful regressions, runs reliably and tells an engineer what failed. Coverage can expose untouched code, but maximising the number does not prove assertions, boundaries or failure paths are useful.'] },
    ],
  },
  {
    slug: 'nuxt-rendering-ssr-ssg-and-client-side', title: 'Nuxt rendering: choosing SSR, static generation and client-side work', category: 'Nuxt', topic: 'TypeScript', readTime: '14 min read',
    summary: 'How Nuxt rendering choices affect HTML, hydration, data freshness, browser APIs and deployment—and why one application can use more than one strategy.',
    sections: [
      { heading: 'Rendering is a route-level product decision', paragraphs: ['Server-side rendering produces HTML for a request before the browser hydrates it. Static generation produces HTML during a build. Client-side rendering waits for JavaScript in the browser to construct the view. Each moves work and freshness to a different point in the system.', 'Public content often benefits from ready HTML and predictable metadata. An authenticated dashboard may rely more heavily on client-side state. Nuxt can combine strategies, so the application does not need one ideological rendering mode for every route.'], code: { label: 'Express route behaviour deliberately', language: 'typescript / Nuxt', source: 'export default defineNuxtConfig({\n  routeRules: {\n    "/": { prerender: true },\n    "/insights/**": { prerender: true },\n    "/account/**": { ssr: true },\n    "/api/**": { cors: true },\n  },\n})' } },
      { heading: 'Hydration requires the first render to agree', paragraphs: ['Hydration attaches Vue behaviour to server-rendered HTML. If the browser produces different initial markup, Vue must reconcile a mismatch. Current time, random values, browser-only storage and viewport-dependent branches are common causes.', 'Move browser-only reads into onMounted or a client-only component. Pass stable server data through the Nuxt payload rather than fetching it independently on both sides with different timing.'], code: { label: 'Read browser state after hydration', language: 'typescript / Vue', source: 'const preferredTheme = ref("system")\n\nonMounted(() => {\n  preferredTheme.value = localStorage.getItem("theme") ?? "system"\n})\n\n// The server and first client render both begin with "system".' } },
      { heading: 'useFetch connects server rendering and hydration', paragraphs: ['Nuxt useFetch wraps asynchronous data in SSR-aware state. Server rendering can wait for the request and serialize the result into the payload so hydration does not need to repeat the same fetch.', 'Use its data, status and error refs explicitly. Lazy or non-awaited fetching can keep navigation responsive, but the page then owns a loading state. Choose blocking or deferred navigation according to what must be present for the route to be useful.'], code: { label: 'Make loading and failure visible', language: 'typescript / Nuxt', source: 'const route = useRoute()\nconst { data: article, status, error } = await useFetch(\n  () => `/api/articles/${route.params.slug}`,\n  { key: `article-${route.params.slug}` },\n)\n\nif (error.value?.statusCode === 404) {\n  throw createError({ statusCode: 404, statusMessage: "Article not found" })\n}' } },
      { heading: 'Static output changes the meaning of freshness', paragraphs: ['A generated page contains data available during the build. Publishing a database change does not update that HTML until another deployment or regeneration strategy runs.', 'This is excellent for versioned articles and marketing pages. It is a poor default for account balances or permission-sensitive data. Document which event makes generated content fresh again and avoid embedding secrets or user-specific responses at build time.'] },
      { heading: 'Deployment runtime completes the architecture', paragraphs: ['A Nuxt build can include server-rendered routes and Nitro handlers; a fully generated build contains static output. The target platform determines function duration, filesystem behaviour, regions and environment configuration.', 'Test the actual deployment shape. Local development can conceal cold starts, missing variables, cross-region database latency and assumptions about a writable filesystem. Preview deployments are useful only when their data and authentication configuration are intentionally separated from production.'], links: [{ label: 'Nuxt useFetch documentation', href: 'https://nuxt.com/docs/4.x/api/composables/use-fetch' }, { label: 'Vercel Nuxt deployment documentation', href: 'https://vercel.com/docs/frameworks/full-stack/nuxt' }] },
      { heading: 'Choose from the user-visible requirement backwards', paragraphs: ['Ask whether crawlers or first-time visitors need complete HTML, how fresh the result must be, whether it contains user-specific data and what should happen without JavaScript. Those answers determine rendering more reliably than framework fashion.', 'Then verify the generated HTML, hydration, navigation, cache behaviour and deployed runtime. A route is not correctly rendered merely because it looks right after a warm client-side navigation.'] },
    ],
  },
  {
    slug: 'nuxt-server-client-boundaries', title: 'Keep Nuxt server and client boundaries explicit', category: 'Nuxt', topic: 'TypeScript', readTime: '14 min read',
    summary: 'A technical guide to Nuxt server routes, runtime configuration, API contracts, authentication and avoiding secrets or server-only dependencies in browser bundles.',
    sections: [
      { heading: 'One repository contains two execution environments', paragraphs: ['Nuxt makes server and browser code feel close, but they run with different capabilities and trust. The server can hold credentials and call protected services. Browser code is delivered to users and every value inside it must be treated as public.', 'Make imports reflect the boundary. Database clients, private SDK keys and filesystem access belong in server routes or server utilities. Components should consume typed application responses rather than importing infrastructure directly.'], code: { label: 'Expose only intentional public configuration', language: 'typescript / Nuxt', source: 'export default defineNuxtConfig({\n  runtimeConfig: {\n    openAiApiKey: process.env.OPENAI_API_KEY,\n    auth0ClientSecret: process.env.AUTH0_CLIENT_SECRET,\n    public: {\n      appBaseUrl: process.env.NUXT_PUBLIC_APP_BASE_URL,\n    },\n  },\n})\n\n// Values under public are included in the client payload.' } },
      { heading: 'Server routes are application boundaries', paragraphs: ['A file under server/api becomes an HTTP handler. Parse untrusted input, establish identity, call application behaviour and map the result to a stable response. Avoid placing the complete workflow in a page component simply because $fetch can call an external API.', 'A server route can also keep third-party API shapes away from the client. Translate the external response into the smaller contract the interface actually uses and retain diagnostic detail in server-side logs.'], code: { label: 'Validate before invoking the service', language: 'typescript / Nuxt', source: 'export default defineEventHandler(async (event) => {\n  const id = getRouterParam(event, "id")\n  if (!id) {\n    throw createError({ statusCode: 400, statusMessage: "Account id required" })\n  }\n\n  const account = await accountService(event).find(id)\n  if (!account) {\n    throw createError({ statusCode: 404, statusMessage: "Account not found" })\n  }\n\n  return AccountResponse.from(account)\n})' } },
      { heading: 'TypeScript types do not validate network data', paragraphs: ['A generic such as $fetch<AccountResponse> tells TypeScript how code intends to use the result. It does not prove that the server or third party returned that shape at runtime.', 'Validate at boundaries where data is untrusted or compatibility matters. Keep runtime schemas next to the transport contract and translate valid input into domain-oriented application values.'], code: { label: 'Treat a network response as unknown first', language: 'typescript', source: 'const raw: unknown = await $fetch("/api/account")\nconst parsed = AccountResponseSchema.safeParse(raw)\n\nif (!parsed.success) {\n  throw new Error("Account response did not match its contract")\n}\n\nconst account: AccountResponse = parsed.data' } },
      { heading: 'Authentication is more than hiding a page', paragraphs: ['A client-side route guard improves navigation but does not protect server data. Every server route that returns private information must authenticate the request and authorise the requested operation.', 'Keep access tokens out of logs and avoid exposing provider secrets through public runtime configuration. Test missing, expired and insufficient credentials at the server boundary, not only the successful browser redirect.'] },
      { heading: 'Shared code should genuinely be environment-neutral', paragraphs: ['Pure types, validation and formatting can often be shared. A shared module that conditionally checks whether window exists is frequently an environment-specific module whose ownership has become unclear.', 'Keep server-only and client-only entry points obvious. This also prevents a harmless component import from pulling a Node dependency or private configuration path into the browser build.'] },
      { heading: 'Review the built application, not just source folders', paragraphs: ['Inspect client bundles for accidental secrets and unexpectedly large server libraries. Exercise a fresh SSR request, hydrated navigation and direct API calls with invalid credentials.', 'The boundary is healthy when a reader can trace browser input through a server contract to application behaviour and back without guessing which runtime owns authentication, validation or external integration.'], links: [{ label: 'Nuxt useFetch documentation', href: 'https://nuxt.com/docs/4.x/api/composables/use-fetch' }] },
    ],
  },
  {
    slug: 'using-codex-on-real-codebases', title: 'Using Codex on a real codebase without losing engineering control', category: 'AI-assisted engineering', topic: 'AI', topics: ['Software Delivery'], readTime: '13 min read',
    summary: 'How to give Codex useful repository context, shape bounded tasks, review its evidence and keep responsibility for architecture, security and production behaviour with the engineering team.',
    sections: [
      { heading: 'Treat Codex as an agent working inside a real system', paragraphs: ['Codex can explore a codebase, build features, review changes and investigate failures. The useful shift from autocomplete is that it can gather context, use development tools and work through several connected steps toward an outcome.', 'That does not turn a vague request into a sound requirement. The agent sees the repository and tools it is given, not the unrecorded product decisions, production history or organisational constraints held by the team.'], code: { label: 'A task with an observable boundary', language: 'text', source: 'Add validation to the account creation endpoint.\n\nRequired behaviour:\n- Reject blank display names with HTTP 400.\n- Preserve the existing response schema.\n- Do not change persisted account documents.\n- Add focused controller and service tests.\n\nRun the relevant checks and summarize any assumptions.' } },
      { heading: 'Repository instructions remove repeated guesswork', paragraphs: ['Build commands, test conventions, architecture boundaries and prohibited technologies should live close to the code. Codex can follow repository instruction files and existing conventions more reliably than facts repeated incompletely in each prompt.', 'Keep those instructions testable and current. “Write clean code” provides little direction; naming the formatter, relevant test command and boundary that must not import a framework gives the agent something it can verify.'], code: { label: 'Useful repository guidance', language: 'markdown', source: '# Repository guidance\n\n- Run `npm run typecheck` after TypeScript changes.\n- Use `npm run generate` for route or content changes.\n- Keep API credentials in server runtime configuration.\n- Do not add a dependency when an existing utility covers the need.\n- Preserve unrelated working-tree changes.' } },
      { heading: 'Ask for investigation before a risky implementation', paragraphs: ['For an unfamiliar failure, request a diagnosis supported by files, logs and tests before authorising a fix. This separates evidence from a plausible-looking patch and makes hidden assumptions easier to challenge.', 'For larger work, define checkpoints: understand the path, agree the boundary, implement the smallest change, then verify it. A long autonomous run is most useful when success can still be measured by concrete tests and output.'] },
      { heading: 'Review the diff and the evidence', paragraphs: ['A passing test suite is evidence, not proof. Review public contracts, failure paths, permissions, migrations and operational behaviour. Generated tests can reproduce the implementation rather than independently protect the requirement.', 'Ask what was run, what could not be verified and which assumptions remain. Inspect the actual diff instead of relying on a summary, particularly when changes touch authentication, data deletion, deployment or dependencies.'], bullets: ['Does the change solve the stated behaviour?', 'Are unrelated files untouched?', 'Do tests fail for the regression they claim to protect?', 'Are external inputs and failure paths handled?', 'Did the agent verify the production-shaped boundary?', 'Can another engineer understand and own the result?'] },
      { heading: 'Permissions are part of the engineering model', paragraphs: ['Coding agents can modify files and may be able to run commands or access connected tools. Give the narrowest access that permits the task, review escalations and keep destructive or external actions explicit.', 'Secrets should not be placed in prompts, repository instructions or test fixtures. Treat generated terminal output and patches as material that can accidentally expose credentials, personal data or internal endpoints.'] },
      { heading: 'Use Codex where feedback can close the loop', paragraphs: ['Good tasks have an inspectable starting point and a reliable feedback loop: a failing test, build error, reproducible bug, bounded refactor or documented UI requirement. Open-ended architecture and product decisions still require accountable human judgement.', 'The aim is not to maximise generated code. It is to shorten the path from evidence to a reviewed change while keeping ownership of correctness with the people operating the software.'], links: [{ label: 'Official Codex overview', href: 'https://learn.chatgpt.com/docs' }, { label: 'Official Codex engineering use cases', href: 'https://developers.openai.com/codex/use-cases' }] },
    ],
  },
  {
    slug: 'openai-responses-and-batch-api', title: 'OpenAI API and Batch API: choosing the right execution path', category: 'AI integration', topic: 'AI', readTime: '16 min read',
    summary: 'A production-oriented guide to synchronous Responses API calls and asynchronous Batch API workloads, including boundaries, JSONL input, correlation, partial failure and operational handling.',
    sections: [
      { heading: 'Begin with the product latency requirement', paragraphs: ['An interactive request normally needs a response while the user is waiting. The Responses API supports that direct path and can return text or structured output from text, image or file input, with tools where the application needs them.', 'Batch is for work that does not require an immediate answer: offline classification, enrichment, evaluation or scheduled processing. It exchanges latency for asynchronous throughput and discounted processing rather than acting as a faster interactive endpoint.'], code: { label: 'Keep model selection in configuration', language: 'typescript / OpenAI', source: 'import OpenAI from "openai"\n\nconst client = new OpenAI({ apiKey: process.env.OPENAI_API_KEY })\n\nconst response = await client.responses.create({\n  model: process.env.OPENAI_MODEL!,\n  instructions: "Return a concise technical summary.",\n  input: sourceText,\n})\n\nconst summary = response.output_text' } },
      { heading: 'Put the API behind a server-owned boundary', paragraphs: ['Never expose the API key through browser code or public Nuxt runtime configuration. A server route should authenticate the caller, validate input, apply request limits and translate provider responses into the application contract.', 'Store stable identifiers for users and jobs rather than sending unnecessary personal data. Log provider request identifiers and local correlation IDs, but avoid logging full prompts and outputs by default when they may contain customer data.'] },
      { heading: 'A batch begins as JSONL', paragraphs: ['Each line in the input file is one request with a unique custom_id, POST method, supported relative URL and request body. The file is uploaded with purpose batch, then its file ID is used to create the batch.', 'The official API currently supports a 24-hour completion window. A batch input file can contain up to 50,000 requests and be up to 200 MB; account and model queue limits still apply. Validate the JSONL locally before upload because one formatting mistake can invalidate work.'], code: { label: 'Two independent Responses API requests', language: 'jsonl', source: '{"custom_id":"account-17","method":"POST","url":"/v1/responses","body":{"model":"YOUR_MODEL","input":"Summarise account 17"}}\n{"custom_id":"account-29","method":"POST","url":"/v1/responses","body":{"model":"YOUR_MODEL","input":"Summarise account 29"}}' } },
      { heading: 'Upload, create and observe the job', paragraphs: ['Upload the input file, create a batch for the same endpoint used by every line, then persist the returned batch ID. Polling can work for a small internal process; a production workflow should have explicit job state, bounded retry and a recovery path when the worker restarts.', 'Statuses include validation, in-progress, finalising and terminal outcomes such as completed, failed, expired or cancelled. A completed batch can still contain individual failed requests, so completion is not equivalent to every item succeeding.'], code: { label: 'Create the asynchronous batch', language: 'shell / HTTP', source: 'curl https://api.openai.com/v1/files \\\n  -H "Authorization: Bearer $OPENAI_API_KEY" \\\n  -F purpose="batch" \\\n  -F file="@requests.jsonl"\n\ncurl https://api.openai.com/v1/batches \\\n  -H "Authorization: Bearer $OPENAI_API_KEY" \\\n  -H "Content-Type: application/json" \\\n  -d "{\\"input_file_id\\":\\"file_INPUT\\",\\"endpoint\\":\\"/v1/responses\\",\\"completion_window\\":\\"24h\\"}"' } },
      { heading: 'Correlate by custom_id, never by line order', paragraphs: ['Output order may differ from input order. Join every result to application state using custom_id and make that identifier unique within the batch. Keep it opaque enough that exported output files do not disclose sensitive domain information.', 'Successful results and request errors are available through output and error files. Record each item independently so a retry batch contains only failed or expired work. Idempotent result handling prevents a restarted importer from applying the same enrichment twice.'], code: { label: 'Index output by the application identifier', language: 'typescript', source: 'type BatchLine = {\n  custom_id: string\n  response?: { status_code: number; body: unknown }\n  error?: { code: string; message: string }\n}\n\nfor (const line of outputLines as BatchLine[]) {\n  if (line.response?.status_code === 200) {\n    await results.saveOnce(line.custom_id, line.response.body)\n  } else {\n    await failures.record(line.custom_id, line.error ?? line.response)\n  }\n}' } },
      { heading: 'Production quality lives around the model call', paragraphs: ['Set timeouts and retry only transient failures for direct requests. Validate structured results before they enter the domain, monitor token usage and latency, and evaluate behaviour against representative examples whenever prompts or models change.', 'For batches, monitor queued volume, age, item failure rate and import completion. Keep prompts and model configuration versioned with the job so an output can be explained after the application has moved on.'], links: [{ label: 'Official Responses API reference', href: 'https://developers.openai.com/api/reference/resources/responses/methods/create' }, { label: 'Official Batch API reference', href: 'https://developers.openai.com/api/reference/resources/batches' }, { label: 'Official Files API reference', href: 'https://developers.openai.com/api/reference/resources/files/methods/create' }] },
    ],
  },
  {
    slug: 'deploying-nuxt-on-vercel', title: 'Deploying Nuxt on Vercel without ignoring the runtime', category: 'Vercel', topic: 'Serverless', topics: ['TypeScript', 'Platform & DevOps'], readTime: '14 min read',
    summary: 'How Nuxt build modes, Vercel deployments, functions, environment variables, data locality and observability shape a production application after the first successful deploy.',
    sections: [
      { heading: 'A successful deployment is only the first boundary', paragraphs: ['Vercel can build a connected Git repository and give each deployment a unique URL. That makes previewing a Nuxt change straightforward, but production readiness still depends on knowing which routes are static, which execute on the server and which external systems they call.', 'Treat the deployment summary as an architectural view: static assets, middleware and functions should match what the team believes it shipped. Unexpected functions or oversized bundles often reveal a rendering or import decision worth revisiting.'] },
      { heading: 'Choose build or generate from runtime needs', paragraphs: ['A normal Nuxt build can support SSR, static generation and platform features through Nitro. nuxt generate creates a fully static site and does not provide request-time SSR. Content sites can suit generation; authenticated or frequently changing server-rendered routes usually need a server build.', 'Do not choose generate only to avoid understanding server functions. Decide whether each route needs request-time data, user identity or immediate freshness, then select route rules and deployment output accordingly.'], code: { label: 'Keep the deployment preset explicit when useful', language: 'typescript / Nuxt', source: 'export default defineNuxtConfig({\n  nitro: { preset: "vercel" },\n  routeRules: {\n    "/": { prerender: true },\n    "/insights/**": { prerender: true },\n    "/account/**": { ssr: true },\n  },\n})' } },
      { heading: 'Environment values belong to a deployment environment', paragraphs: ['Vercel separates development, preview and production values. A change applies to new deployments rather than retroactively changing an existing one. This makes deployments reproducible, but it also means rotating a credential requires a redeploy where the application reads it.', 'Keep secrets server-only and use Nuxt public runtime configuration only for values safe to expose. Preview environments should not silently share production databases, Auth0 callbacks or external write credentials.'], code: { label: 'Separate private and public runtime configuration', language: 'typescript / Nuxt', source: 'export default defineNuxtConfig({\n  runtimeConfig: {\n    databaseUrl: process.env.DATABASE_URL,\n    auth0ClientSecret: process.env.AUTH0_CLIENT_SECRET,\n    public: {\n      baseUrl: process.env.NUXT_PUBLIC_BASE_URL,\n    },\n  },\n})' } },
      { heading: 'Functions still have operational constraints', paragraphs: ['Serverless removes server management, not networking, concurrency or resource behaviour. A function that opens too many PostgreSQL connections, waits on a distant API or assumes a persistent writable filesystem can fail under real traffic.', 'Place compute close to its database where the platform permits and use connection behaviour suitable for the managed database. Keep long jobs out of request handlers and make external calls bounded by timeouts and useful errors.'] },
      { heading: 'Preview deployments need a verification purpose', paragraphs: ['A preview URL is valuable when it lets someone verify the actual build, routes and integration configuration before production. It is less useful when missing credentials cause every server path to fall back to mock behaviour.', 'Define which checks a preview supports, provide isolated test data where required and test direct page loads as well as client navigation. Authentication callback URLs and generated canonical metadata commonly differ between preview and production.'] },
      { heading: 'Observe cost and failure at the deployed boundary', paragraphs: ['Use function logs and platform observability to follow invocation volume, duration, errors and external requests. Add application correlation IDs so a browser failure can be traced through a Nuxt server route to a database or third-party API.', 'Production confidence includes rollback and configuration history. A previous deployment is useful only when its expected environment and compatible database schema still exist.'], links: [{ label: 'Vercel Nuxt documentation', href: 'https://vercel.com/docs/frameworks/full-stack/nuxt' }, { label: 'Vercel deployment overview', href: 'https://vercel.com/docs/deployments/overview' }, { label: 'Vercel environment variables', href: 'https://vercel.com/docs/environment-variables' }, { label: 'Vercel observability', href: 'https://vercel.com/docs/observability' }] },
    ],
  },
  {
    slug: 'postgresql-schema-indexes-and-query-behaviour', title: 'PostgreSQL in application code: schemas, indexes and query behaviour', category: 'PostgreSQL', topic: 'Databases', readTime: '15 min read',
    summary: 'A practical PostgreSQL guide to relational modelling, constraints, indexes, transactions, EXPLAIN and keeping persistence behaviour visible in application code.',
    sections: [
      { heading: 'The database schema is an executable contract', paragraphs: ['Application validation improves feedback, but PostgreSQL constraints protect data regardless of which process writes it. Primary keys, foreign keys, uniqueness, nullability and check constraints should represent invariants the database can enforce.', 'Do not duplicate every domain rule in SQL. A rule requiring external state or a complex workflow may belong in application behaviour. Put durable relational facts in the schema and give constraint failures a deliberate application translation.'], code: { label: 'Let the schema protect relational facts', language: 'sql / PostgreSQL', source: 'CREATE TABLE account (\n  id uuid PRIMARY KEY,\n  display_name text NOT NULL CHECK (length(trim(display_name)) > 0),\n  status text NOT NULL CHECK (status IN (\'pending\', \'active\', \'closed\')),\n  external_reference text NOT NULL UNIQUE,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE payment (\n  id uuid PRIMARY KEY,\n  account_id uuid NOT NULL REFERENCES account(id),\n  amount numeric(18, 2) NOT NULL CHECK (amount > 0)\n);' } },
      { heading: 'Normalisation makes updates less ambiguous', paragraphs: ['Separate facts that have different identity and lifecycle. Repeating an account name across every payment makes renaming expensive and permits contradictory copies. A foreign key records the relationship without duplicating the account.', 'Denormalisation can be justified for measured read paths or historical snapshots, but it creates a synchronisation rule the system must own. Record whether copied data is a snapshot, cache or second source of truth.'] },
      { heading: 'Indexes should follow real access paths', paragraphs: ['An index can make selected reads much faster while adding storage and write overhead. Index the columns and order used by important filters, joins and sorting rather than adding one index for every column.', 'A multicolumn B-tree index is most useful when its leading columns match the query pattern. Partial and expression indexes can target narrower workloads. Unique indexes enforce identity as well as accelerate lookup.'], code: { label: 'Support one observed query shape', language: 'sql / PostgreSQL', source: 'CREATE INDEX payment_account_created_idx\n  ON payment (account_id, created_at DESC);\n\nSELECT id, amount, created_at\nFROM payment\nWHERE account_id = $1\nORDER BY created_at DESC\nLIMIT 50;' } },
      { heading: 'Read the plan instead of guessing', paragraphs: ['EXPLAIN shows the plan selected by PostgreSQL. EXPLAIN ANALYZE executes the statement and reports actual timing and row counts, allowing estimated rows to be compared with reality. Use it carefully on writes because the statement really runs unless contained and rolled back.', 'Look for the first large divergence between estimated and actual rows, unexpected repeated loops, expensive sorting and reads that touch far more rows than they return. A sequential scan is not automatically wrong; it can be cheapest for a small table or a query returning much of it.'], code: { label: 'Inspect execution with buffers', language: 'sql / PostgreSQL', source: 'EXPLAIN (ANALYZE, BUFFERS)\nSELECT id, amount, created_at\nFROM payment\nWHERE account_id = \'2f20b77a-7e6a-4ab9-a28c-f271ef28ea31\'\nORDER BY created_at DESC\nLIMIT 50;' } },
      { heading: 'Transaction boundaries belong to the use case', paragraphs: ['A transaction should contain the writes and reads that must succeed as one decision. Putting each repository call in its own hidden transaction can leave a workflow partially applied; holding a transaction open across slow external HTTP calls increases contention.', 'Keep transaction ownership in the application operation that understands atomicity. Handle expected uniqueness conflicts explicitly and make retries safe where isolation failures can occur.'] },
      { heading: 'Persistence code should expose query behaviour', paragraphs: ['Repository abstractions should use domain-oriented inputs and results without pretending all persistence is free. Pagination, locking, missing rows and uniqueness affect the service contract and tests.', 'Integration tests should apply real migrations and exercise representative queries. Monitor slow queries and connection use in production, then use that evidence to revise indexes or access patterns rather than relying on local sample data.'], links: [{ label: 'PostgreSQL index documentation', href: 'https://www.postgresql.org/docs/current/indexes.html' }, { label: 'PostgreSQL EXPLAIN guide', href: 'https://www.postgresql.org/docs/current/using-explain.html' }] },
    ],
  },
  {
    slug: 'database-normalisation-in-practice', title: 'Database normalisation in practice: model each fact once', category: 'Relational modelling', topic: 'Databases', topics: ['Architecture'], readTime: '16 min read',
    summary: 'A practical guide to functional dependencies, update anomalies, first through third normal form, join tables, historical facts and deliberate denormalisation in PostgreSQL applications.',
    sections: [
      { heading: 'Normalisation is about the ownership of facts', paragraphs: ['Normalisation is a way of arranging relational data so that each fact has a clear owner. A customer email belongs to a customer, an order date belongs to an order, and the quantity purchased belongs to one order line. When those facts are repeated in several rows, the database can represent contradictory versions of the same reality.', 'The purpose is not to create as many tables as possible. It is to reduce insertion, update and deletion anomalies while allowing the database to enforce meaningful relationships. A schema is easier to change when a developer can say where a fact is stored and which key determines it.', 'Normal forms provide a vocabulary for testing that structure. They are useful reasoning tools, not a substitute for understanding identity, history and the queries the application must support.'], bullets: ['Insertion anomaly: one fact cannot be recorded until an unrelated fact exists', 'Update anomaly: one logical change requires several rows to stay in agreement', 'Deletion anomaly: removing one fact accidentally removes the only record of another'] },
      { heading: 'Begin with keys and functional dependencies', paragraphs: ['A functional dependency states that one set of attributes determines another. CustomerId → CustomerEmail means that for a given customer identifier there is one current email value in the model. The left side is called the determinant.', 'Candidate keys are minimal sets of attributes that uniquely identify a row. One candidate key is selected as the primary key, but the other candidate keys still matter and normally need unique constraints. A generated id does not make natural dependencies disappear.', 'Write the important dependencies before moving columns between tables. If ProductId determines ProductName, repeating the name on every order line creates a copied fact. If an order line records the price actually agreed at purchase, that price may instead be determined by the order line itself and should not be replaced whenever the product’s current price changes.'], code: { label: 'Expose the mixed dependencies in one wide table', language: 'text', source: 'order_item(\n  order_id,\n  order_created_at,\n  customer_id,\n  customer_email,\n  product_id,\n  product_name,\n  unit_price_paid,\n  quantity\n)\n\nCandidate key: (order_id, product_id)\n\norder_id   → order_created_at, customer_id\ncustomer_id → customer_email\nproduct_id → product_name\n(order_id, product_id) → unit_price_paid, quantity' } },
      { heading: 'First normal form removes repeating groups', paragraphs: ['In first normal form, each row is identified by a key and each column holds one value from its declared domain. Repeating columns such as product_1, product_2 and product_3 make the maximum collection size part of the schema and force queries to inspect several columns for the same relationship.', 'Comma-separated identifiers in a text column create the same problem in disguise. The database cannot apply a foreign key to each embedded value, and ordinary joins, uniqueness and indexing become awkward.', 'Atomic does not mean a value can never contain internal structure. A timestamp and a postal address string can each be treated as one value for a particular model. PostgreSQL arrays and JSON are legitimate types, but using them moves parts of the data outside ordinary relational constraints. Make that trade-off intentionally rather than calling every nested value a first-normal-form violation.'], code: { label: 'Replace repeating product columns with rows', language: 'sql / PostgreSQL', source: '-- Avoid a fixed collection encoded in columns:\n-- order_id, product_1, product_2, product_3\n\nCREATE TABLE order_line (\n  order_id uuid NOT NULL REFERENCES sales_order(id),\n  line_number integer NOT NULL CHECK (line_number > 0),\n  product_id uuid NOT NULL REFERENCES product(id),\n  quantity integer NOT NULL CHECK (quantity > 0),\n  PRIMARY KEY (order_id, line_number)\n);' } },
      { heading: 'Second normal form removes partial dependency on a composite key', paragraphs: ['Second normal form applies when a candidate key contains more than one attribute. Every non-key attribute should depend on the whole candidate key, not only part of it.', 'In the wide order-item table, order_created_at depends only on order_id and product_name depends only on product_id. Repeating either value for every item creates update anomalies. Moving order facts into sales_order and product facts into product gives each dependency a relation where its determinant is a key.', 'A table with a single-column candidate key cannot have a partial dependency on that key, so it is already in second normal form if it satisfies first normal form. Adding a synthetic id can hide the composite business key from view; preserve the natural uniqueness constraint where duplicate relationships are not valid.'], code: { label: 'Give order and product facts their own relations', language: 'sql / PostgreSQL', source: 'CREATE TABLE product (\n  id uuid PRIMARY KEY,\n  name text NOT NULL,\n  current_price numeric(18, 2) NOT NULL CHECK (current_price >= 0)\n);\n\nCREATE TABLE sales_order (\n  id uuid PRIMARY KEY,\n  customer_id uuid NOT NULL REFERENCES customer(id),\n  created_at timestamptz NOT NULL\n);\n\nCREATE TABLE order_line (\n  order_id uuid NOT NULL REFERENCES sales_order(id),\n  line_number integer NOT NULL,\n  product_id uuid NOT NULL REFERENCES product(id),\n  unit_price_paid numeric(18, 2) NOT NULL CHECK (unit_price_paid >= 0),\n  quantity integer NOT NULL CHECK (quantity > 0),\n  PRIMARY KEY (order_id, line_number)\n);' } },
      { heading: 'Third normal form removes dependencies through non-key attributes', paragraphs: ['Third normal form addresses transitive dependencies. If order_id determines customer_id and customer_id determines customer_email, then storing customer_email on the order makes it depend on the order through another non-key attribute.', 'The repeated email can disagree with the customer row and requires every open order to be updated when the customer changes it. Store the current email with the customer and join it when the application needs the current customer details.', 'This reasoning depends on meaning. If the order must preserve the billing email used when it was placed, that value is a historical fact about the order rather than a copy of the customer’s current email. Naming it billing_email_at_purchase makes the different dependency explicit.'], code: { label: 'Separate current customer data from an intentional snapshot', language: 'sql / PostgreSQL', source: 'CREATE TABLE customer (\n  id uuid PRIMARY KEY,\n  email text NOT NULL UNIQUE\n);\n\nCREATE TABLE sales_order (\n  id uuid PRIMARY KEY,\n  customer_id uuid NOT NULL REFERENCES customer(id),\n  billing_email_at_purchase text NOT NULL,\n  created_at timestamptz NOT NULL\n);\n\n-- customer.email is the current contact detail.\n-- billing_email_at_purchase is part of the historical order.' } },
      { heading: 'BCNF catches determinants that are not candidate keys', paragraphs: ['Boyce–Codd normal form is stricter than third normal form: for every non-trivial functional dependency, the determinant should be a superkey. It matters in less common schemas where candidate keys overlap and a determinant can satisfy the technical rule for third normal form without identifying the complete row.', 'Most application schemas gain more from confidently reaching third normal form than from applying BCNF mechanically. If a table records several independent relationships—such as which instructor can teach a subject and which instructor is assigned to a course—separate those facts rather than forcing them into one relation whose constraints are hard to express.', 'The useful question remains concrete: can two rows assert conflicting values for a fact that should have one owner? If so, identify its determinant and decide whether it belongs in another relation.'] },
      { heading: 'Many-to-many relationships deserve an explicit table', paragraphs: ['A student can join many courses and a course can contain many students. Neither foreign key belongs as a list inside the other row when the relationship needs relational constraints or carries facts of its own.', 'A junction table gives the relationship a key and a place for attributes such as enrolment time or status. Those values depend on the student-course relationship, not on the student or course independently.', 'Choose the key from the relationship’s semantics. A composite primary key prevents duplicate membership. A generated enrolment id may be useful when other records refer to one enrolment, but it should not silently permit duplicate active enrolments if the domain forbids them.'], code: { label: 'Model the relationship and its facts directly', language: 'sql / PostgreSQL', source: 'CREATE TABLE enrolment (\n  student_id uuid NOT NULL REFERENCES student(id),\n  course_id uuid NOT NULL REFERENCES course(id),\n  enrolled_at timestamptz NOT NULL DEFAULT now(),\n  status text NOT NULL CHECK (status IN (\'active\', \'completed\', \'withdrawn\')),\n  PRIMARY KEY (student_id, course_id)\n);' } },
      { heading: 'Normalisation does not dictate the application API', paragraphs: ['A normalised persistence model can be joined into a response shaped for one use case. The HTTP client does not need to receive four database tables merely because the data is stored across four relations.', 'Keep query behaviour visible. Loading an order and then issuing one product query for every line is an application access problem, not proof that the schema should duplicate product data. Use an intentional join or a bounded set-based query and map the rows into the application result.', 'Repository boundaries should reflect useful operations while preserving important database behaviour such as transaction ownership, missing rows and uniqueness. An abstraction that hides every join can make performance harder to understand without making the model simpler.'], code: { label: 'Read a complete order with one set-based query', language: 'sql / PostgreSQL', source: 'SELECT\n  o.id AS order_id,\n  o.created_at,\n  c.id AS customer_id,\n  c.email AS current_customer_email,\n  l.line_number,\n  p.name AS product_name,\n  l.unit_price_paid,\n  l.quantity\nFROM sales_order o\nJOIN customer c ON c.id = o.customer_id\nJOIN order_line l ON l.order_id = o.id\nJOIN product p ON p.id = l.product_id\nWHERE o.id = $1\nORDER BY l.line_number;' } },
      { heading: 'Denormalise only when the copied fact has a policy', paragraphs: ['Denormalisation can be appropriate for a measured read bottleneck, reporting workload, immutable snapshot or precomputed summary. It deliberately introduces duplication, so the design must state which representation is authoritative and how the copy is refreshed.', 'Adding customer_email to an order summary table might avoid an expensive reporting join, but it raises specific questions: should historical summaries change when the email changes, what happens if refresh fails, and can consumers tolerate stale data?', 'Measure before denormalising. Appropriate indexes, a corrected query or a smaller result set often fixes the actual problem without adding synchronisation. When duplication is justified, name it as a cache, snapshot or projection so later engineers do not mistake it for another source of truth.'], bullets: ['Name the authoritative relation', 'Define whether the copy is current, eventually consistent or historical', 'Make refresh and failure behaviour observable', 'Test reconciliation or rebuilding', 'Record the query evidence that justified the extra complexity'] },
      { heading: 'Normalising an existing schema is a compatibility change', paragraphs: ['Splitting a live table affects application reads, writes, migrations and rollback. Add the new relations and constraints in stages, backfill them from existing data, and detect contradictions before requiring the new model.', 'During transition, one application version may need to write both shapes or read the new shape with a controlled fallback. Keep that compatibility period short and observable. Dual writes can fail independently, so they need reconciliation rather than an assumption that both always succeeded.', 'Validate row counts, missing relationships and uniqueness before making foreign keys or not-null constraints mandatory. Remove the old columns only after every supported application version has stopped depending on them and rollback no longer requires the old representation.', 'Normalisation succeeds when the resulting ownership is clearer in the database and in application code. Reaching a named normal form is useful evidence, but the real result is fewer contradictory states and a model whose history and constraints match the domain.'], code: { label: 'Find contradictory copied values before splitting them out', language: 'sql / PostgreSQL', source: 'SELECT customer_id, count(DISTINCT customer_email) AS email_versions\nFROM legacy_order_item\nGROUP BY customer_id\nHAVING count(DISTINCT customer_email) > 1;\n\n-- Resolve contradictions before adding a unique customer row.\n-- A migration cannot infer which repeated value is authoritative.' } },
    ],
  },
  {
    slug: 'github-actions-ci-cd-that-remains-understandable', title: 'GitHub Actions CI/CD that remains understandable', category: 'GitHub Actions', topic: 'Platform & DevOps', topics: ['Testing', 'Software Delivery'], readTime: '15 min read',
    summary: 'A practical guide to building GitHub Actions workflows with useful feedback, narrow permissions, deliberate caching, durable artifacts and safer deployment boundaries.',
    sections: [
      { heading: 'Start with the workflow execution model', paragraphs: ['A workflow is a YAML file in .github/workflows. An event starts a workflow run, jobs contain steps, and each job runs on a runner. Steps in one job share its workspace; separate jobs should be treated as separate machines unless files are passed between them explicitly.', 'That distinction prevents a common source of confusion. A package installed or file produced in the build job does not simply appear in a later deploy job. The workflow needs an artifact, cache or repeated setup step depending on what the data represents.', 'Keep the first workflow small enough to explain: one pull-request trigger, one verification job and the commands developers already trust locally. CI should automate the project contract rather than invent a second build system in YAML.'], code: { label: 'A focused pull-request workflow', language: 'yaml / GitHub Actions', source: 'name: verify\n\non:\n  pull_request:\n  push:\n    branches: [main]\n\npermissions:\n  contents: read\n\nconcurrency:\n  group: verify-${{ github.ref }}\n  cancel-in-progress: true\n\njobs:\n  test:\n    runs-on: ubuntu-latest\n    timeout-minutes: 15\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n          cache: npm\n      - run: npm ci\n      - run: npm run typecheck\n      - run: npm test\n      - run: npm run generate' } },
      { heading: 'Make pull-request feedback fast and meaningful', paragraphs: ['The checks should answer whether the proposed change is safe to review and merge. Run formatting or linting, type checking, focused tests and a production-shaped build where those commands protect real failure modes.', 'Order quick, diagnostic checks before slower work, but do not split every command into another job. More jobs add runner startup time and make shared setup explicit. Split work when it can run independently, needs a different runtime or has a genuinely different responsibility.', 'Use timeouts so a deadlocked test cannot consume a runner indefinitely. Cancelling superseded runs on the same branch also prevents old commits competing with the version a reviewer is actually reading.'] },
      { heading: 'Cache dependencies; publish build outputs as artifacts', paragraphs: ['A cache is an optimisation for data that can be recreated, such as downloaded npm or Maven dependencies. A cache miss must make the workflow slower, not incorrect. Keys should change when the dependency lock file changes and should not include secrets.', 'An artifact is an output that another job or a person needs from this particular run: a compiled package, generated report or test result. Upload it with a clear name and an intentional retention period. A deployment pipeline can then promote the exact artifact that passed verification instead of rebuilding potentially different source or dependencies.', 'Caching node_modules directly is often more fragile than caching the package manager download store and continuing to run npm ci. Setup actions can manage the relevant cache without hiding dependency installation.'], bullets: ['Cache: reusable performance data that may safely disappear', 'Artifact: an output belonging to one workflow run', 'Release asset: a versioned deliverable intended for consumers'] },
      { heading: 'Give the workflow only the permissions it needs', paragraphs: ['Set permissions explicitly. A verification job that only checks out source often needs contents: read and nothing more. Grant write permissions to the smallest job that performs the write rather than to the complete workflow.', 'Secrets are not ordinary configuration. Keep non-sensitive values in variables, restrict secrets to the environment and job that need them, and avoid printing command input that can contain credentials. Workflows triggered from forks have different secret behaviour by design.', 'Treat pull_request_target with particular care because it runs in the context of the base repository. Checking out and executing untrusted pull-request code in that context can expose privileged tokens or secrets. Use the ordinary pull_request event for building untrusted changes unless there is a carefully designed reason not to.'], code: { label: 'Narrow deployment permissions to one job', language: 'yaml / GitHub Actions', source: 'jobs:\n  deploy:\n    needs: build\n    runs-on: ubuntu-latest\n    environment: production\n    permissions:\n      contents: read\n      id-token: write\n    steps:\n      - uses: actions/download-artifact@v4\n        with:\n          name: application\n      - run: ./scripts/deploy.sh' } },
      { heading: 'Use environments as a deployment boundary', paragraphs: ['A GitHub environment can separate production from preview or test deployment configuration. Environment secrets, protection rules and deployment history make the boundary visible in the repository rather than burying it inside a long conditional script.', 'Build once, verify that build, then deploy the same artifact. Rebuilding inside the production job weakens the connection between what passed and what shipped. Database migrations and configuration compatibility still need their own release plan; an environment approval does not make an unsafe change reversible.', 'Use concurrency to prevent production deployments racing each other. CI for a superseded commit can be cancelled, while production work usually needs serialisation rather than interruption halfway through a release.'], code: { label: 'Serialize production deployment', language: 'yaml / GitHub Actions', source: 'jobs:\n  deploy-production:\n    needs: build\n    environment: production\n    concurrency:\n      group: production\n      cancel-in-progress: false\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/download-artifact@v4\n        with:\n          name: application\n      - run: ./scripts/deploy.sh' } },
      { heading: 'Matrices and reusable workflows should remove proven repetition', paragraphs: ['A matrix is useful when the same verification genuinely needs several supported runtimes or operating systems. It is less useful when it multiplies combinations that nobody supports or knows how to diagnose.', 'Reusable workflows can centralise an established release path across repositories. Start by making one pipeline clear, then extract the stable shared contract. A generic organisation-wide workflow created too early tends to accumulate inputs and exceptions until application teams cannot tell what actually runs.', 'Keep application commands in the repository build tool where possible. npm scripts, Maven goals and sbt tasks can be run locally; a large shell program embedded only in workflow YAML is harder to reproduce.'] },
      { heading: 'Design failure output for the person responding', paragraphs: ['A red check should identify the command, relevant error and artifact needed to investigate. Name jobs after the promise they protect, preserve test reports when useful and keep logs free of unrelated setup noise.', 'Pin action versions deliberately and review dependency updates like application dependencies. Add monitoring around deployment outcomes rather than treating a green workflow as proof the service is healthy after release.', 'A dependable pipeline is not the YAML with the most stages. It is the shortest route from a proposed change to trustworthy evidence, followed by a controlled path that ships the same verified output.'], links: [{ label: 'GitHub workflow syntax', href: 'https://docs.github.com/en/actions/reference/workflows-and-actions/workflow-syntax' }, { label: 'GitHub dependency caching', href: 'https://docs.github.com/en/actions/concepts/workflows-and-actions/dependency-caching' }, { label: 'GitHub workflow artifacts', href: 'https://docs.github.com/en/actions/concepts/workflows-and-actions/workflow-artifacts' }, { label: 'GitHub deployment environments', href: 'https://docs.github.com/en/actions/concepts/workflows-and-actions/deployment-environments' }] },
    ],
  },
  {
    slug: 'handling-async-code-in-typescript', title: 'Handling asynchronous code in TypeScript without losing control', category: 'TypeScript', topic: 'TypeScript', topics: ['Architecture', 'Testing'], readTime: '16 min read',
    summary: 'How to compose promises, preserve useful errors, cancel obsolete work, limit concurrency and test asynchronous behaviour without timing-dependent tests.',
    sections: [
      { heading: 'A Promise is one eventual result, not the operation itself', paragraphs: ['An async function always returns a Promise. Returning a plain value fulfils it, throwing rejects it, and awaiting another promise pauses only that async function while the surrounding event loop can continue.', 'A promise can be observed by several consumers, but it represents one result and cannot be restarted. Creating a promise often starts the underlying work immediately, which matters when an array is mapped to async callbacks before concurrency is considered.', 'Use explicit return types on application boundaries. Promise<Account> communicates success but says nothing about expected absence or domain rejection; those outcomes may deserve a union or result type rather than an undocumented exception.'], code: { label: 'Keep expected outcomes in the return type', language: 'typescript', source: 'type FindAccountResult =\n  | { kind: "found"; account: Account }\n  | { kind: "not-found" }\n\nasync function findAccount(id: AccountId): Promise<FindAccountResult> {\n  const row = await repository.find(id)\n  return row\n    ? { kind: "found", account: Account.from(row) }\n    : { kind: "not-found" }\n}' } },
      { heading: 'Prefer straight-line await when operations depend on each other', paragraphs: ['await makes a dependent sequence readable and gives try/catch the same shape as synchronous control flow. It does not make the function synchronous, nor does it block the process while network I/O is pending.', 'Do not mix await and .then chains without a reason. Both use promises, but switching styles inside one operation makes return paths and error handling harder to follow. Always return or await a promise created inside an async function so rejection remains connected to the caller.', 'A floating promise is work the caller cannot observe. Linters can detect many accidental cases, but deliberate background work still needs an owner, failure reporting and a shutdown policy.'], code: { label: 'Keep the asynchronous chain attached to its caller', language: 'typescript', source: 'async function activateAccount(id: AccountId): Promise<Account> {\n  const account = await accounts.load(id)\n  const activated = account.activate()\n  await accounts.save(activated)\n  await audit.record({ type: "account-activated", id })\n  return activated\n}\n\n// The caller can now observe every failure in the operation.' } },
      { heading: 'Run independent work concurrently, not everything concurrently', paragraphs: ['Sequential awaits are correct when the second operation needs the first result. Independent calls can begin together and be awaited with Promise.all, reducing total latency to roughly the slowest operation rather than the sum.', 'Promise.all rejects when one input rejects, but it does not cancel the other operations. Promise.allSettled is appropriate when every outcome must be collected, such as a batch status screen. It should not be used to quietly turn failures into success.', 'Starting thousands of requests at once can exhaust sockets, rate limits or database connections. Use a worker pool or concurrency-limited mapper for collections whose size is not tightly bounded.'], code: { label: 'Choose concurrency from dependency and capacity', language: 'typescript', source: 'const [account, permissions] = await Promise.all([\n  accounts.load(id),\n  authorisation.permissionsFor(userId),\n])\n\nconst outcomes = await Promise.allSettled(\n  selectedIds.map(id => notifications.send(id)),\n)\n\nconst failures = outcomes.filter(\n  (outcome): outcome is PromiseRejectedResult => outcome.status === "rejected",\n)' } },
      { heading: 'Preserve error meaning across boundaries', paragraphs: ['catch receives unknown under strict TypeScript settings because JavaScript can throw any value. Narrow it before reading properties and avoid catch blocks that replace every failure with an empty value.', 'Expected domain outcomes can be returned as typed values. Infrastructure failures usually remain exceptions until an application boundary logs useful context and translates them into an HTTP or job result. Do not report a database timeout as “account not found” merely because both paths failed to produce an account.', 'Wrap an error only when the new layer adds meaning, and retain the original cause. Log once at the boundary that owns the operation; logging and rethrowing at every layer produces several copies without more evidence.'], code: { label: 'Add context without discarding the cause', language: 'typescript', source: 'class AccountLoadError extends Error {\n  constructor(readonly accountId: AccountId, cause: unknown) {\n    super(`Unable to load account ${accountId}`, { cause })\n    this.name = "AccountLoadError"\n  }\n}\n\nasync function load(id: AccountId): Promise<Account> {\n  try {\n    return await repository.load(id)\n  } catch (error: unknown) {\n    throw new AccountLoadError(id, error)\n  }\n}' } },
      { heading: 'Cancellation needs cooperation', paragraphs: ['A promise has no general cancel method. Browser fetch and many modern APIs accept an AbortSignal, which lets the caller communicate that a result is no longer wanted. The callee must pass the signal through every supported dependency for cancellation to have an effect.', 'Cancellation is useful for superseded searches, disconnected requests, timeouts and application shutdown. It does not undo a remote side effect that already happened, so write operations still need idempotency and explicit status handling.', 'Distinguish cancellation from an operational failure where the user experience or retry policy differs. Always clean up timers and listeners so cancellation machinery does not itself leak resources.'], code: { label: 'Pass cancellation from the owner to the I/O boundary', language: 'typescript', source: 'async function searchAccounts(\n  query: string,\n  signal: AbortSignal,\n): Promise<AccountSummary[]> {\n  const response = await fetch(`/api/accounts?q=${encodeURIComponent(query)}`, { signal })\n  if (!response.ok) throw new Error(`Search failed: ${response.status}`)\n  return parseAccountSummaries(await response.json())\n}\n\nconst controller = new AbortController()\nconst request = searchAccounts("mushroom", controller.signal)\ncontroller.abort()\nawait request' } },
      { heading: 'Timeout the operation, not only the wait', paragraphs: ['Racing an operation against a timer can stop the caller waiting, but it does not automatically stop the losing operation. It may continue consuming a connection or complete a write after the timeout has been reported.', 'Prefer a dependency with AbortSignal or a native timeout option, and make ownership clear. Clear the timer after completion and preserve whether the failure was timeout, cancellation or a response from the remote system.'], code: { label: 'A fetch timeout that also aborts the request', language: 'typescript', source: 'async function fetchWithTimeout(url: string, timeoutMs: number): Promise<Response> {\n  const controller = new AbortController()\n  const timeout = setTimeout(() => controller.abort(), timeoutMs)\n\n  try {\n    return await fetch(url, { signal: controller.signal })\n  } finally {\n    clearTimeout(timeout)\n  }\n}' } },
      { heading: 'Do not hide asynchronous work inside array helpers', paragraphs: ['forEach ignores the promises returned by an async callback. The outer function can finish before any item completes, and rejections may become unhandled. Use for...of for a deliberate sequence or map plus Promise.all for a small, bounded concurrent set.', 'The same caution applies to filter and reduce. Their callbacks expect immediate values, so an async predicate does not create an asynchronous filter. Resolve the decisions first, then perform the synchronous collection operation.'], code: { label: 'Make sequential and concurrent intent visible', language: 'typescript', source: '// Sequential: preserve order or protect a constrained dependency\nfor (const account of accounts) {\n  await migrate(account)\n}\n\n// Concurrent: safe only for a known, bounded collection\nawait Promise.all(accounts.map(account => refresh(account)))\n\n// Not awaited by forEach:\n// accounts.forEach(async account => migrate(account))' } },
      { heading: 'Test outcomes without waiting on real time', paragraphs: ['An async test must return or await the promise under test. Otherwise the test runner can complete before a later assertion or rejection occurs. Assert both fulfilment and rejection paths, including the error information a caller relies on.', 'Inject dependencies and clocks so the test can control completion. Deferred promises are useful for proving ordering or concurrency without sleep calls. Fake timers can test timeout policy, but they should be advanced deliberately and restored after the test.', 'Integration tests still matter where behaviour depends on fetch, database drivers, framework request lifetimes or cancellation support. A unit test with an immediately resolved mock cannot prove that a real boundary handles latency, disconnects or partial failure.'], code: { label: 'Make the test observe the returned promise', language: 'typescript / Vitest', source: 'it("reports a failed account lookup", async () => {\n  repository.load.mockRejectedValueOnce(new Error("connection refused"))\n\n  await expect(service.load(accountId)).rejects.toMatchObject({\n    name: "AccountLoadError",\n    accountId,\n  })\n})\n\nit("waits for the audit record before completing", async () => {\n  const auditCompleted = deferred<void>()\n  audit.record.mockReturnValueOnce(auditCompleted.promise)\n\n  const activation = service.activate(accountId)\n  expect(await isSettled(activation)).toBe(false)\n\n  auditCompleted.resolve()\n  await expect(activation).resolves.toMatchObject({ status: "active" })\n})' } },
      { heading: 'Put policy where the application can see it', paragraphs: ['Retries, timeouts, concurrency limits and cancellation are application policies, not scattered syntax corrections. Keep them close to the operation that understands idempotency, capacity and the user-facing deadline.', 'A retry can duplicate a write or amplify an outage. Retry only failures known to be transient, use bounded attempts with delay, and keep the complete operation within a useful deadline. Record enough context to explain which attempt and dependency failed.', 'Well-structured asynchronous TypeScript is not code with await on every line. It makes ownership visible: who starts the work, who waits, who can cancel it, how much may run at once and where a failure becomes an application result.'] },
    ],
  },
  {
    slug: 'vim-controls-and-essential-commands', title: 'Vim controls: the knowledge and keys that matter', category: 'Developer tools', topic: 'Misc', readTime: '15 min read',
    summary: 'A practical guide to Vim’s modes, motions, operators, text objects, search, undo, registers and file navigation—without beginning with a wall of commands to memorise.',
    sections: [
      { heading: 'Vim starts making sense when you stop treating it like a normal editor', paragraphs: ['Vim is modal. The same key performs different work depending on the current mode, which is why the editor initially feels uncooperative if every key is expected to insert text.', 'Normal mode is where navigation and editing commands begin. Insert mode enters text. Visual mode selects text, and command-line mode accepts commands such as writing a file or running a substitution. Press Esc whenever the current state is unclear; it returns to Normal mode from the ordinary editing modes.', 'The status line normally shows modes such as -- INSERT -- or -- VISUAL --. Normal mode often has no mode label, so an apparently inactive editor may simply be waiting for a command.'], code: { label: 'The four modes to learn first', language: 'text', source: 'Normal mode       navigation and editing commands\ni                 enter Insert mode before the cursor\nv                 enter character-wise Visual mode\n:                 enter command-line mode\nEsc               return to Normal mode\n\nIf unsure: press Esc once, then choose the next command.' } },
      { heading: 'Enter Insert mode where the text needs to appear', paragraphs: ['The i command inserts before the cursor and a inserts after it. I and A move to the first non-blank character or end of the current line before inserting. These small distinctions remove unnecessary cursor movements.', 'Use o to open a line beneath the current one and O to open one above. They also enter Insert mode, making them more direct than moving to a line ending, pressing Enter and repairing indentation manually.', 'Insert mode supports ordinary typing and backspace, but Vim is designed around returning to Normal mode between changes. Staying in Insert mode and navigating with arrow keys is possible; it simply leaves most of Vim’s editing vocabulary unavailable.'], code: { label: 'Insert at an intentional position', language: 'text', source: 'i    insert before the cursor\na    append after the cursor\nI    insert at the first non-blank character\nA    append at the end of the line\no    open a new line below\nO    open a new line above\nEsc  finish inserting and return to Normal mode' } },
      { heading: 'Motions describe where a command should act', paragraphs: ['The h, j, k and l keys move left, down, up and right. They are useful for small adjustments, but word, line and search motions cover distance more effectively.', 'w moves to the start of the next word, b moves backwards and e moves to a word ending. The uppercase W, B and E variants treat punctuation-separated text as one whitespace-delimited WORD. Use 0 for the first column, ^ for the first non-blank character and $ for the end of a line.', 'gg moves to the first line and G to the last; a number followed by G moves to that line. Counts prefix most motions: 4j moves down four lines and 3w moves forward three words. This composability matters more than raw typing speed.'], code: { label: 'Navigate by structure rather than repeated keys', language: 'text', source: 'h j k l    left, down, up, right\nw b e      next word, previous word, word end\nW B E      whitespace-delimited WORD motions\n0 ^ $      column zero, first text, end of line\ngg G       first line, last line\n42G        line 42\n%          matching bracket, parenthesis or brace\nf{char}    find character on the current line\nt{char}    move just before that character\n; ,        repeat that find forward or backward' } },
      { heading: 'Operators and motions form Vim’s editing grammar', paragraphs: ['Vim avoids providing a separate command for every editing situation. An operator describes what to do and a motion describes the range. d deletes, c changes and y yanks; combining d with w produces dw, deleting through a word motion.', 'Repeating an operator commonly applies it to the whole line: dd deletes a line, cc changes it and yy yanks it. Counts can apply to either part, so 3dd deletes three lines and d3w deletes across three word motions.', 'Change differs from delete because it enters Insert mode after removing the selected text. Use c when replacement is the intention and d when the next operation remains in Normal mode.'], code: { label: 'Combine one operator with many motions', language: 'text', source: 'd + motion    delete\nc + motion    change, then enter Insert mode\ny + motion    yank (copy)\n\ndw            delete to the next word boundary\nd$ or D       delete to the end of the line\ncw            change the current word from the cursor\ny}            yank to the next paragraph\ndd / cc / yy  operate on the current line\n3dd           delete three lines' } },
      { heading: 'Text objects target the thing around the cursor', paragraphs: ['Text objects let an operator act on a structural unit without first moving to one of its edges. iw means inner word while aw means a word including surrounding separation. The same inner-versus-around distinction applies to quotes, parentheses, brackets and braces.', 'ci" changes the contents inside double quotes while ca" also removes the quotes. di( deletes inside parentheses and ya{ yanks a brace-delimited block including its braces. The cursor only needs to be somewhere inside the object.', 'Text objects are one of the largest steps from using Vim as a keyboard-controlled editor to using its actual editing language. Learn a small set and combine them with d, c and y rather than memorising each combination as an unrelated shortcut.'], code: { label: 'Edit the object, not its coordinates', language: 'text', source: 'iw / aw    inner word / a word\ni" / a"    inside quotes / including quotes\ni( / a(    inside parentheses / including parentheses\ni[ / a[    inside brackets / including brackets\ni{ / a{    inside braces / including braces\n\nciw        change the word under the cursor\nci"        change text inside double quotes\nda(        delete the parenthesised expression\nyi{        yank the contents of a brace-delimited block' } },
      { heading: 'Undo, repeat and paste make changes recoverable', paragraphs: ['Press u in Normal mode to undo and Ctrl-r to redo. Vim groups an Insert-mode session into a change, so returning to Normal mode at sensible points creates useful undo boundaries.', 'The dot command repeats the last change. A change might be ciw followed by replacement text, or an operator and motion. Design a repeatable change once, move to the next target and press . rather than recording the same keystrokes manually.', 'Deleted and changed text is placed in registers as well as yanked text. p pastes after the cursor or below the current line; P pastes before or above. Because deletion replaces the unnamed register, deleting immediately before a paste can overwrite the text you expected to paste.'], code: { label: 'Recover and repeat without retyping', language: 'text', source: 'u         undo\nCtrl-r    redo\n.         repeat the last change\np / P     paste after or before the cursor\nx         delete the character under the cursor\nr{char}   replace one character\nJ         join the next line to the current line\n\nExample: ciwreplacement<Esc>\nMove to another word and press . to repeat the replacement.' } },
      { heading: 'Registers make copy and paste explicit', paragraphs: ['Vim stores text in named and numbered registers. The unnamed register, addressed as ", is used implicitly by ordinary delete, change, yank and paste operations. The 0 register keeps the most recent yank, which is useful after a later deletion has replaced the unnamed register.', 'Prefix an operation with "a through "z to select a named register. "ayy yanks a line into register a and "ap pastes it. Uppercase register names append instead of replacing, so "Ayy appends another line to register a.', 'System clipboard integration depends on the Vim build and environment. When supported, "+y and "+p use the + clipboard register. Check :version or :set clipboard? when clipboard behaviour differs between a terminal, remote host and graphical Vim.'], code: { label: 'Choose which stored text to use', language: 'text', source: '"0p       paste the most recently yanked text\n"ayy      yank the current line into register a\n"ap       paste register a\n"Ayy      append the current line to register a\n"_d       delete into the black-hole register\n"+y       yank to the system clipboard when supported\n"+p       paste from the system clipboard when supported\n:registers inspect register contents' } },
      { heading: 'Search is also a navigation system', paragraphs: ['Press / to search forwards and ? to search backwards. Enter submits the pattern, n moves to the next match in the same search direction and N moves in the opposite direction. * searches forwards for the word under the cursor and # searches backwards.', 'Search patterns use Vim’s regular-expression syntax, which differs in places from regular expressions used by Java or JavaScript. Start with literal searches, then use :help pattern when grouping, boundaries or escaping behaves unexpectedly.', 'Substitution uses the shape :[range]s/pattern/replacement/[flags]. Without a range it changes the current line. % selects the whole file, g replaces every match on each selected line and c asks for confirmation.'], code: { label: 'Find and replace without losing control', language: 'text', source: '/account       search forwards\n?account       search backwards\nn / N          next / previous match\n* / #          search for the word under the cursor\n:nohlsearch    clear search highlighting\n\n:s/old/new/       replace first match on this line\n:s/old/new/g      replace every match on this line\n:%s/old/new/g     replace every match in the file\n:%s/old/new/gc    confirm each replacement' } },
      { heading: 'Files, buffers and windows are different things', paragraphs: ['A file is data on disk. A buffer is Vim’s in-memory representation of a file, which may contain unsaved changes. A window is a viewport showing a buffer, and a tab page is a layout containing one or more windows. Confusing these concepts makes commands such as :q and :bnext appear unpredictable.', ':w writes the current buffer, :q closes the current window and :wq performs both. :q! abandons unsaved changes in that buffer, so use it deliberately. :e path opens a file in the current window.', ':ls lists buffers, :bnext and :bprevious move between them, and :buffer name selects one. :split and :vsplit create horizontal and vertical windows; Ctrl-w followed by h, j, k or l moves between them.'], code: { label: 'Manage the editor without fighting it', language: 'text', source: ':w                 write the current buffer\n:q                 close the current window\n:wq or ZZ          write and close\n:q!                abandon changes and close\n:e path            edit a file\n:ls                list buffers\n:bnext / :bprevious move through buffers\n:split / :vsplit   split the current window\nCtrl-w h/j/k/l     move between windows\n:qa                close all windows\n:qa!               abandon changes and close everything' } },
      { heading: 'Visual mode, indentation and code editing cover the next layer', paragraphs: ['v begins character-wise Visual mode, V selects whole lines and Ctrl-v begins blockwise Visual mode. Move to extend the selection, then apply an operator. Visual mode is helpful while learning, although an operator and text object is often faster once the target can be described.', 'The > and < operators indent and outdent; >> and << apply them to a line. = asks Vim to reindent a range according to its filetype rules, and gg=G reindents the whole file. Whether that produces useful Scala formatting depends on the configured indentation support—it is not a replacement for the project formatter.', 'Macros record Normal-mode commands into a register. qa begins recording into register a, q stops and @a replays it. They are effective for a repeated edit that is too irregular for substitution, but the dot command is simpler for one repeatable change.'], code: { label: 'Select, format and replay', language: 'text', source: 'v          character-wise Visual mode\nV          line-wise Visual mode\nCtrl-v     blockwise Visual mode\n> / <      indent / outdent a motion or selection\n>> / <<    indent / outdent the current line\n=          reindent a motion or selection\ngg=G       reindent the whole buffer\n\nqa         record a macro into register a\nq          stop recording\n@a         replay register a\n@@         replay the most recent macro' } },
      { heading: 'Use Vim’s own help instead of memorising everything', paragraphs: ['The essential skill is forming commands from a small grammar, not remembering a catalogue of shortcuts. Start with modes, useful motions, d/c/y, text objects, undo, dot and search. Add registers, windows and macros when a real editing task creates the need.', ':help opens the manual and :help followed by a command goes to that subject. Some keys need notation: :help CTRL-W, :help text-objects and :help :substitute locate the window command, concept and command-line command respectively.', 'Run vimtutor in a terminal for an interactive introduction. Keep configuration modest while learning so advice and help match the editor in front of you. Add mappings only after understanding the operation they replace; otherwise a personalised setup can conceal the transferable Vim language.'], bullets: ['Press Esc when the current mode is unclear', 'Think operator plus motion or text object', 'Use u, Ctrl-r and . before manually repairing a change', 'Prefer search and structural motions to repeated h, j, k and l', 'Understand buffers and windows before installing navigation plugins', 'Use :help and vimtutor as part of normal learning'] },
    ],
  },
  {
    slug: 'typed-application-boundaries-in-scala', title: 'Keep application boundaries typed until the edge', category: 'Scala architecture', topic: 'Scala', topics: ['Architecture'], readTime: '13 min read',
    summary: 'Why returning JsValue from a service and hiding data shapes behind aliases can weaken a Scala application—and how to keep Play HTTP, domain and persistence contracts explicit.',
    sections: [
      { heading: 'A boundary should explain what crosses it', paragraphs: ['A method signature is one of the fastest ways to understand a Scala system. It should say what the caller must provide, what successful result can be produced and which expected failures need handling. When the signature exposes only String, tuple-heavy aliases or JsValue, much of that information has moved into the implementation.', 'This matters most at application boundaries: HTTP input entering a Play application, an application service invoking domain behaviour, a repository loading stored data or an external API returning a response. Each boundary has a representation and a set of guarantees. Treating them as the same model can make the first implementation shorter while making later changes harder to locate.', 'A useful default is to parse untrusted data at the edge, work with meaningful Scala types inside the application and serialize the result when it leaves. This is a design direction rather than a demand for a separate model in every directory.'], code: { label: 'Keep each contract visible', language: 'text', source: 'HTTP request\n    ↓ Play Reads and request validation\nTransport request\n    ↓ translation and domain construction\nApplication command\n    ↓ service and domain behaviour\nTyped application result\n    ↓ response mapping and Play Writes\nHTTP response' } },
      { heading: 'JsValue is a transport representation, not a domain result', paragraphs: ['Play’s JsValue is useful because it can represent any valid JSON value. That flexibility is also why it is a weak contract for most application services. Future[JsValue] says that an asynchronous JSON value will arrive; it does not say which fields exist, what they mean, whether the operation can be rejected or which shape represents success.', 'To understand such a method, an engineer has to find the implementation, identify the value passed to Json.toJson, locate the selected Writes and check whether later code modifies the JSON. The compiler cannot tell a caller that an expected field was renamed or that two successful shapes are possible.', 'Returning JSON also couples otherwise reusable application logic to Play. A scheduled process, integration test or another adapter must now understand an HTTP representation even when it only needs the account or decision produced by the operation.'], code: { label: 'A service contract that hides its result', language: 'scala 2.13 / Play', source: 'type ServiceResponse = JsValue\n\nfinal class AccountService(repository: AccountRepository) {\n  def find(id: String): Future[ServiceResponse] =\n    repository.find(id).map { account =>\n      Json.toJson(account)\n    }\n}\n\n// Is a missing account null, an empty object, an error object\n// or a failed Future? The signature cannot answer.' } },
      { heading: 'Return the application result the caller needs', paragraphs: ['A stronger service accepts validated inputs and returns a type describing the operation. A domain identifier prevents unrelated strings from being interchanged. A sealed error type names expected negative outcomes. A result case class states the successful data without committing it to JSON field names.', 'Future and Either represent different concerns. Future carries asynchronous completion or operational failure. Either carries an expected application decision. Future[Either[FindAccountError, AccountSummary]] is more verbose than Future[JsValue], but each branch now has a meaning the compiler and caller can see.', 'The service result does not have to expose the entire persisted entity. Return the information promised by this operation. A smaller result also reduces the chance that adding a database field accidentally expands the HTTP response.'], code: { label: 'Describe success and expected failure explicitly', language: 'scala 2.13', source: 'final case class AccountId private (value: String) extends AnyVal\n\nsealed trait FindAccountError\nobject FindAccountError {\n  final case class NotFound(id: AccountId) extends FindAccountError\n  case object AccessDenied extends FindAccountError\n}\n\nfinal case class AccountSummary(\n  id: AccountId,\n  name: AccountName,\n  balance: BigDecimal\n)\n\ntrait AccountService {\n  def find(\n    id: AccountId\n  ): Future[Either[FindAccountError, AccountSummary]]\n}' } },
      { heading: 'Translate the result at the HTTP boundary', paragraphs: ['The controller or an HTTP-specific presenter should translate the application result into status codes and response bodies. This is where NotFound becomes 404, AccessDenied becomes 403 and AccountSummary becomes the public JSON representation.', 'Keeping that translation at the boundary does not require a large controller. A response mapper can own the conversion when it is reused or complicated. The architectural point is that this component is explicitly part of the HTTP adapter, while the application service remains unaware of Result, JsValue and HTTP status codes.', 'This split makes tests more focused. Service tests assert typed results. Controller tests assert parsing, status codes and JSON. A change to an API field does not require rewriting domain assertions, and a new non-HTTP caller can reuse the service without decoding its answer.'], code: { label: 'Make HTTP translation an explicit operation', language: 'scala 2.13 / Play', source: 'final case class AccountResponse(\n  id: String,\n  name: String,\n  balance: BigDecimal\n)\n\nobject AccountResponse {\n  implicit val writes: OWrites[AccountResponse] = Json.writes\n\n  def from(account: AccountSummary): AccountResponse =\n    AccountResponse(\n      id = account.id.value,\n      name = account.name.value,\n      balance = account.balance\n    )\n}\n\ndef render(result: Either[FindAccountError, AccountSummary]): Result =\n  result match {\n    case Right(account) => Ok(Json.toJson(AccountResponse.from(account)))\n    case Left(FindAccountError.NotFound(_)) => NotFound\n    case Left(FindAccountError.AccessDenied) => Forbidden\n  }' } },
      { heading: 'Validate transport structure and domain meaning separately', paragraphs: ['Play Reads answers whether an incoming JSON document has the required transport shape and whether its values can be decoded. Domain construction answers whether those decoded values are meaningful for the operation. Combining the stages into Json.fromJson[DomainEntity] can allow an HTTP codec to become the only protection for domain invariants.', 'A request model can reflect client compatibility, optional fields and naming conventions. Translation then constructs validated values such as AccountName or PositiveAmount. Other entry points use the same constructors rather than duplicating the rules.', 'Avoid repeating every validation in both layers. Structural rules belong in the transport decoder; invariants that must hold regardless of the entry point belong with the domain type or command construction.'], code: { label: 'Move from untrusted JSON to a valid command', language: 'scala 2.13 / Play', source: 'final case class OpenAccountRequest(\n  name: String,\n  openingBalance: BigDecimal\n)\n\nobject OpenAccountRequest {\n  implicit val reads: Reads[OpenAccountRequest] = Json.reads\n}\n\ndef toCommand(\n  request: OpenAccountRequest\n): Either[OpenAccountError, OpenAccount] =\n  for {\n    name <- AccountName.from(request.name)\n      .left.map(OpenAccountError.InvalidName)\n    balance <- OpeningBalance.from(request.openingBalance)\n      .left.map(OpenAccountError.InvalidBalance)\n  } yield OpenAccount(name, balance)' } },
      { heading: 'Type aliases can clarify or conceal', paragraphs: ['A type alias gives another name to an existing type. It can remove repetitive machinery and make a common abstraction easier to read. For example, Result[A] can establish that a group of functions shares Either[ApplicationError, A]. The type parameter and error channel remain visible enough to reason about.', 'An alias becomes a smell when it hides the only definition of the data shape. AccountData might expand to Map[String, Option[(String, BigDecimal)]]. Callers see a domain-sounding name, but the compiler still exposes map keys, tuple positions and optionality rather than named fields. Engineers must repeatedly navigate to the alias to interpret each operation.', 'Named case classes are usually better for records that cross a meaningful boundary. They give fields names, support focused constructors and make changes appear at affected call sites. Use aliases to name established type relationships, not to disguise an anonymous schema.'], code: { label: 'Compare a shorter type with a hidden shape', language: 'scala 2.13', source: '// Useful: the common error context remains clear.\ntype Result[A] = Either[ApplicationError, A]\n\n// Opaque: every position and key needs external knowledge.\ntype AccountData = Map[String, Option[(String, BigDecimal)]]\n\n// Explicit: the contract is visible where it is used.\nfinal case class AccountData(\n  id: AccountId,\n  name: Option[AccountName],\n  balance: BigDecimal\n)' } },
      { heading: 'A Scala 2 alias does not create a distinct domain type', paragraphs: ['In Scala 2.13, type AccountId = String and type PaymentId = String remain the same underlying type. A PaymentId can be supplied to a method expecting AccountId because the aliases are interchangeable. The names improve local readability but do not enforce the distinction they appear to describe.', 'A value class can create a nominal distinction with little allocation overhead in many common uses. A private constructor and smart constructor can also validate the representation. There are restrictions and boxing cases around value classes, so the choice should follow the domain value’s use rather than an assumption that the wrapper is always free.', 'Scala 3 opaque types offer another way to expose a distinct type while using an underlying representation inside the defining scope. During a Scala 2 to Scala 3 migration, preserve construction and serialization behaviour rather than changing representation and compiler in one unexplained step.'], code: { label: 'Make identifiers non-interchangeable', language: 'scala 2.13', source: 'final case class AccountId private (value: String) extends AnyVal\nfinal case class PaymentId private (value: String) extends AnyVal\n\ndef loadAccount(id: AccountId): Future[Option[Account]] = ???\n\nval paymentId: PaymentId = ???\n\n// Does not compile:\n// loadAccount(paymentId)' } },
      { heading: 'Derived JSON is still an external contract', paragraphs: ['Json.writes and Json.format reduce codec boilerplate, but derivation does not make a representation internal. Field names and nested formats still determine the JSON clients receive. Renaming a case-class field or changing an implicit format can alter the API without changing the controller.', 'The risk increases when the same case class is used for HTTP, MongoDB and domain logic. A field added for persistence can leak into the API; an API rename can make old documents unreadable; an optional compatibility field can spread through business code where the value is actually required.', 'Separate models when their compatibility requirements diverge. If they genuinely share the same shape and lifecycle, reuse may be reasonable. Protect that decision with boundary tests using representative JSON and stored documents rather than relying only on case-class construction tests.'], code: { label: 'Read an old field while writing the current response', language: 'scala 2.13 / Play JSON', source: 'implicit val accountReads: Reads[AccountResponse] = (\n  (__ \\ "id").read[String] and\n  ((__ \\ "displayName").read[String] orElse\n    (__ \\ "name").read[String]) and\n  (__ \\ "balance").read[BigDecimal]\n)(AccountResponse.apply _)\n\nimplicit val accountWrites: OWrites[AccountResponse] =\n  Json.writes[AccountResponse]\n\n// Compatibility is deliberate and testable.' } },
      { heading: 'There are legitimate reasons to work in JSON', paragraphs: ['Returning JsValue is appropriate when JSON is the component’s actual responsibility. An HTTP presenter, a proxy that deliberately preserves an external payload, a JSON transformation service or code operating on schemaless stored documents may need to expose the representation directly.', 'The name and module should make that responsibility clear. AccountJsonPresenter returning JsObject communicates something different from AccountService returning ServiceResponse where the alias eventually resolves to JsValue.', 'The design question is not whether Json.toJson appears outside a controller file. It is whether the layer performing serialization owns the external representation, and whether callers that need application behaviour are forced to depend on that representation.'] },
      { heading: 'Review the boundary from its signature outward', paragraphs: ['A boundary is healthy when its signature provides enough information to use it correctly without reading several implementations and aliases. The types should distinguish meaningful inputs, expected failures and successful results. Transport and storage translation should have an identifiable owner.', 'Do not add layers merely to satisfy an architecture diagram. A small Play application may reasonably place response mapping beside the controller and reuse a domain case class for a stable internal endpoint. Add separation where invariants, consumers or change cycles differ.', 'The goal is traceability. An engineer should be able to follow a value from untrusted input, through validated application behaviour, to its public or persisted representation—and know which contract is changing at each step.'], bullets: ['Does the service signature describe the business result without opening its implementation?', 'Does application code import Play JSON or Play Result without owning an HTTP concern?', 'Can expected rejection be distinguished from operational failure?', 'Does a type alias simplify a known abstraction or hide the data shape?', 'Can two semantically different identifiers still be interchanged?', 'Would changing a case-class field silently change JSON or MongoDB data?', 'Could another adapter reuse the service without constructing or decoding JSON?'] },
    ],
  },
  {
    slug: 'long-lived-play-framework-applications', title: 'Common problems in long-lived Play Framework applications', category: 'Play Framework', topic: 'Scala', readTime: '5 min read',
    summary: 'The Play version gets the blame, but the real trouble is often hiding elsewhere.',
    sections: [
      { heading: 'Skipped upgrades add up', paragraphs: ['Miss a few Play, Scala and sbt releases and the eventual jump gets much wider. Plugins vanish, APIs move and an old JDK starts dictating where the service can run.'] },
      { heading: 'Look past the controllers', paragraphs: ['Slow builds, giant integration tests, blocking database calls and muddled service boundaries often hurt more than the framework version itself.'], bullets: ['Find blocking work and check its execution context', 'Treat JSON changes as API changes', 'Reduce global state where it blocks testing', 'Make configuration failures obvious at startup'], code: { label: 'Keep blocking work off Play’s default dispatcher', language: 'scala', source: "def findUser(id: UserId) = Action.async {\n  Future(blocking(repository.find(id)))(databaseEc)\n    .map {\n      case Some(user) => Ok(Json.toJson(user))\n      case None       => NotFound\n    }\n}" } },
      { heading: 'Give yourself checkpoints', paragraphs: ['Map the important dependencies and protect the busiest user journeys before you begin. Upgrade in stages you can run and observe. It is much easier to find a bad change when it travelled alone.'] },
    ],
  },
  {
    slug: 'scala-or-java', title: 'When does Scala make sense over Java?', category: 'Engineering decisions', topic: 'Scala', readTime: '6 min read',
    summary: 'Sometimes Scala earns its keep. Sometimes Java is the more honest choice.',
    sections: [
      { heading: 'Choose for the whole system', paragraphs: ['Language features matter. So do hiring, builds, libraries and the people who will be paged when something breaks. Scala is at its best when the type system and functional style genuinely make a hard problem simpler.'] },
      { heading: 'Your team changes the answer', paragraphs: ['A team already fluent in Scala is making a different choice from a Java team running a conventional Spring estate. Pick the language that leaves the fewest long-term surprises, not the one with the most impressive demo.'], bullets: ['How complicated is the problem?', 'Who will own the code in two years?', 'Do the libraries and frameworks fit?', 'Can the team build, debug and operate it confidently?'], code: { label: 'The same small domain model in each language', language: 'scala / java', source: "// Scala\nfinal case class Payment(id: PaymentId, amount: BigDecimal)\n\n// Java\npublic record Payment(PaymentId id, BigDecimal amount) {}" } },
    ],
  },
  {
    slug: 'technical-code-reviews', title: 'Code reviews that find engineering problems', category: 'Engineering practice', topic: 'Engineering', readTime: '11 min read',
    summary: 'A practical method for reviewing behaviour, types, failure paths, tests, compatibility and production impact without turning every pull request into a style debate.',
    sections: [
      { heading: 'Start with the change the code is meant to make', paragraphs: ['A code review is not a search for lines that look unfamiliar. The first question is what behaviour should be different when the change reaches production. Read the ticket or pull-request description, identify the affected users or systems, and state the expected result in plain language before examining implementation details.', 'A useful description should name the problem, the boundary being changed, the intended behaviour and how it was verified. It should also call out deliberate exclusions. Without that context, a reviewer can check local syntax while missing that the change solves the wrong problem.', 'If the desired behaviour is unclear, that is already a review finding. Ask for the missing decision rather than inferring product rules from the implementation. Code can be internally consistent and still implement an unsupported assumption.'], bullets: ['What changes for a caller, user or operator?', 'Which existing behaviour must remain unchanged?', 'What is deliberately outside this pull request?', 'How can the reviewer reproduce or verify the result?'] },
      { heading: 'Trace inputs to effects and back again', paragraphs: ['Review the complete path affected by the change: input parsing, validation, domain decisions, persistence or external calls, and the response returned to the caller. Defects often live between individually reasonable functions rather than inside one complicated method.', 'For a Play endpoint, check what happens when JSON is malformed, when a domain rule rejects the command, when MongoDB returns no document and when an asynchronous dependency fails. Then follow the successful path far enough to confirm that the intended data is actually stored or returned.', 'Do not assume a familiar method name proves the behaviour. Read the implementation or contract at boundaries where ordering, retries, transactions or serialization matter.'], code: { label: 'Review every result channel at the boundary', language: 'scala 2.13 / Play', source: 'def closeAccount(id: AccountId): Action[AnyContent] = Action.async {\n  service.close(id).map {\n    case Right(account) => Ok(Json.toJson(AccountResponse.from(account)))\n    case Left(AccountNotFound) => NotFound\n    case Left(OutstandingBalance(amount)) =>\n      UnprocessableEntity(Json.obj(\n        "code" -> "outstanding_balance",\n        "amount" -> amount\n      ))\n  }.recover {\n    case _: RepositoryTimeout => ServiceUnavailable\n  }\n}\n\n// Review the domain Left cases and the failed Future separately.' } },
      { heading: 'Use the types to find missing states', paragraphs: ['Scala types expose many review questions directly. Option asks what absence means. Either asks which expected failures exist. A sealed trait asks whether every case is handled. Future asks where work runs and how failure reaches the boundary.', 'Look for weakened information: a domain identifier converted back to String too early, an Either replaced with an exception, or several distinct states compressed into booleans and nullable fields. These changes may compile while making later code less able to enforce the original rules.', 'Also check whether a new type actually protects its invariant. A case class named PositiveAmount provides little safety if any caller can construct it with a negative value. The constructor and available transitions matter more than the name.'], code: { label: 'Check whether the type makes its promise true', language: 'scala 2.13', source: 'final case class PositiveAmount private (value: BigDecimal)\n\nobject PositiveAmount {\n  def from(value: BigDecimal): Either[AmountError, PositiveAmount] =\n    Either.cond(\n      value > 0,\n      PositiveAmount(value),\n      AmountError.MustBePositive(value)\n    )\n}\n\n// Review whether JSON and database code also use from,\n// rather than bypassing the validated construction path.' } },
      { heading: 'Review failure paths as carefully as the happy path', paragraphs: ['Error handling deserves more than confirming that recover exists. Check which failures it catches, what information survives, whether the fallback is valid and whether an unexpected failure can be mistaken for a successful business result.', 'Broad recovery is a common problem. Catching Throwable or converting every repository failure into NotFound hides outages as missing data. A retry can multiply load during an incident. A fallback may return stale data without telling the caller. Each policy needs an explicit reason.', 'For asynchronous Scala code, also inspect blocking work and execution contexts. Wrapping a synchronous database call in Future does not make the call non-blocking; running it on Play’s default dispatcher can reduce capacity for unrelated requests.'], code: { label: 'Keep absence and infrastructure failure distinct', language: 'scala 2.13', source: 'def find(id: AccountId): Future[Either[FindError, Account]] =\n  repository.find(id).map {\n    case Some(account) => Right(account)\n    case None          => Left(FindError.NotFound(id))\n  }\n\n// A failed repository Future remains failed here.\n// The HTTP boundary can log it and return a 5xx response\n// instead of presenting an outage as a missing account.' } },
      { heading: 'Tests should provide evidence for the changed behaviour', paragraphs: ['A review should not count test files or chase an arbitrary coverage percentage. Identify the behaviours introduced, removed or placed at risk, then check whether the tests would fail if those behaviours were implemented incorrectly.', 'Tests are strongest when they control relevant inputs and assert meaningful outputs. A test that only verifies an internal mock call may remain green while the API response, stored document or domain result is wrong. Use unit tests for isolated decisions and integration tests where serialization, dependency injection, persistence or routing is part of the risk.', 'Read the test before trusting its name. Look for assertions that can never fail, fixtures that avoid the new edge case, swallowed asynchronous failures and tests coupled so tightly to implementation that a safe refactor requires rewriting them.'], code: { label: 'Assert the rule rather than the implementation steps', language: 'scala 2.13 / ScalaTest', source: '"close" should "reject an account with an outstanding balance" in {\n  val account = openAccount(balance = BigDecimal("12.50"))\n\n  Account.close(account) shouldBe\n    Left(CloseError.OutstandingBalance(BigDecimal("12.50")))\n}\n\n// This test does not care which helper methods were called.\n// It protects the domain behaviour the change must preserve.' } },
      { heading: 'Treat API and stored-data changes as compatibility work', paragraphs: ['A renamed case-class field can alter derived Play JSON or MongoDB serialization. A stricter validator can reject requests that existing clients still send. Removing a response field may compile cleanly because the consumer lives in another repository.', 'Compare representations rather than only Scala types. Review representative request and response JSON, existing stored documents, default values and the strategy for reading older data. If compatibility is intentionally broken, the pull request should identify the coordinated release or migration that makes it safe.', 'Database indexes and query shapes also belong in the review. A functionally correct query may become expensive at production data volume, while a new unique index may fail to build because existing data violates the constraint.'], code: { label: 'Make a renamed field backward-readable', language: 'scala 2.13 / Play JSON', source: 'implicit val accountReads: Reads[AccountRecord] = (\n  (__ \\ "accountId").read[String] and\n  ((__ \\ "displayName").read[String] orElse\n    (__ \\ "name").read[String])\n)(AccountRecord.apply _)\n\nimplicit val accountWrites: OWrites[AccountRecord] = Json.writes\n\n// Read the old and new field during the transition,\n// but write only the current representation.' } },
      { heading: 'Check how the change will behave in production', paragraphs: ['Reviewers should ask how a failed change will be detected and reversed. New error paths need enough structured context to diagnose them without logging sensitive request bodies. A background operation may need progress and failure visibility. A configuration change should fail clearly at startup rather than much later under traffic.', 'Consider load and concurrency where the code changes shared state, database access or asynchronous work. Check whether calls that were previously sequential are now concurrent, whether timeouts still cover the whole operation and whether a new query can exhaust a connection pool.', 'The appropriate depth depends on risk. A pure formatting helper does not need a rollback plan. A change to authentication, persistence or a heavily used API deserves evidence from integration tests, deployment checks and production monitoring.'], bullets: ['What log or metric shows that the new path is working?', 'Can failures be distinguished from normal rejections?', 'Does the change add blocking work or unbounded concurrency?', 'Can the release be rolled back without corrupting stored data?', 'Which production assumption has not been exercised locally?'] },
      { heading: 'Make comments specific and actionable', paragraphs: ['A review comment should identify the observed issue, explain its impact and distinguish a required correction from an optional suggestion. “I do not like this” gives the author no engineering basis for a decision. “This recovery converts database timeouts into 404 responses, so an outage will look like missing customer data” can be verified and resolved.', 'Use automated formatting and static checks for rules a tool can enforce consistently. Human review time is better spent on behaviour, boundaries, maintainability and operational consequences. Style matters when it obscures meaning, but personal preference should not block an otherwise clear change.', 'Ask questions when context is missing, but do not disguise a demand as a question. Clear severity helps the author respond efficiently: blocker, concern, suggestion or clarification. Review the revision after substantive comments rather than assuming the latest patch still has the same behaviour.'], bullets: ['Blocker: incorrect, unsafe or incompatible behaviour', 'Concern: material risk that needs an answer or change', 'Suggestion: a useful improvement that is not required for this change', 'Question: context needed before the reviewer can judge'] },
      { heading: 'Reviewability begins before the review request', paragraphs: ['Very large pull requests make it harder to hold the behaviour, architecture and edge cases in working memory. Separate mechanical changes, dependency upgrades and behavioural changes where they can be independently built and tested. A sequence of coherent changes is easier to review than one artificially small diff that leaves the system broken between commits.', 'Authors can improve review quality with a concise explanation, focused commits, removed debugging noise and evidence that the relevant checks ran. Reviewers should respond within an agreed window and avoid widening the work into unrelated cleanup.', 'The aim is shared confidence in a production change, not approval as quickly as possible or proof that the reviewer could have written it differently. A useful review leaves the code safer and the engineering decision easier for the team to understand.'] },
    ],
  },
  {
    slug: 'technical-debt-without-a-rewrite', title: 'How to tackle technical debt without rewriting everything', category: 'Technical debt', topic: 'Engineering', readTime: '7 min read',
    summary: 'You probably don’t need a rewrite. You do need a better reason than “the code is messy.”',
    sections: [
      { heading: 'Say what the debt is costing you', paragraphs: ['“This code needs cleaning up” rarely wins an argument for time. “Releases take two days because nobody trusts these tests” might. Tie the debt to slow delivery, incidents, difficult onboarding or a product change you cannot safely make.'] },
      { heading: 'Make room for one safe change', paragraphs: ['Put tests around the behaviour you need to keep, then create a boundary where the new work can sit. Improve the part of the system touched by a real delivery goal instead of opening a cleanup project with no end.'], bullets: ['Measure the friction that keeps coming back', 'Protect the behaviour that matters', 'Reduce coupling at the point of change', 'Ship steps small enough for production'], code: { label: 'Characterise today’s behaviour before refactoring', language: 'java', source: "@Test\nvoid keepsLegacyRoundingBehaviour() {\n  var price = calculator.total(new BigDecimal(\"12.345\"));\n\n  assertEquals(new BigDecimal(\"12.35\"), price);\n}" } },
    ],
  },
  {
    slug: 'safe-java-jdk-upgrades', title: 'Approaching Java and JDK upgrades safely', category: 'Java', topic: 'Java', readTime: '5 min read',
    summary: 'A JDK upgrade should be ordinary maintenance. Here’s how to stop it becoming an event.',
    sections: [
      { heading: 'The runtime reaches further than the code', paragraphs: ['A new JDK can uncover assumptions in libraries, build plugins, container images and production flags. A clean compile is encouraging; it is not proof that the service is ready.'] },
      { heading: 'Build confidence one step at a time', paragraphs: ['Update the tooling, compile cleanly, run tests that represent real behaviour, then watch the service in a production-like environment. Keep unrelated refactoring out of the upgrade.'], bullets: ['Check which framework versions support the JDK', 'Look for removed flags and modules', 'Exercise startup and graceful shutdown', 'Compare memory, latency and CPU under load'], code: { label: 'Make the target JDK explicit in Maven', language: 'xml', source: "<properties>\n  <maven.compiler.release>21</maven.compiler.release>\n</properties>\n\n<plugin>\n  <artifactId>maven-enforcer-plugin</artifactId>\n  <!-- fail early when CI uses the wrong JDK -->\n</plugin>" } },
    ],
  },
  {
    slug: 'maintainable-backend-services', title: 'Why backend services become difficult to change', seoTitle: 'Backend service maintainability: why change gets difficult', category: 'Backend maintainability', topic: 'Engineering', topics: ['Architecture', 'Testing'], readTime: '16 min read',
    summary: 'A technical guide to the boundaries, hidden effects, data compatibility, tests, builds and production feedback that determine whether a backend change is safe or expensive.',
    seoDescription: 'Why backend services become hard to maintain, with Scala and Play examples covering application boundaries, MongoDB, testing, builds and observability.',
    sections: [
      { heading: 'Maintainability is the cost of making a safe change', paragraphs: ['A maintainable service is not necessarily small, new or written in the latest language. It is a service whose behaviour can be located, changed, verified and released without requiring one person to reconstruct its entire history.', 'Line count and code style are weak proxies. A five-hundred-line service can be expensive to change when it has an unreproducible build, undocumented consumers and no useful production evidence. A much larger service can remain workable when its boundaries and feedback loops are clear.', 'Assess maintainability through the path of a real change. How long does it take to find the responsible code, understand the affected contracts, run meaningful tests, deploy the result and determine whether it worked?'], bullets: ['Can a new checkout be built and run?', 'Can the relevant behaviour be found without reading the whole repository?', 'Does the change remain inside a comprehensible boundary?', 'Do tests fail for the mistakes the change could introduce?', 'Can the release be observed and reversed?', 'Is the reason for an unusual constraint available to the next engineer?'] },
      { heading: 'Follow one apparently small change', paragraphs: ['Consider adding displayName to an account response. The visible request sounds small, but the value may pass through Play routing, JSON validation, an application command, a domain model, MongoDB mapping and an external response contract.', 'The change becomes risky when the same case class owns all of those representations. A transport field made optional for compatibility can spread Option through domain code where a name is required. Renaming a persistence field can make existing documents unreadable. A derived JSON writer can change the public API because an internal field was renamed.', 'Draw the path before editing it. The number of layers is not the problem; the difficulty comes from boundaries whose contracts and owners cannot be distinguished.'], code: { label: 'Trace the value and each contract it crosses', language: 'text', source: 'HTTP JSON\n   ↓ Play Reads\nOpenAccountRequest\n   ↓ validated translation\nOpenAccount command\n   ↓ application service\nAccount domain value\n   ↓ persistence mapping\nMongoDB document\n   ↓ presenter / Writes\nAccountResponse JSON\n\nAsk which representation is allowed to change at each arrow.' } },
      { heading: 'Unclear boundaries spread the blast radius', paragraphs: ['Controllers should own HTTP concerns, application services should express application behaviour and repositories should own persistence translation. These are responsibilities, not mandatory folder names. A small service may combine some code while keeping the contracts distinct.', 'Difficulty appears when a service returns JsValue because only the current controller calls it, or when a repository exposes MongoDB query documents through application code. Callers then depend on transport or storage shapes without admitting it in their signatures.', 'Keep meaningful values typed until the boundary that owns serialization. This makes an HTTP rename, storage migration or new adapter a local translation problem rather than a change to every caller.'], code: { label: 'Keep JSON out of the application result', language: 'scala 2.13 / Play', source: '// Transport and persistence concerns are mixed:\ndef find(id: String): Future[JsValue] =\n  collection.find(Json.obj("_id" -> id))\n    .map(document => Json.toJson(document))\n\n// The application contract remains typed:\ndef find(id: AccountId): Future[Either[FindError, Account]] =\n  repository.find(id).map {\n    case Some(account) => Right(account)\n    case None          => Left(FindError.NotFound(id))\n  }\n\n// The controller maps Account to AccountResponse JSON.' } },
      { heading: 'Hidden effects make signatures misleading', paragraphs: ['A method named calculateSummary is difficult to reason about if it also writes a document, calls another service and records an audit event. A reader cannot predict failure, latency or retry behaviour from the apparent calculation.', 'Expose asynchronous work and expected failure in the return type where practical. Keep pure calculations as ordinary functions, then compose persistence and external calls in an application operation whose name and signature acknowledge those effects.', 'Be especially careful with recovery. Converting every failed Future into None hides an unavailable database as missing data. Retrying an undocumented write can duplicate a side effect. A fallback can return stale information without telling the caller.'], code: { label: 'Separate a pure decision from effectful orchestration', language: 'scala 2.13', source: 'def rename(\n  account: Account,\n  name: AccountName\n): Either[RenameError, Account] =\n  Either.cond(!account.isClosed, account.copy(name = name), RenameError.Closed)\n\ndef renameAccount(\n  id: AccountId,\n  name: AccountName\n): Future[Either[RenameError, Account]] =\n  repository.find(id).flatMap {\n    case None => Future.successful(Left(RenameError.NotFound(id)))\n    case Some(account) =>\n      rename(account, name).traverse(updated => repository.save(updated).map(_ => updated))\n  }' } },
      { heading: 'Asynchronous code carries operational assumptions', paragraphs: ['A Future communicates that a result arrives later, but it does not reveal whether the underlying operation blocks, which ExecutionContext runs it or whether the work can be cancelled. Wrapping synchronous database or filesystem work in Future does not make that work non-blocking.', 'Long-lived Play applications can become fragile when blocking calls share the default dispatcher with request processing. A slow dependency then reduces capacity for unrelated endpoints. Execution contexts, timeouts and resource limits are part of the service design.', 'Concurrency changes require the same scrutiny. Replacing sequential calls with Future.sequence may reduce latency for ten bounded items and overwhelm a dependency for ten thousand. The service needs an explicit capacity policy, not only asynchronous syntax.'] },
      { heading: 'Data compatibility outlives the current code', paragraphs: ['Stored documents and external consumers survive individual application releases. A case-class field rename may compile cleanly while changing derived Play JSON or MongoDB serialization. A new validator may reject requests that existing clients still send.', 'Review representative stored data as well as Scala types. Define how old documents are read, whether new code writes only the current representation and when compatibility logic can be removed. Make defaults deliberate; silently manufacturing a value can hide a migration gap.', 'Indexes and query shapes belong in the same review. A functionally correct query can become the most expensive part of the change at production data volume, while a new unique index can fail because old data already violates the proposed constraint.'], code: { label: 'Read an older field while writing the current representation', language: 'scala 2.13 / Play JSON', source: 'implicit val accountReads: Reads[AccountRecord] = (\n  (__ \\ "accountId").read[String] and\n  ((__ \\ "displayName").read[String] orElse\n    (__ \\ "name").read[String])\n)(AccountRecord.apply _)\n\nimplicit val accountWrites: OWrites[AccountRecord] =\n  Json.writes[AccountRecord]\n\n// Compatibility is visible, testable and removable later.' } },
      { heading: 'A large test suite can still provide weak confidence', paragraphs: ['Test count and coverage do not show whether the important behaviour is protected. A suite can contain hundreds of mock-heavy unit tests while never exercising JSON codecs, dependency injection, database queries or failure translation.', 'A useful unit test protects a decision and tolerates an internal refactor. An integration test exercises a real boundary whose semantics matter. If a repository test mocks the MongoDB collection, it proves how the mock was configured rather than whether the query can round-trip the production document.', 'Read failure output as part of maintainability. Tests that are slow, order-dependent or vague increase the cost of every change. Flakiness teaches engineers to rerun evidence until it agrees with them.'], bullets: ['Which business rules have fast value-based tests?', 'Which transport and persistence contracts are exercised for real?', 'Do asynchronous assertions return or await their Future?', 'Can tests run independently with controlled data?', 'Does a failure identify the responsible boundary?', 'Can safe refactoring occur without rewriting interaction scripts?'] },
      { heading: 'The build is part of the service architecture', paragraphs: ['A readable codebase is still difficult to maintain when only one warm development machine can build it. Record the Scala and JDK versions, sbt version, compiler plugins, private dependencies and configuration required by a clean checkout.', 'Long feedback loops change engineering behaviour. When compilation or tests take too long, developers batch changes, avoid running checks and receive failures after the relevant context has gone. Separate fast local evidence from slower integration work without making the latter optional.', 'Dependency warnings and temporary overrides should have an explanation. An unexplained exclusion can be the only thing preventing an incompatible transitive version; deleting it during routine cleanup can create a runtime failure far from the edit.'], code: { label: 'Establish a reproducible build baseline', language: 'sbt shell', source: 'show scalaVersion\nshow javaHome\nshow sbtVersion\nplugins\nshow Compile / scalacOptions\ndependencyTree\nevicted\nclean\nTest / test\n\n// Run from a clean checkout with the same JDK used by CI.' } },
      { heading: 'Production feedback determines diagnosis cost', paragraphs: ['A failed request reported only as “internal error” forces an engineer to infer which boundary failed. Structured logs should carry safe identifiers and operation context, while preserving the original cause for unexpected failures.', 'Metrics and dashboards should answer whether the changed path is used, slow or failing. Correlation between a request, downstream call and database operation shortens investigation far more than adding unrelated log lines everywhere.', 'Observability must reflect expected rejection as well as operational failure. A validation error, missing account and unavailable database are different events. Treating all three as exceptions creates noisy alerts; treating all three as ordinary absence hides incidents.'], code: { label: 'Log once where the operation has useful context', language: 'scala 2.13', source: 'service.rename(id, name).map {\n  case Right(account) => Ok(Json.toJson(AccountResponse.from(account)))\n  case Left(RenameError.NotFound(_)) => NotFound\n  case Left(RenameError.Closed) => UnprocessableEntity\n}.recover {\n  case error: RepositoryUnavailable =>\n    logger.error(s"Rename failed for account ${id.value}", error)\n    ServiceUnavailable\n}' } },
      { heading: 'Ownership gaps become technical constraints', paragraphs: ['A service is difficult to change when nobody can explain which consumers rely on an endpoint, why a workaround exists or who can decide ambiguous domain behaviour. Engineers respond by preserving everything, adding another branch and avoiding deletion.', 'Useful documentation records decisions, contracts, operational procedures and the reason behind surprising constraints. It does not need to narrate every class. Keep information close to the code or workflow it governs and update it when the decision changes.', 'Ownership does not mean one permanent expert. It means there is a reachable person or team responsible for decisions, and knowledge is visible enough that another engineer can take part without an oral history.'] },
      { heading: 'Improve the path of the next real change', paragraphs: ['Do not begin with a rewrite or a repository-wide cleanup. Choose a real product change, recurring failure or dependency constraint and trace its complete path. That provides a reason to improve the boundary currently creating cost.', 'Protect existing behaviour at the narrowest useful level. Separate compatibility work, refactoring and new behaviour where possible. Make one responsibility clearer, run the relevant integration evidence and release a change small enough to observe and reverse.', 'Record what remains difficult. Maintainability improves through repeated reductions in change risk, not through declaring the architecture clean.'], bullets: ['Choose one valuable change or recurring failure', 'Trace input, decisions, effects and externally visible output', 'Identify the boundary creating the most uncertainty', 'Protect the behaviour that must remain', 'Refactor and change behaviour in reviewable steps', 'Deploy with an observable success and rollback condition', 'Leave the next constraint documented and prioritised'] },
      { heading: 'The service should answer the next engineer back', paragraphs: ['A maintainable service is not one that never needs explanation. It gives the next engineer enough evidence to understand a change, enough boundaries to contain it and enough feedback to know whether it worked.', 'The strongest signals are practical: a reproducible build, types that preserve meaning, tests at the boundaries that matter, compatible data changes, direct ownership and production behaviour that can be observed.', 'When those signals are weak, even a small service becomes expensive. When they are strong, a mature backend can continue moving without pretending its history and constraints do not exist.'] },
    ],
  },
  {
    slug: 'typescript-backends-get-complicated', title: 'Where TypeScript backends start to get complicated', category: 'TypeScript', topic: 'TypeScript', readTime: '5 min read',
    summary: 'TypeScript makes a backend approachable. That does not guarantee it will stay simple as the system grows.',
    sections: [
      { heading: 'Types stop at the edges', paragraphs: ['A precise internal type cannot make an incoming request, database row or third-party response trustworthy. Validation still has to happen where untrusted data enters the system.', 'The trouble starts when a codebase treats a compile-time type as proof of runtime behaviour. Make the boundaries explicit and keep the validation close to them.'] },
      { heading: 'A folder structure is not an architecture', paragraphs: ['Controllers, services and repositories can look tidy while responsibilities leak everywhere. Name the job of each part of the system and keep business decisions away from transport and persistence details.'], bullets: ['Validate data at runtime boundaries', 'Keep domain decisions out of route handlers', 'Make asynchronous failures visible', 'Test behaviour rather than framework wiring'], code: { label: 'Narrow unknown input before using it', language: 'typescript', source: "type CreateUser = { email: string }\n\nfunction parseCreateUser(value: unknown): CreateUser {\n  if (typeof value !== 'object' || value === null ||\n      !('email' in value) || typeof value.email !== 'string') {\n    throw new Error('Invalid request body')\n  }\n  return { email: value.email }\n}" } },
    ],
  },
  {
    slug: 'operable-python-services', title: 'Keeping a Python service easy to operate', category: 'Python', topic: 'Python', readTime: '5 min read',
    summary: 'A Python service can be quick to build. The real test is whether another engineer can run and change it safely.',
    sections: [
      { heading: 'Make the environment boring', paragraphs: ['Pin dependencies, document the supported runtime and make local startup predictable. If every machine has a slightly different Python environment, production issues become harder to reproduce than they need to be.'] },
      { heading: 'Be explicit about the service boundary', paragraphs: ['Small Python applications often grow through convenience: another script, another background task, another direct database call. Clear entry points and ownership keep that convenience from becoming confusion.'], bullets: ['Use one repeatable dependency workflow', 'Validate inputs at the edge', 'Separate background work from request handling', 'Log enough context to explain failures'], code: { label: 'Keep domain code behind a small interface', language: 'python', source: "from typing import Protocol\n\nclass UserRepository(Protocol):\n    def find(self, user_id: str) -> User | None: ...\n\ndef load_user(user_id: str, repository: UserRepository) -> User:\n    user = repository.find(user_id)\n    if user is None:\n        raise UserNotFound(user_id)\n    return user" } },
    ],
  },
  {
    slug: 'slow-api-database-problem', title: 'When a slow API is really a database problem', category: 'SQL', topic: 'Databases', readTime: '6 min read',
    summary: 'The endpoint gets blamed first. Often the useful evidence is in the query plan, connection pool or data model.',
    sections: [
      { heading: 'Trace the whole request', paragraphs: ['Measure where the time is spent before changing application code. One slow query, an exhausted connection pool or repeated calls inside a loop can all look like a slow API from the outside.'] },
      { heading: 'Fix the cause, not only the query', paragraphs: ['An index may solve today’s symptom. It may also hide a data-access pattern that will fail again as the dataset grows. Look at the query, the schema and why the application asks for the data in that shape.'], bullets: ['Capture representative query timings', 'Read the execution plan', 'Check connection and transaction behaviour', 'Test with realistic data volume'], code: { label: 'Inspect the plan before adding an index', language: 'sql', source: "EXPLAIN (ANALYZE, BUFFERS)\nSELECT id, created_at, total\nFROM orders\nWHERE customer_id = 42\nORDER BY created_at DESC\nLIMIT 25;\n\nCREATE INDEX CONCURRENTLY idx_orders_customer_created\n  ON orders (customer_id, created_at DESC);" } },
    ],
  },
  {
    slug: 'choosing-nosql-data-model', title: 'Choosing NoSQL does not remove the need for a data model', category: 'NoSQL', topic: 'Databases', readTime: '5 min read',
    summary: 'A flexible store changes the modelling trade-offs. It does not make those trade-offs disappear.',
    sections: [
      { heading: 'Start with access patterns', paragraphs: ['NoSQL design works best when the important reads, writes and consistency needs are understood first. Choosing the database before those patterns are clear often pushes complexity into application code.'] },
      { heading: 'Flexibility still needs discipline', paragraphs: ['Flexible documents can help a system evolve, but mixed shapes and unclear versioning rules make production behaviour difficult to reason about. Decide which flexibility is useful and which invariants still need protection.'], bullets: ['List the busiest access patterns', 'State consistency requirements', 'Plan document versioning and migrations', 'Account for indexes and operational tooling'], code: { label: 'A MongoDB document should reveal ownership and shape', language: 'javascript / MongoDB', source: "{\n  _id: ObjectId('...'),\n  customerId: 'customer-42',\n  status: 'paid',\n  items: [\n    { sku: 'book-1', quantity: 2 }\n  ],\n  schemaVersion: 2\n}\n\ndb.orders.createIndex({ customerId: 1, createdAt: -1 })" } },
    ],
  },
  {
    slug: 'backend-work-on-serverless', title: 'What to check before moving backend work to serverless', category: 'Vercel & serverless', topic: 'Serverless', readTime: '6 min read',
    summary: 'Serverless can remove infrastructure work, but runtime limits and workload shape still matter.',
    sections: [
      { heading: 'Match the runtime to the work', paragraphs: ['Short, stateless request handling is a natural fit. Long-running jobs, heavy startup work and connection-hungry workloads need more care. The platform should simplify the system rather than move its complexity somewhere less visible.'] },
      { heading: 'Design for the limits you actually have', paragraphs: ['Understand execution time, memory, region placement, concurrency and database connections before launch. These are architecture inputs, not details to discover during an incident.'], bullets: ['Measure cold-start sensitivity', 'Plan database connection behaviour', 'Keep background jobs separate where needed', 'Add logs and traces before production'], code: { label: 'A small Nuxt server endpoint for Vercel', language: 'typescript', source: "export default defineEventHandler(async (event) => {\n  const body = await readBody<{ email?: string }>(event)\n\n  if (!body.email) {\n    throw createError({ statusCode: 400, message: 'Email is required' })\n  }\n\n  return await subscribers.add(body.email)\n})" } },
    ],
  },
  {
    slug: 'practical-git-aliases', title: 'Practical Git aliases: shorter commands without hidden surprises', category: 'Git & GitHub', topic: 'Misc', topics: ['Software Delivery'], readTime: '13 min read',
    summary: 'How Git aliases are resolved, where configuration lives, which everyday aliases earn their place and why shortcuts should never conceal destructive repository operations.',
    sections: [
      { heading: 'An alias should remove repetition, not understanding', paragraphs: ['Git aliases give a shorter name to a Git subcommand or, with an exclamation mark, a shell command. A useful alias makes a familiar operation easier to type while leaving its effect recognisable.', 'Aliases are personal workflow tools unless a team deliberately shares and documents them. Build instructions, deployment steps and recovery procedures should not depend on an undocumented alias that only exists on one laptop.', 'Start with commands you already understand and repeat often. An alias is a poor way to learn a complicated rebase or hide a force push behind a friendly verb.'], code: { label: 'Create and inspect a simple alias', language: 'shell / Git', source: 'git config --global alias.st status\ngit config --global alias.co checkout\ngit config --global alias.br branch\n\ngit st\ngit config --global --get-regexp \'^alias\\.\'' } },
      { heading: 'Configuration scope determines who sees it', paragraphs: ['A --global alias is stored in the user configuration and applies across repositories. A local alias is stored for one repository. System configuration is machine-wide and rarely the right home for personal shortcuts.', 'Use git config --show-origin to discover which file supplied a value. The same alias name can be overridden at a narrower scope, so checking only the global file can miss the command Git actually resolves.', 'Repository-local aliases are not automatically shared when someone clones the repository because .git/config is not versioned. If a project needs common scripts, keep ordinary executable commands or documented build-tool tasks in the repository instead.'], code: { label: 'See the active scope and origin', language: 'shell / Git', source: 'git config --global alias.lg "log --oneline --decorate --graph"\ngit config --local alias.review "diff --check"\n\ngit config --show-origin --get-regexp \'^alias\\.\'' } },
      { heading: 'Git aliases are expanded as Git subcommands', paragraphs: ['Without an exclamation mark, the alias value is parsed as arguments following git. alias.last "log -1 HEAD" makes git last behave like git log -1 HEAD.', 'Aliases cannot redefine an existing Git command. Keep names easy to recall and avoid one-letter aliases whose meaning is only visible in old shell history.', 'Quoting occurs twice: once in the shell running git config and later when Git parses the stored alias. Inspect the resulting value after adding anything more complicated than a single subcommand.'], code: { label: 'A small set of readable aliases', language: 'shell / Git', source: 'git config --global alias.last "log -1 --stat"\ngit config --global alias.unstage "restore --staged"\ngit config --global alias.aliases "config --get-regexp ^alias\\."\n\ngit last\ngit unstage path/to/file\ngit aliases' } },
      { heading: 'Make history useful for the question being asked', paragraphs: ['One log alias rarely covers every investigation. A compact graph helps with branch shape; a changed-file summary helps locate a relevant commit; a patch is needed when the exact behaviour matters.', 'Keep decorations and dates visible enough to orient the reader. Do not compress history into an unreadable format merely to fit more commits on screen.', 'Aliases can accept additional arguments. If lg expands to log --oneline --graph, git lg -- path/to/file adds the path restriction after the stored arguments.'], code: { label: 'Two views of repository history', language: 'shell / Git', source: 'git config --global alias.lg "log --graph --decorate --oneline --all"\ngit config --global alias.changed "log --stat --oneline"\n\ngit lg -- src/main/scala\ngit changed -10' } },
      { heading: 'Shell aliases are more powerful and more dangerous', paragraphs: ['A Git alias beginning with ! is executed by a shell from the repository’s top-level directory. It can use pipes, environment variables and several commands, but it also inherits shell quoting and portability concerns.', 'Use a shell function when arguments need to be handled deliberately. Positional parameters and quoting should be tested with spaces and unusual branch names. Once an alias becomes a script, a versioned script with tests and documentation is usually easier to maintain.', 'Never copy an opaque ! alias from the internet and run it in an important repository. Read every command first; the alias has the same filesystem and credential access as the Git process.'], code: { label: 'A shell alias with explicit argument handling', language: 'gitconfig', source: '[alias]\n  recent = !git branch --sort=-committerdate --format="%(committerdate:relative) %(refname:short)"\n  files = "!f() { git diff --name-only \"$1\" \"$2\"; }; f"\n\n# Usage:\n# git recent\n# git files main HEAD' } },
      { heading: 'Prefer safe inspection aliases', paragraphs: ['Status, log, diff, branch listing and configuration inspection are good candidates because they do not change repository history. Shortcuts for restore, reset, clean, force push and branch deletion deserve much more caution.', 'Do not alias a destructive command to a harmless-sounding word. Include the important mode in the alias name, keep confirmation where Git provides it and inspect the target before running it.', 'An alias that saves three characters but makes a rare dangerous operation easier to trigger has negative value. Optimise frequent, recoverable work first.'], bullets: ['Good candidates: status, log, diff, show, branch listing', 'Use care: commit amendments, rebases and worktree changes', 'Avoid obscuring: hard resets, forced updates, clean and destructive deletion'] },
      { heading: 'Shell aliases and Git aliases solve different problems', paragraphs: ['A shell alias can shorten the initial git command and compose with other shell tools. A Git alias travels through Git configuration, appears in git config output and naturally accepts repository-relative Git arguments.', 'Use shell aliases for broader terminal workflows and Git aliases for Git vocabulary. Avoid defining the same name differently in both places; future debugging should not begin by guessing which expansion ran.', 'Aliases are not a replacement for learning the underlying command. Keep git help available and periodically remove shortcuts whose meaning is no longer obvious.'], code: { label: 'Remove or edit an alias cleanly', language: 'shell / Git', source: 'git config --global --unset alias.co\ngit config --global --edit\n\ngit help log\ngit help config' } },
      { heading: 'Treat a useful alias set as a small interface', paragraphs: ['A compact set of stable aliases becomes muscle memory. A catalogue of dozens becomes another command language to forget. Add one when repeated use demonstrates friction, and choose a name that still makes sense six months later.', 'If an alias is essential to a team workflow, promote the underlying operation into a repository script or build task and document it. Personal convenience should not become an invisible project dependency.', 'The best aliases preserve Git’s nouns and effects. They make the next command quicker without making the repository state harder to reason about.'], links: [{ label: 'Official Git configuration documentation', href: 'https://git-scm.com/docs/git-config' }, { label: 'Official Git aliases chapter', href: 'https://git-scm.com/book/en/v2/Git-Basics-Git-Aliases' }] },
    ],
  },
  {
    slug: 'performance-testing-with-k6-and-grafana', title: 'Performance testing with k6 and Grafana: turn load into evidence', category: 'Performance testing', topic: 'Testing', topics: ['Platform & DevOps'], readTime: '18 min read',
    summary: 'How to model representative traffic with Grafana k6, define checks and thresholds, avoid coordinated overload, and correlate latency and errors with application behaviour in Grafana.',
    sections: [
      { heading: 'Begin with a performance question', paragraphs: ['A load test needs a decision to support. Can the account API sustain the expected weekday peak? Does latency recover after a burst? Which resource reaches its limit first? “Run 100 users” is a test configuration, not a useful question.', 'Record the environment, data volume, deployed version and external dependencies. A result from an undersized test environment is still useful when its purpose is explicit, but it should not be presented as production capacity.', 'Agree success criteria before the run. Otherwise a dashboard full of response times invites a favourable interpretation after the result is known.'] },
      { heading: 'k6 scripts describe behaviour and workload separately', paragraphs: ['A k6 default function describes one virtual-user iteration. Options and scenarios describe how iterations are scheduled. Keeping the user flow separate from the load model lets the same behaviour support a smoke, average-load or stress run.', 'Parameterise environment-specific base URLs and credentials without embedding secrets in source. Validate that the target is an authorised test environment before generating load.', 'Keep setup work outside the timed interaction where it does not represent user activity. Large shared setup can also create unrealistic data contention if every virtual user acts on the same record.'], code: { label: 'A small HTTP journey with configuration at the edge', language: 'javascript / k6', source: 'import http from "k6/http"\nimport { check, sleep } from "k6"\n\nconst baseUrl = __ENV.BASE_URL\n\nexport default function () {\n  const response = http.get(`${baseUrl}/api/accounts`, {\n    tags: { operation: "list-accounts" },\n  })\n\n  check(response, {\n    "list succeeds": (result) => result.status === 200,\n  })\n\n  sleep(1)\n}' } },
      { heading: 'Choose an open or closed workload deliberately', paragraphs: ['A closed model keeps a number of virtual users looping; when the system slows, each user completes fewer iterations and the offered request rate falls. This resembles users who wait before taking their next action.', 'An arrival-rate model starts iterations at a configured rate independently of response duration. It is useful when incoming demand does not slow merely because the service is struggling. It also requires enough preallocated and maximum virtual users to sustain the rate.', 'The two models answer different questions. State which one represents the production traffic and watch dropped iterations in arrival-rate scenarios; they indicate that the generator could not start all scheduled work.'], code: { label: 'Model a steady arrival rate with a controlled ramp', language: 'javascript / k6', source: 'export const options = {\n  scenarios: {\n    account_reads: {\n      executor: "ramping-arrival-rate",\n      startRate: 5,\n      timeUnit: "1s",\n      preAllocatedVUs: 20,\n      maxVUs: 100,\n      stages: [\n        { target: 20, duration: "2m" },\n        { target: 20, duration: "10m" },\n        { target: 0, duration: "1m" },\n      ],\n    },\n  },\n}' } },
      { heading: 'Checks protect correctness; thresholds decide pass or fail', paragraphs: ['A fast 500 response is not a successful performance result. Checks record whether responses have the expected status or content while the test continues.', 'A failed check does not by itself make k6 exit unsuccessfully. Thresholds define pass-or-fail criteria over metrics, including the checks rate, error rate and latency percentiles. This distinction matters in CI.', 'Use criteria connected to a service objective or accepted baseline. An average hides slow tail behaviour, so percentiles such as p(95) and p(99) are usually more useful alongside error rate and throughput.'], code: { label: 'Turn expected service behaviour into thresholds', language: 'javascript / k6', source: 'export const options = {\n  thresholds: {\n    http_req_failed: ["rate<0.01"],\n    http_req_duration: ["p(95)<400", "p(99)<800"],\n    checks: ["rate>0.99"],\n    "http_req_duration{operation:list-accounts}": ["p(95)<300"],\n  },\n}' } },
      { heading: 'Representative traffic needs representative data', paragraphs: ['A test that repeatedly reads one cached account may measure a best case. A test that creates unlimited new data may measure database growth rather than the normal workload. Model the mix of reads, writes, identities and hot data observed or expected in production.', 'Generate unique data where writes must not conflict, and decide what cleanup occurs after the run. Avoid making setup itself the unmeasured bottleneck.', 'Think time should represent user pacing when modelling user behaviour. Removing every pause can turn a modest virtual-user count into an accidental maximum-throughput test.'] },
      { heading: 'Tags and custom metrics keep results attributable', paragraphs: ['Aggregate HTTP duration across every endpoint can hide one failing operation behind many fast health checks. Tag requests by stable operation name and apply thresholds to the important sub-metrics.', 'Use custom counters, rates or trends for application outcomes that built-in HTTP metrics cannot express. Keep tag values bounded; tagging every request with a unique identifier creates high-cardinality data that is costly to store and difficult to query.', 'Useful starting metrics include request count, HTTP failure rate and request duration. Add iteration and application metrics only when they answer the performance question.'] },
      { heading: 'Grafana connects load symptoms to system behaviour', paragraphs: ['Stream or store k6 metrics in a supported backend and display them in Grafana alongside application and infrastructure telemetry. A latency increase becomes more useful when it can be aligned with database time, error logs, CPU, memory or connection use.', 'Use a shared run identifier, deployment version and environment label so test and application data can be correlated. Annotate the ramp stages or retain the scenario rate on the same time axis.', 'Dashboards explain a run; thresholds still provide the automated decision. A visually interesting graph should not replace explicit criteria in CI.'], bullets: ['Offered and completed iteration rate', 'HTTP error rate and check failures', 'p(90), p(95) and p(99) latency by operation', 'Dropped iterations and active virtual users', 'Application errors and request correlation', 'Database, runtime and host saturation signals'] },
      { heading: 'Protect the system and the test generator', paragraphs: ['Only run load against systems you own or have explicit permission to test. Coordinate production-shaped runs, set abort conditions and understand which third-party APIs, emails or payments the journey could trigger.', 'The load generator can become the bottleneck. Monitor its CPU, memory and network, especially at high rates or when response bodies are large. Distributed load adds clock, network and coordination considerations rather than automatically producing a truer result.', 'Warm-up can reduce one-off startup noise, but cold behaviour may itself be a requirement. Decide whether startup, steady state, burst recovery or saturation is the subject instead of discarding inconvenient samples.'] },
      { heading: 'Different tests reveal different failure modes', paragraphs: ['A smoke run verifies the script and environment with minimal load. An average-load test checks expected traffic, a stress test explores the capacity boundary, a spike test examines sudden demand and a soak test looks for degradation over time.', 'Do not run every profile on every commit. A small thresholded check can guard an important regression in CI, while longer or higher-volume tests run on an appropriate schedule or before risky releases.', 'Compare like with like: same environment, data scale, configuration and workload. Keep the script and thresholds versioned with the application so a historical result can be explained.'] },
      { heading: 'Performance work ends with a diagnosis or decision', paragraphs: ['When a threshold fails, identify where time and errors accumulated before changing code. A slow API can be blocked on a database query, connection pool, downstream service, execution context or resource limit.', 'Change one material factor, rerun the same workload and compare distributions rather than a single average. Preserve both successful and failed runs; only storing the best result destroys the baseline.', 'A useful performance test produces a defensible statement about one workload in one environment, together with enough correlated evidence to explain the limiting behaviour.'], links: [{ label: 'Grafana k6 scenarios documentation', href: 'https://grafana.com/docs/k6/latest/using-k6/scenarios/' }, { label: 'Grafana k6 metrics', href: 'https://grafana.com/docs/k6/latest/using-k6/metrics/' }, { label: 'Grafana k6 thresholds', href: 'https://grafana.com/docs/k6/latest/using-k6/thresholds/' }, { label: 'Grafana dashboards for k6 results', href: 'https://grafana.com/docs/k6/latest/results-output/grafana-dashboards/' }] },
    ],
  },
  {
    slug: 'when-agile-process-replaces-interaction', title: 'When Agile process replaces interaction, software delivery slows down', category: 'Delivery culture', topic: 'Software Delivery', readTime: '15 min read',
    summary: 'How ceremonies, ticket workflows and delivery metrics become harmful when they replace direct collaboration—and how to recover useful structure without abandoning discipline.',
    sections: [
      { heading: 'Agile did not ask teams to prefer process', paragraphs: ['The Agile Manifesto explicitly values individuals and interactions over processes and tools. The qualification matters: the items on the right still have value, but they should support the human collaboration and working software on the left.', 'Many organisations adopt the visible mechanics—boards, stand-ups, estimation, sprint boundaries and roles—without changing how decisions reach the people building the software. The result can be a highly managed queue with very little agility.', 'The problem is not that a team has a process. It is that following the process becomes safer than solving the problem, even when everyone can see that delivery is stuck.'] },
      { heading: 'Tickets become harmful when they replace conversation', paragraphs: ['A ticket is useful memory: the problem, decision, constraints and acceptance evidence remain available after a conversation. It is a weak substitute for the conversation itself when the work contains uncertainty.', 'When product, design and engineering communicate only by moving a ticket and adding comments, questions wait, assumptions harden and language becomes defensive. A hand-off document grows because the people who need shared understanding are discouraged from speaking directly.', 'Talk first when ambiguity is expensive. Record the resulting decision afterwards. This produces shorter documentation with more meaning than trying to predict every question in advance.'] },
      { heading: 'Ceremonies can consume the interaction they were meant to create', paragraphs: ['A stand-up can reveal a blocker and connect the two people who can resolve it. It fails when every person reports status to a manager while the actual dependency is deferred to another scheduled meeting.', 'Retrospectives become theatre when recurring problems are listed without authority or time to change them. Planning becomes waste when estimates are treated as promises despite new information. Reviews become approval gates rather than opportunities to inspect working software.', 'Keep a ceremony only while it changes a useful decision or enables collaboration. Change its format, frequency or attendance when the purpose can be achieved more directly.'], bullets: ['What decision does this meeting enable?', 'Who needs to interact for that decision?', 'Could the issue be resolved sooner by speaking now?', 'What changes as a result of the ceremony?', 'Would anyone notice if it stopped for a month?'] },
      { heading: 'Process queues turn small questions into lead time', paragraphs: ['A clarification that takes five minutes can wait days when it must move through analysis, refinement, estimation and approval queues. Each queue looks locally organised while the complete change barely moves.', 'Specialist hand-offs also discard context. Product writes requirements for analysis, analysis rewrites them for engineering, engineering sends them to testing and testing returns defects without the original discussion. Every boundary creates inventory and another interpretation.', 'Bring the people needed for one outcome together early. This does not require everyone in every meeting; it means the shortest responsible path between a question and the person able to answer it.'] },
      { heading: 'Activity metrics reward the appearance of delivery', paragraphs: ['Velocity, ticket count and utilisation are tempting because they are easy to count. Once used as targets, teams learn to split work, protect estimates and remain visibly busy rather than reduce the time to a useful production result.', 'A sprint can complete every planned ticket while the feature remains unreleased, unobserved or wrong. Code review queues, flaky tests and deployment delays are delivery problems even when the board says done.', 'Use measures to investigate the system, not rank individuals. Lead time, blocked time, deployment outcomes, recovery and user behaviour can start better questions when interpreted with context. No single number is the team.'] },
      { heading: 'Psychological safety affects technical flow', paragraphs: ['Teams need to say that a requirement is unclear, an estimate is uncertain or a release is unsafe without being treated as obstructive. When the culture rewards certainty, risks remain hidden until they become incidents or missed commitments.', 'Blamelessness does not remove accountability. It makes the system and decision available for examination instead of encouraging people to protect themselves through documentation, approvals and silence.', 'Direct interaction works only when it is respectful. Removing process without building trust can simply give the loudest person more control. Facilitation and written records remain valuable when they help everyone participate.'] },
      { heading: 'Useful process reduces cognitive and coordination cost', paragraphs: ['Automated formatting, repeatable builds, code review and clear release checks are processes that save attention and protect shared work. A written decision record can prevent the same architectural argument returning every month.', 'The test is whether the process makes good work easier. It should encode a lesson, reduce ambiguity or provide fast feedback. It should also have an owner and a route to change when its original constraint disappears.', 'Standardise routine mechanics so people can spend their interaction on product and technical uncertainty. Do not standardise every judgement until nobody close to the code is permitted to make one.'] },
      { heading: 'Recover by following one piece of work end to end', paragraphs: ['Choose a recent change and trace elapsed time from question to production. Record waiting, hand-offs, rework and the points where missing context caused delay. Do this with the people involved rather than turning it into a compliance audit.', 'Remove one queue, combine one hand-off into a conversation or automate one repeated check. Then observe whether the change improves flow and quality. Wholesale process redesign can create another programme while current work remains stuck.', 'Give teams authority within clear boundaries. Fast interaction is ineffective when every material decision still waits for a distant approval whose criteria are unknown.'], code: { label: 'A simple delivery-flow review', language: 'text', source: 'Change requested                     Day 1\nClarification requested               Day 3\nRefinement meeting                    Day 8\nDevelopment started                  Day 12\nProduct assumption corrected         Day 15\nCode complete                        Day 16\nWaiting for test environment          Day 21\nReleased                             Day 24\n\nImplementation time: about 5 days\nElapsed delivery time: 24 days\n\nInvestigate the waiting and lost context, not developer busyness.' } },
      { heading: 'Agility is the ability to learn and respond', paragraphs: ['A team is not agile because its calendar contains sprints. It is agile when new evidence can reach a decision quickly, working software can be changed safely and the people involved can collaborate without navigating an organisational maze.', 'Keep the minimum process that protects quality, coordination and sustainable work. Remove or change the parts that exist only to demonstrate compliance with a framework.', 'The strongest delivery culture combines interaction with engineering discipline: clear ownership, reviewable changes, useful tests, observable releases and people trusted to respond when reality differs from the plan.'], links: [{ label: 'Manifesto for Agile Software Development', href: 'https://agilemanifesto.org/' }, { label: 'Principles behind the Agile Manifesto', href: 'https://agilemanifesto.org/principles.html' }] },
    ],
  },
]

export const getArticle = (slug: string) => articles.find(article => article.slug === slug)
